  if (!sd || !Number.isFinite(ahora)) return r;
  if (_vmObjeto(sd.estados)) {
    for (const k of Object.keys(sd.estados)) {
      const e = sd.estados[k];
      if (!_vmObjeto(e) || !(ahora - Number(e.ultimoMensajeMs || 0) < _vmVence(e.paso))) {
        delete sd.estados[k];
