  const pares = [];
  for (const raw of n.split(' ')) {
    if (!raw || PD_VACIAS.indexOf(raw) >= 0 || PD_MARCAS_FORMA.indexOf(raw) >= 0) continue;
    if (esConsulta && PD_PALABRAS_PRECIO.indexOf(raw) >= 0) continue;
    pares.push({ raw, stem: _pdSingular(raw) });
