// LECTURA DE RESPALDO (solo hasta VM_RESPALDO_HASTA_MS): si el servidor no tiene NADA para el telefono (version 0: nunca se comprometio) y la memoria vieja
// tiene un estado vigente o pedidos suyos, se usan; al comprometer quedan en el servidor y `vmRetirarRespaldo` los borra de la memoria vieja.
function vmSes(from, ahoraMs) {
  const cfg = vmCfg();
  const s = _vmObjeto(cfg.sesion) ? cfg.sesion : {};
  const ahora = Number(ahoraMs);
  const ses = { ok: s.ok === true, version: Number.isInteger(s.version) && s.version >= 0 ? s.version : 0, estados: {}, pedidos: {}, vistos: {}, reservas: null, previo: null, deRespaldo: false };
  const f = _vmCadena(from);
  if (!ses.ok || !_vmClaveValida(f) || !Number.isFinite(ahora)) return ses;
  const copia = (x) => JSON.parse(JSON.stringify(x));
  const bloque = _vmObjeto(s.estado) ? s.estado : null;
  if (bloque) {
    if (_vmObjeto(bloque.estado)) ses.estados[f] = copia(bloque.estado);
    const ps = _vmObjeto(bloque.pedidos) ? bloque.pedidos : {};
    for (const k of Object.keys(ps)) {
      // (al LEER solo se descarta el que tiene una marca de tiempo de mas de 72 h; `vmGuardarPedido` poda tambien los que no la traen)
      if (_vmIdValido(k) && _vmObjeto(ps[k]) && !(Number.isFinite(Number(ps[k].guardadoMs)) && ahora - Number(ps[k].guardadoMs) >= VM_PEDIDOS_MS)) ses.pedidos[k] = copia(ps[k]);
    }
    // Las reservas ya anotadas HOY por este telefono (`{dia, n}`): el tope diario de reservas (`rsDentroDelTope`) lee de aqui; un dia viejo o una forma rara no cuentan.
    if (_vmObjeto(bloque.reservas) && typeof bloque.reservas.dia === 'string' && Number.isInteger(bloque.reservas.n) && bloque.reservas.n >= 0) ses.reservas = { dia: bloque.reservas.dia, n: bloque.reservas.n };
    ses.previo = copia(bloque);
    return ses;
  }
  if (ses.version === 0 && ahora < VM_RESPALDO_HASTA_MS) {
    let viejo = null;
    try { viejo = $getWorkflowStaticData('global').ventaMinima; } catch (e) { viejo = null; }
    if (_vmObjeto(viejo)) {
      if (_vmHay(viejo.estados, f) && _vmObjeto(viejo.estados[f]) && ahora - Number(viejo.estados[f].ultimoMensajeMs || 0) < _vmVence(viejo.estados[f].paso)) {
        ses.estados[f] = copia(viejo.estados[f]);
        ses.deRespaldo = true;
      }
      if (_vmObjeto(viejo.pedidos)) {
        for (const k of Object.keys(viejo.pedidos)) {
          const p = viejo.pedidos[k];
          if (_vmIdValido(k) && _vmObjeto(p) && String(p.from) === f && !(Number.isFinite(Number(p.guardadoMs)) && ahora - Number(p.guardadoMs) >= VM_PEDIDOS_MS)) { ses.pedidos[k] = copia(p); ses.deRespaldo = true; }
        }
      }
      if (ses.deRespaldo) ses.previo = { v: 1, estado: ses.estados[f] || null, pedidos: copia(ses.pedidos) };
    }
  }
  return ses;
}

// Las reservas del dia de este telefono con la forma que lee `rsDentroDelTope` / escribe `rsAnotar` (`sd.reservasDelDia[digitos] = {dia, n}`): un objeto
// de AQUI, nunca el `staticData`. PR-4b: el contador viaja en el bloque del telefono (`reservas`), no en la memoria de n8n. Falla cerrado (sin sesion, sin
// bloque): `rsDentroDelTope` cuenta 0 y el servidor se queda con lo que comprometa `Armar mensajes`.
function vmReservasSd(ses, from) {
  const clave = _vmCadena(from).replace(/\D/g, '');
  const sd = { reservasDelDia: {} };
  if (clave && ses && _vmObjeto(ses.reservas)) sd.reservasDelDia[clave] = { dia: ses.reservas.dia, n: ses.reservas.n };
  return sd;
}

// PR-4b. Lo que contesto «Consumir cupos» (el consumo de los cupos de aviso en el servidor), para quien decide despues:
//   { estado: 'sin_consumo' }   el nodo no corrio (no hubo avisos que armar)
//   { estado: 'ok' }            el servidor concedio (o ya habia concedido, `repetido`): CUENTA EL SERVIDOR, nada local
//   { estado: 'negado', motivo, clave }   `cupo_negado` (agotado, sin tope, datos invalidos): ningun aviso sale
//   { estado: 'falla' }         5xx, timeout, forma rara o un resultado que no es de cupos: fail-open, el aviso sale y se aplica el tope LOCAL DE CAIDA
function vmResultadoCupos() {
  const j = vmPrimero('Consumir cupos');
  if (!j) return { estado: 'sin_consumo' };
  let cuerpo = j.body;
  if (typeof cuerpo === 'string') { try { cuerpo = JSON.parse(cuerpo); } catch (e) { cuerpo = null; } }
  if (Number(j.statusCode) !== 200 || !_vmObjeto(cuerpo)) return { estado: 'falla' };
  if (cuerpo.resultado === 'comprometido' || cuerpo.resultado === 'repetido') return { estado: 'ok' };
  if (cuerpo.resultado === 'cupo_negado') return { estado: 'negado', motivo: _vmCadena(cuerpo.motivo).slice(0, 30), clave: _vmCadena(cuerpo.clave).slice(0, 32) };
  return { estado: 'falla' };
}

// El pedido a guardar, con la ventana de 72 h desde su ultima escritura (`guardadoMs`): se podan los vencidos y, pasado el tope, los mas antiguos
// (el recien escrito nunca). `ped` ya trae `pedidoId`. Devuelve el pedido guardado, o null si no se pudo.
function vmGuardarPedido(ses, ped, ahoraMs) {
  if (!_vmObjeto(ses) || !_vmObjeto(ped) || !_vmIdValido(String(ped.pedidoId || '')) || !Number.isFinite(Number(ahoraMs))) return null;
  const ahora = Number(ahoraMs);
  if (!_vmObjeto(ses.pedidos)) ses.pedidos = {};
  for (const k of Object.keys(ses.pedidos)) {
    const v = ses.pedidos[k];
    if (!v || !(ahora - Number(v.guardadoMs || 0) < VM_PEDIDOS_MS)) delete ses.pedidos[k];
  }
  const id = String(ped.pedidoId);
  ses.pedidos[id] = Object.assign({}, _vmHay(ses.pedidos, id) ? ses.pedidos[id] : {}, ped, { guardadoMs: ahora });
  const claves = Object.keys(ses.pedidos);
  if (claves.length > VM_MAX_PEDIDOS) {
    claves.sort((a, b) => Number(ses.pedidos[a].guardadoMs || 0) - Number(ses.pedidos[b].guardadoMs || 0));
    for (const k of claves.slice(0, claves.length - VM_MAX_PEDIDOS)) delete ses.pedidos[k];
  }
  return ses.pedidos[id];
}

// La clave con que se recuerda un aviso ya enviado cuando el compromiso del estado fallo (`sd.avisosHuerfanos`). El de PEDIDO es por pedidoId; el de COMPROBANTE incluye el medio y el
// resultado del cotejo: un segundo comprobante (otra foto, o el mismo pedido ahora correcto) NO es el mismo aviso huérfano. (Desde el 07/11/2026 el aviso de comprobante es
// UNO por pedido: lo suprime `comprobanteAvisadoMs` del pedido guardado, en `Armar avisos`; esta clave sigue cubriendo solo el compromiso fallido.)
function vmClaveAviso(tipo, pedidoId, mediaId, resultado) {
  const base = _vmCadena(tipo) + ':' + _vmCadena(pedidoId);
  return tipo === 'comprobante' ? base + ':' + _vmCadena(mediaId) + ':' + _vmCadena(resultado) : base;
}

// ¿El mensaje ya se vio segun la memoria vieja? Solo hasta el retiro del respaldo: un reintento de Meta que llega justo al publicar no se responde dos veces.
function vmVistoDeRespaldo(idMensaje, ahoraMs) {
  if (!(Number(ahoraMs) < VM_RESPALDO_HASTA_MS) || !_vmIdValido(idMensaje)) return false;
  let viejo = null;
  try { viejo = $getWorkflowStaticData('global').ventaMinima; } catch (e) { return false; }
  return _vmObjeto(viejo) && vmYaVisto(viejo, idMensaje, ahoraMs);
}

// Despues de comprometer: lo migrado ya esta en el servidor, se borra de la memoria vieja (el telefono y SUS pedidos). Pasado el retiro, se borran
// los tres mapas viejos enteros (nadie los escribe ya). Nunca toca el residuo de PR-4b.
function vmRetirarRespaldo(from, ahoraMs, migrado) {
  let viejo = null;
  try { viejo = $getWorkflowStaticData('global').ventaMinima; } catch (e) { return false; }
  if (!_vmObjeto(viejo)) return false;
  if (!(Number(ahoraMs) < VM_RESPALDO_HASTA_MS)) {
    for (const k of ['estados', 'vistos', 'pedidos', 'reservasDelDia']) delete viejo[k];
    return true;
  }
  if (migrado !== true) return false;
  const f = _vmCadena(from);
  if (_vmObjeto(viejo.estados) && _vmHay(viejo.estados, f)) delete viejo.estados[f];
  if (_vmObjeto(viejo.pedidos)) {
    for (const k of Object.keys(viejo.pedidos)) if (_vmObjeto(viejo.pedidos[k]) && String(viejo.pedidos[k].from) === f) delete viejo.pedidos[k];
  }
  return true;
}

// La atencion del telefono: lo que devolvio la ingesta del entrante si lo trae, y si
// no, lo que dijo `configuracionFlujo`. Ante la duda, normal.
function vmAtencion(rIngesta, cfg) {
  const c = cfg && typeof cfg === 'object' ? cfg : {};
  const a = rIngesta && typeof rIngesta === 'object' && rIngesta.atencion && typeof rIngesta.atencion === 'object'
    ? rIngesta.atencion : null;
  const estados = ['normal', 'operador', 'bloqueado'];
  const estado = a && estados.indexOf(a.estado) >= 0 ? a.estado
    : (estados.indexOf(c.atencionEstado) >= 0 ? c.atencionEstado : 'normal');
  const avisarIngesta = rIngesta && typeof rIngesta === 'object' ? rIngesta.avisarRecepcion : '';
  const avisarCfg = a && a.avisarRecepcion !== undefined ? a.avisarRecepcion : c.atencionAvisarRecepcion;
  const avisar = ['operador', 'bloqueado'].indexOf(avisarIngesta || avisarCfg) >= 0 ? (avisarIngesta || avisarCfg) : '';
  return {
    estado: estado,
    avisar: avisar,
    mensajeFijo: String((a && a.mensajeFijo) || c.atencionMensajeFijo || '').trim(),
    respuestas: Number(a && a.respuestasEnVentana !== undefined ? a.respuestasEnVentana : c.atencionRespuestas) || 0,
    venceEn: String((a && a.ventanaVenceEn) || c.atencionVenceEn || ''),
  };
}

// ¿El telefono empieza con alguno de los prefijos del CSV? Sin prefijos NO se permite
// (responder a un numero extranjero cuesta su tarifa).
function vmPrefijoPermitido(from, csv) {
  const f = vmDigitos(from);
  if (!f) return false;
  const ps = _vmCadena(csv).split(',').map(vmDigitos).filter(Boolean);
  return ps.length > 0 && ps.some((p) => f.startsWith(p));
}

// ---------------------------------------------------------------------------
// Botones y codigos
// ---------------------------------------------------------------------------
// El id de un boton: `tipo|parte|parte…`, hasta 256 caracteres. Devuelve `null` (nunca
// un id recortado) si el tipo o una parte llevan un caracter que no es de la lista
// (`A-Z a-z 0-9 _ . : = ~ + -`), si una parte esta vacia o si el id pasa de 256.
const _VM_TIPO_BOTON = /^[A-Za-z0-9_]{1,20}$/;
