//     resultado: 'cuadra'|'no_cuadra'|'ilegible'|'sin_cotejo'|'sin_qr'|'qr_vencido'|'ya_cotejado'|'simulado'
//       (`simulado` = pedido de PRUEBA con cobro simulado: se rotula PRUEBA y SIMULADO, su cierre no habla del banco
//        y NUNCA lleva la imagen del comprobante, aunque `mediaId` venga)
//       (por defecto: `sin_qr` en `pedido`, `sin_cotejo` en `comprobante`; con
//        `ya_cotejado` NO hay aviso: error `sin_aviso_ya_cotejado`)
//     nombre, telefono (quien escribe), direccion, referencia (solo se muestran en delivery y rol completo)
//     diferencias: [texto]  (solo rol completo)   mediaId: id del medio del comprobante (solo rol completo)
//   tipo `reserva`:
//     reserva:{personas, fecha 'AAAA-MM-DD', hora 'HH:MM', zona, nombre, celebracion, requerimiento}
//     codigo, nombre, telefono
//   tipo `transferencia` (derivación a una persona):
//     motivo (lo que escribió el cliente), nombre, telefono, codigo
//
// CIERRES del detalle. Pedido y comprobante con QR: «Revisen el pago en su banco antes
// de despachar.» Con `resultado: 'sin_qr'`: «El pago se coordina con el cliente al entregar
// o al recoger.» Con `resultado: 'simulado'`: «Pedido de PRUEBA: el cobro fue SIMULADO y no se movió dinero.»
// Reserva y derivación tienen cierres propios, sin la frase del banco.
//
// ERRORES de `avPlan` (arreglo de textos): `tope_avisos_dia`, `sin_destinatarios`,
// `sin_aviso_ya_cotejado`, `tipo_desconocido`, `sin_datos_reserva`, `plantilla_invalida`,
// `sin_plantilla_derivacion`, `plantilla_no_configurada_<evento>` (pedido, reserva, derivacion),
// `sin_aviso_posible`, `orden_invalido_<evento>`, `forma_invalida_<evento>` (reserva, derivacion).
//
// Ítems devueltos: {para, rol, payload, respaldo:null, esPlantilla, clase} con
// `clase` ∈ `plantilla` | `detalle` | `imagen`. La imagen NO cuenta como «el aviso salió».

// La copia local de la red de palabras que el asistente jamás dice (la de `comun.js` manda si existe).
const AV_PROHIBIDAS = /validad|confirmad|pagad[oa]|acreditad|verificad|recibimos\s+tu\s+pago|ya lo prepar|lo (est[aá](n|mos)|estoy) prepar|lo preparamos|te avisa(mos|remos)|en camino|te llama(mos|remos)|te escribir[aá]n|lo consulto|acredit|recib\S{0,40}\s+(tu|el|su|mi|un|este|ese|la|tus|sus|los)\s+(pago|transferencia|dep[oó]sito|abono)s?|lleg[oó]\s+(tu|el|su|mi)\s+(pago|transferencia|dep[oó]sito|abono)|(tu|el|su|mi)\s+(pago|transferencia|dep[oó]sito|abono)s?\s+(ya\s+)?(lleg|ingres|entr)(o|ó|aron)\b|(pago|transferencia|dep[oó]sito|abono)s?\s+(ya\s+|fue\s+|fueron\s+|est[aá]\s+)?(recibid|aprobad|[eé]xitos|realizad|registrad|llegad|ingresad|efectuad)|confirm(amos|ó|o)\s+(tu|tus|su|sus|la|el|lo|los|las)\b|\b(?:est[aá]n?|qued[oó]|queda|quedan|quedaron|fue|fueron|ya)\s+(?:ya\s+)?reservad|reserva\s+((est[aá]|qued[oó])\s+)?(registrad|agendad)|reservamos tu|\b(?:te|le|les|se|lo|la|ya)\s+confirm(?:o|amos|é|ó|aron)\b|gracias\s+por\s+(tu|su|el)\s+(pago|transferencia|dep[oó]sito|abono)s?|\b(lleg|ingres|entr)(o|ó|aron)\s+(tu|tus|el|los|su|sus|mi|la|las)\s+(pago|transferencia|dep[oó]sito|abono|dinero|plata|monto)|\b(tu|tus|el|los|su|sus|mi|la|las)\s+(pago|transferencia|dep[oó]sito|abono|dinero|plata|monto)s?\s+(ya\s+)?(lleg|ingres|entr)(o|ó|aron)\b|\brecib(imos|i|í|ido)\s+(el|la|tu|su)\s+(dinero|plata|monto)|(pago|transferencia|dep[oó]sito|abono|cobro)s?\s+(ya\s+|fue\s+|fueron\s+|est[aá]\s+|qued[oó]\s+|se\s+)?(ya\s+)?(recibid|aprobad|[eé]xitos|realizad|registrad|llegad|ingresad|efectuad|aceptad|completad|procesad|reflejad|comprobad)|\breflej(o|ó)\s+(tu|el|su)\s+(pago|transferencia|dep[oó]sito|abono)|\b(verificamos|comprobamos|validamos|aceptamos|tenemos|vimos|cobramos)\s+(tu|tus|su|sus|el|la)\s+(pago|transferencia|dep[oó]sito|abono|dinero|plata)|\bpago\s+(listo|ok)\b|\b(tu|su|el)\s+pago\s+(ya\s+)?(est[aá]|qued[oó])\s+(ya\s+)?(listo|ok|en\s+orden|bien|correcto|completo|hecho)\b|en\s+orden\s+con\s+(tu|su|el)\s+pago|\bsaldad[oa]s?\b|\b(pedido|cuenta|pago|total|orden|deuda)s?\s+((ya\s+)?(est[aá]n?|qued[oó]|fue|queda)\s+)?(ya\s+)?cancelad[oa]s?\b|\bya\s+nos\s+pag(aste|o|ó|aron)\b|\bgracias\s+por\s+pagar\b|\bya\s+pagaste\W{0,3}\s*(muchas\s+)?gracias|\brecib(imos|i|í|ido)\s+(bs\.?\s*|bob\s*)?\d+([.,]\d+)?\s*(bs|bob|bolivianos)\b|\bconfirm(amos|e|é)\s+que\s+(ya\s+)?pag|(pago|transferencia|dep[oó]sito|abono)s?\s+(ya\s+)?se\s+reflej/i;

const AV_VENTANA_MS = 23.5 * 60 * 60 * 1000; // 23 h 30 min
const AV_TOPE_DIA_DEF = 150;
const AV_UTC_MENOS_4_MS = 4 * 60 * 60 * 1000;
const AV_TIPOS = ['pedido', 'comprobante', 'reserva', 'transferencia'];
const AV_ORDEN_PEDIDO = ['items', 'total', 'modalidad', 'cotejo'];
const AV_ORDEN_AGENDA = ['destinatario', 'cuando', 'detalle', 'codigo'];
const AV_ORDEN_SOLICITUD = ['cliente', 'personas', 'cuando', 'telefono', 'nota'];
const AV_CIERRE_PAGO = 'Revisen el pago en su banco antes de despachar.';
const AV_CIERRE_SIN_QR = 'El pago se coordina con el cliente al entregar o al recoger.';
const AV_CIERRE_QR_VENCIDO = 'El QR de cobro está vencido y no se envió: coordinen el pago con el cliente.';
const AV_CIERRE_SIMULADO = 'Pedido de PRUEBA: el cobro fue SIMULADO y no se movió dinero.';
const AV_CIERRE_RESERVA = 'Es una solicitud: revísenla según sus mesas y respondan al cliente.';
const AV_CIERRE_DERIVACION = 'El cliente también puede escribirles directo con el botón.';
const AV_DIAS = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
const AV_MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
const AV_ENLACE = /(?:https?:\/\/|www\.)\S+|\b(?:wa\.me|t\.me|bit\.ly|goo\.gl|tinyurl\.com)\/\S*|\b[a-z0-9-]+(?:\.[a-z0-9-]+)*\.(?:com|net|org|bo|me|io|co|app|ly|link|info|biz|xyz|site|online)\b(?:\/\S*)?/gi;

// --- Red de palabras y saneo ------------------------------------------------------------------

function avProhibidas() {
  try {
    if (typeof VM_PROHIBIDAS !== 'undefined' && VM_PROHIBIDAS instanceof RegExp) return VM_PROHIBIDAS;
  } catch (e) { /* VM_PROHIBIDAS aún sin declarar: rige la copia local */ }
  return AV_PROHIBIDAS;
}

// Confusables latino/cirílico/griego que se pliegan a ASCII SOLO para comparar (S-1). Las dos cadenas van en paralelo, letra
// por letra. El texto que sale nunca se pliega, y las letras latinas no están en la tabla (un texto legítimo no cambia).
const AV_CONFUSABLES_DE = 'аеорсухіјѕԁһӏ' + 'αεικορτυχνηβı';
const AV_CONFUSABLES_A = 'aeopcyxijsdhl' + 'aeikoptuxvnbi';
const AV_OMITIDO = '[texto omitido]';

/** La forma en que se COMPARA (S-1): NFKC, sin controles C1 ni caracteres de formato, NFD sin marcas, en minúsculas y con los confusables plegados. */
function avCanon(t) {
  return String(t === undefined || t === null ? '' : t).normalize('NFKC').replace(/[\u0080-\u009f]/g, '').replace(/\p{Cf}/gu, '').replace(/[\u115f\u1160\u3164\uffa0\u2800]/g, '')
    .normalize('NFD').replace(/\p{M}/gu, '').toLowerCase()
    .replace(/[Ͱ-ϿЀ-ԯı]/g, (c) => {
      const i = AV_CONFUSABLES_DE.indexOf(c);
      return i < 0 ? c : AV_CONFUSABLES_A.charAt(i);
    });
}

/** La forma canónica sin puntuación: todo lo que no es letra ni número es un espacio. */
function avNorm(t) {
  return avCanon(t).replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

// Las palabras de `s` que caen dentro de una coincidencia de la red, mirando la forma canónica (con puntuación) y la sin
// puntuación, cada una con las palabras unidas por un espacio. `separadores[k]` es el espacio que antecede a la palabra `k`.
function avPalabrasProhibidas(s) {
  const re0 = avProhibidas();
  const base = re0.flags.replace(/[gy]/g, '');
  const partes = s.split(/(\s+)/);
  const palabras = [];
  const separadores = [];
  let sep = '';
  for (let i = 0; i < partes.length; i++) {
    if (i % 2 === 1) { sep = partes[i]; continue; }
    if (partes[i] === '') continue;
    palabras.push(partes[i]);
    separadores.push(sep);
    sep = '';
  }
  const marcadas = palabras.map(() => false);
  const vacias = palabras.map(() => false);
  for (const forma of [avCanon, avNorm]) {
    const spans = [];
    let unido = '';
    palabras.forEach((w, k) => {
      const f = forma(w);
      if (f === '') { spans.push(null); if (forma === avNorm) vacias[k] = true; return; }
      if (unido !== '') unido += ' ';
      spans.push([unido.length, unido.length + f.length]);
      unido += f;
    });
    const re = new RegExp(re0.source, base + 'g');
    let m = re.exec(unido);
    while (m) {
      const a = m.index;
      const b = a + m[0].length;
      spans.forEach((p, k) => { if (p && p[0] < b && p[1] > a) marcadas[k] = true; });
      if (m[0].length === 0) re.lastIndex++;
      m = re.exec(unido);
    }
  }
  // Una palabra sin letras ni números («·», «-») entre dos marcadas se va con ellas: queda UNA marca.
  for (let k = 0; k < palabras.length; k++) {
    if (!marcadas[k]) continue;
    let j = k + 1;
    while (j < palabras.length && vacias[j] && !marcadas[j]) j++;
    if (j < palabras.length && marcadas[j]) for (let x = k + 1; x < j; x++) marcadas[x] = true;
  }
  return { palabras, separadores, marcadas, cola: sep };
}

// Cada PALABRA que forma parte de una coincidencia de la red (en la forma canónica o en la sin puntuación) se cambia por
// «[texto omitido]» (una marca por racha). No se corta ninguna palabra ni se normaliza nada fuera de la coincidencia. Llega a
// un punto fijo: tras reemplazar se vuelve a probar (hasta 3 pasadas) y, si aún coincide, devuelve solo la marca.
function avSinProhibidas(t) {
  let s = String(t === undefined || t === null ? '' : t);
  for (let pasada = 0; pasada < 3; pasada++) {
    const r = avPalabrasProhibidas(s);
    if (!r.marcadas.some(Boolean)) return s;
    let salida = '';
    let enMarca = false;
    r.palabras.forEach((w, k) => {
      if (r.marcadas[k]) {
        if (!enMarca) salida += r.separadores[k] + AV_OMITIDO;
        enMarca = true;
      } else {
        salida += r.separadores[k] + w;
        enMarca = false;
      }
    });
    s = salida + r.cola;
  }
  const re = avProhibidas();
  const rx = new RegExp(re.source, re.flags.replace(/[gy]/g, ''));
  return rx.test(avCanon(s)) || rx.test(avNorm(s)) ? AV_OMITIDO : s;
}

function avDigitos(v) {
  return String(v === undefined || v === null ? '' : v).replace(/\D/g, '');
}

/** Quita, sin regex (tiempo lineal), los espacios y los «·» del principio y del final. */
function avSinBordes(s) {
  const sep = (c) => c === '·' || /\s/.test(c);
  let i = 0;
  let j = s.length;
  while (i < j && sep(s.charAt(i))) i++;
  while (j > i && sep(s.charAt(j - 1))) j--;
  return s.slice(i, j);
}

/** Recorta a `n` puntos de código sin partir un par sustituto (acotado: solo mira los primeros `2n` caracteres). */
function avCortar(s, n) {
  return s.length > n ? Array.from(s.slice(0, n * 2)).slice(0, n).join('') : s;
}

/**
 * Una sola línea limpia: sin saltos ni tabuladores (quedan « · »), sin enlaces («[enlace omitido]»; una abreviatura con punto
 * pegada a la palabra siguiente, como «Nro.123» o «Av.Arce», recibe un espacio: «Nro. 123», «Av. Arce»), sin `{}<>&` ni marcas
 * de formato de WhatsApp (`* _ ~` y la comilla invertida), sin palabras prohibidas (cada palabra afectada, entera, por
 * «[texto omitido]»), sin espacios repetidos y con tope de caracteres. Con `opc.cocina` se quitan además los números largos
 * (teléfonos, cuentas, documentos). Devuelve '' si no queda nada.
 * TIEMPO LINEAL: el texto se recorta a `max * 2` antes de aplicar ninguna expresión regular y otra vez después de NFKC (una
 * ligadura como «㏂» crece 4×), y los bordes « · » se quitan a mano (la forma `(\s*·\s*)+$` tenía retroceso exponencial: 24
 * «· » seguidos tardaban 1,6 s y 90 no terminaban).
 */
function avLimpio(t, max, opc) {
  const tope = (Number.isFinite(max) && max > 0) ? Math.floor(max) : 500;
  let s = avCortar((t === undefined || t === null) ? '' : String(t), tope * 2);
  // NFKC (ancho completo, ligaduras) y sin caracteres de formato, salvo «º» y «ª» (NFKC los cambia por «o» y «a»: «N.º»).
  // Tampoco «…»: NFKC lo cambiaría por «...» y la marca «… y N más» de una lista recortada dejaría de ser la que armó el código.
  s = s.split(/([ºª…])/).map((p, i) => (i % 2 ? p : p.normalize('NFKC'))).join('').replace(/\p{Cf}/gu, '');
  s = avCortar(s, tope * 2);
  // El punto ideográfico («。» U+3002) y el de media anchura («｡» U+FF61) NFKC no los lleva a «.»: se normalizan aquí, antes del filtro.
  s = s.replace(/[。｡]/g, '.');
  s = s.replace(AV_ENLACE, ' [enlace omitido] ');
  s = s.replace(/[\r\n\t\u000b\u000c\u0085\u2028\u2029]+/g, ' · ');
  s = s.replace(/[\u0000-\u001f\u007f-\u009f\u200b-\u200f\u202a-\u202e\u2060\ufeff]/g, '');
  s = s.replace(/[{}<>&*_~`]/g, ' ');
  // Un punto pegado a lo que sigue (letra.letra, letra.número o número.letras) recibe un espacio: así «Nro.123», «Av.Arce» o
  // «dpto.4B» llegan enteros, y «malo.test/x» o «x.ru» no quedan como un enlace que WhatsApp convierta en tocable. Los
  // decimales y las horas («4.50», «12.30», «1.25L») no se tocan.
  s = s.replace(/(?<=[\p{L}\p{M}])(?<![ºª])\.(?=[\p{L}\p{M}\p{N}])(?![ºª])|(?<=\p{N})\.(?=\p{L}{2})/gu, '. ');
  if (opc && opc.cocina) {
    s = s.replace(/\+?\d[\d\s.-]{5,}\d/g, (m) => (m.replace(/\D/g, '').length >= 7 ? '…' : m));
    s = s.replace(/\d{7,}/g, '…');
  }
  // Se colapsan espacios y « · » ANTES de comparar con la red: quitar `*_~` deja huecos que juntan frases («te *avisamos»).
  s = avSinBordes(s.replace(/\s{2,}/g, ' '));
  s = avSinBordes(s.replace(/(?:\s·){2,}/g, ' ·'));
  s = avSinBordes(avSinProhibidas(s).replace(/\s{2,}/g, ' '));
  if (Array.from(s).length > tope) {
    // El corte PUEDE volver a formar una coincidencia de la red («confirmo tubos» recortado a «confirmo tu»): tras cortar se vuelve
    // a sanear, y como la marca es más larga que una palabra corta, se vuelve a cortar (hasta 4 vueltas, siempre acotado).
    for (let vuelta = 0; vuelta < 4; vuelta++) {
      s = Array.from(s).slice(0, tope).join('');
      // Un corte que cae dentro de una marca («[texto omit») se retrocede hasta el corchete que la abre.
      const ab = s.lastIndexOf('[');
      if (ab >= 0 && ab > s.lastIndexOf(']')) s = s.slice(0, ab);
      s = avSinBordes(avSinProhibidas(avSinBordes(s)).replace(/\s{2,}/g, ' '));
      if (Array.from(s).length <= tope) break;
    }
  }
  return avAjustarFinal(s, tope);
}

/** Verdadero si `s` coincide con la red en la forma canónica o en la sin puntuación (la misma comprobación de `avSinProhibidas`). */
function avCoincide(s) {
  const re = avProhibidas();
  const rx = new RegExp(re.source, re.flags.replace(/[gy]/g, ''));
  return rx.test(avCanon(s)) || rx.test(avNorm(s));
}

/**
 * Última garantía de `avLimpio`: el resultado respeta el tope y NO coincide con la red. Si algo falla, se quitan palabras
 * ENTERAS del final hasta que cumpla (y, en el peor caso, devuelve '').
 */
function avAjustarFinal(s, tope) {
  if (Array.from(s).length <= tope && !avCoincide(s)) return s;
  const palabras = s.split(' ');
  while (palabras.length > 0) {
    palabras.pop();
    const t = avSinBordes(palabras.join(' '));
    if (Array.from(t).length <= tope && !avCoincide(t)) return t;
  }
  return '';
}

/** El texto de una variable de plantilla: sin saltos, sin 5+ espacios, con tope (500) y nunca vacío («—»). */
function avParametro(t, max, opc) {
  return avLimpio(t, max === undefined ? 500 : max, opc) || '—';
}

function avPrimerNombre(n, opc) {
  return avLimpio(n, 60, opc).split(' ')[0] || '';
}

// --- Destinatarios ----------------------------------------------------------------------------

function avPrefijos(prefijos) {
  const lista = String(prefijos === undefined || prefijos === null || prefijos === '' ? '591' : prefijos)
    .split(/[,;\s]+/).map(avDigitos).filter(Boolean);
  return lista.length ? lista : ['591'];
}

/** Quita repetidos (queda el rol de menos privilegio), el propio número y lo que no es un teléfono permitido. */
function avUnificar(lista, propio, pref) {
  const porTel = {};
  const out = [];
  for (const x of lista) {
    const tel = avDigitos(x && x.tel);
    if (tel.length < 8 || tel.length > 15) continue;
    if (!pref.some((p) => tel.indexOf(p) === 0)) continue;
    if (propio && tel === propio) continue;
    const rol = (x && x.rol === 'completo') ? 'completo' : 'cocina';
    const nombre = avLimpio(x && x.nombre, 40);
    if (porTel[tel]) {
      if (rol === 'cocina') porTel[tel].rol = 'cocina';
      if (!porTel[tel].nombre) porTel[tel].nombre = nombre;
      continue;
    }
    porTel[tel] = { rol, tel, nombre };
    out.push(porTel[tel]);
  }
  return out;
}

/**
 * `rol:tel[:Nombre]` separados por coma o punto y coma → `[{rol, tel, nombre}]`: únicos, de 8 a 15 dígitos,
 * con prefijo permitido (def. «591») y distintos de `from`. Rol desconocido → `cocina`; un marcador sin
 * número válido (`REEMPLAZAR_…`) se descarta.
 *
 * `incluirPropio` es el INTERRUPTOR SOLO DE ENSAYO (`avisarAlPropioNumero` de «Config base»): con `true` EXACTO, el destinatario
 * igual a `from` no se descarta (un solo teléfono hace de cliente y de restaurante). Es la ÚNICA excepción a «nunca al propio
 * número»; el resto de los filtros (prefijo, 8 a 15 dígitos, unicidad, rol) sigue igual. `construir.mjs` solo deja la clave en
 * `ensayo-demo-a.json`. Cualquier otro valor (ausente, «true» como texto, 1, un objeto) es falso: la regla de producción.
 */
function avDestinatarios(csv, from, prefijos, incluirPropio) {
  const crudos = [];
  const partes = String(csv === undefined || csv === null ? '' : csv).split(/[,;\n]+/);
  for (const tok of partes) {
    const p = tok.split(':').map((x) => x.trim());
    if (!p[0] && p.length < 2) continue;
    let rol = 'cocina';
    let tel = '';
    let resto = [];
    if (p.length === 1) { tel = avDigitos(p[0]); }
    else if (avDigitos(p[0]).length >= 8 && avDigitos(p[1]).length < 8) { tel = avDigitos(p[0]); resto = p.slice(1); }
    else {
      rol = p[0].normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase() === 'completo' ? 'completo' : 'cocina';
      tel = avDigitos(p[1]);
      resto = p.slice(2);
    }
    crudos.push({ rol, tel, nombre: resto.join(':') });
  }
  return avUnificar(crudos, incluirPropio === true ? '' : avDigitos(from), avPrefijos(prefijos));
}

// --- Cargas útiles para la Cloud API ----------------------------------------------------------

function avCuerpoBase(tel, tipo) {
  return { messaging_product: 'whatsapp', recipient_type: 'individual', to: avDigitos(tel), type: tipo };
}

/** Mensaje de plantilla con 4 variables (o las que lleguen), todas saneadas. `null` si el nombre o el teléfono no sirven. */
function avPlantilla(tel, nombre, idioma, params4) {
  const n = String(nombre === undefined || nombre === null ? '' : nombre).trim();
  if (!/^[a-z0-9_]{1,512}$/.test(n) || !avDigitos(tel)) return null;
  const lang = /^[a-z]{2,3}(?:_[A-Za-z]{2})?$/.test(String(idioma || '').trim()) ? String(idioma).trim() : 'es';
  const lista = Array.isArray(params4) ? params4 : [];
  return Object.assign(avCuerpoBase(tel, 'template'), {
    template: {
      name: n,
      language: { code: lang },
      components: [{ type: 'body', parameters: lista.map((p) => ({ type: 'text', text: avParametroConMapa(p) })) }],
    },
  });
}

// Como `avParametro`, pero conserva UN enlace de mapa con la forma exacta de `avEnlaceDeUbicacion` (solo dígitos, armado por el
// código, nunca texto del cliente) cuando va como segmento «mapa: <enlace>» al principio o tras « · » y al final o antes de « · ».
// Los segmentos del cliente ya vienen saneados (todo enlace suyo es «[enlace omitido]»), así que un enlace con esta forma solo
// puede venir del código. Se sustituye por una marca durante el saneo y se repone entero; si la marca no queda exactamente una
// vez, el enlace se descarta (nunca se devuelve un enlace partido).
const AV_MARCA_MAPA = 'ENLACEMAPAOK';
// Sin la marca (o con el enlace descartado): quita «mapa:» colgando, separadores « · » repetidos y los de los bordes.
function avSinMapa(t) {
  return avSinBordes(t.split(AV_MARCA_MAPA).join('').replace(/mapa:\s*(?=$| · )/g, '').replace(/(?:\s*·){2,}/g, ' ·').replace(/\s{2,}/g, ' ')) || '—';
}
function avParametroConMapa(t) {
  const s = String(t === undefined || t === null ? '' : t);
  const re = new RegExp('(^| · )mapa: (' + AV_FORMA_ENLACE_MAPA.source.slice(1, -1) + ')(?= · |$)');
  const m = re.exec(s);
  if (!m) return avParametro(s);
  const sin = s.slice(0, m.index) + m[1] + 'mapa: ' + AV_MARCA_MAPA + s.slice(m.index + m[0].length);
  const limpio = avSinBordes(avParametro(sin));
  const partes = limpio.split(AV_MARCA_MAPA);
  if (partes.length !== 2 || limpio.indexOf('mapa: ' + AV_MARCA_MAPA) < 0) return avSinMapa(limpio);
  const salida = partes.join(m[2]);
  return salida.length <= 500 ? salida : avSinMapa(limpio);
}

/** Mensaje de texto libre (solo con ventana abierta). */
function avTexto(tel, cuerpo) {
  const t = Array.from(String(cuerpo === undefined || cuerpo === null ? '' : cuerpo)).slice(0, 4000).join('');
  return Object.assign(avCuerpoBase(tel, 'text'), { text: { preview_url: false, body: t } });
}

function avImagen(tel, mediaId, caption) {
  return Object.assign(avCuerpoBase(tel, 'image'), { image: { id: mediaId, caption: avLimpio(caption, 200) } });
}

// --- Ventana de 24 h y tope diario ------------------------------------------------------------

function avFechaLocal(ms) {
  const d = new Date(ms - AV_UTC_MENOS_4_MS);
  return d.getUTCFullYear() + '-' + String(d.getUTCMonth() + 1).padStart(2, '0') + '-' + String(d.getUTCDate()).padStart(2, '0');
}

/** ¿Escribió el destinatario hace menos de 23 h 30 min? Solo lee. */
function avVentanaAbierta(sd, tel, ahoraMs) {
  const av = sd && sd.av;
  const ult = av && av.ventana ? av.ventana[avDigitos(tel)] : undefined;
  if (typeof ult !== 'number' || !Number.isFinite(ult) || !Number.isFinite(ahoraMs)) return false;
  const d = ahoraMs - ult;
  return d >= -300000 && d < AV_VENTANA_MS;
}

/** Anota que `tel` escribió ahora (nunca hacia atrás). Escribe en `sd.av.ventana`; acota el tamaño. */
function avAnotarEntrante(sd, tel, ahoraMs) {
  const t = avDigitos(tel);
  if (!sd || typeof sd !== 'object' || !t || !Number.isFinite(ahoraMs)) return false;
  if (!sd.av || typeof sd.av !== 'object') sd.av = {};
  if (!sd.av.ventana || typeof sd.av.ventana !== 'object') sd.av.ventana = {};
  const v = sd.av.ventana;
  v[t] = Math.max(typeof v[t] === 'number' ? v[t] : 0, ahoraMs);
  const claves = Object.keys(v);
  for (const k of claves) {
    if (typeof v[k] !== 'number' || ahoraMs - v[k] > 25 * 60 * 60 * 1000) delete v[k];
  }
  const resto = Object.keys(v);
  if (resto.length > 50) {
    resto.sort((a, b) => v[a] - v[b]);
    for (const k of resto.slice(0, resto.length - 50)) delete v[k];
  }
  return true;
}

function avTope(tope) {
  if (tope === undefined || tope === null || tope === '') return AV_TOPE_DIA_DEF;
  const n = Number(tope);
  return Number.isFinite(n) && n >= 0 ? Math.floor(n) : AV_TOPE_DIA_DEF;
}

/** Cuántos mensajes de aviso salieron hoy (hora de La Paz). Solo lee. */
function avContadosHoy(sd, ahoraMs) {
  const dia = sd && sd.av && sd.av.dia;
  if (!dia || dia.fecha !== avFechaLocal(ahoraMs)) return 0;
  return Number.isFinite(dia.n) && dia.n > 0 ? Math.floor(dia.n) : 0;
}

/** ¿Queda cupo hoy? Con el día cambiado el contador vuelve a cero. Solo lee. */
function avDentroDelTopeDiario(sd, ahoraMs, tope) {
  return avContadosHoy(sd, ahoraMs) < avTope(tope);
}

/** Suma `n` (def. 1) mensajes de aviso enviados al contador del día. Escribe en `sd.av.dia`. Devuelve el total de hoy. */
function avContar(sd, ahoraMs, n) {
  if (!sd || typeof sd !== 'object' || !Number.isFinite(ahoraMs)) return 0;
  const sumar = n === undefined ? 1 : Math.max(0, Math.floor(Number(n) || 0));
  if (!sd.av || typeof sd.av !== 'object') sd.av = {};
  const hoy = avFechaLocal(ahoraMs);
  const previo = (sd.av.dia && sd.av.dia.fecha === hoy && Number.isFinite(sd.av.dia.n)) ? Math.max(0, Math.floor(sd.av.dia.n)) : 0;
  sd.av.dia = { fecha: hoy, n: previo + sumar };
  return sd.av.dia.n;
}

// --- Piezas de texto --------------------------------------------------------------------------

function avMonto(n) {
  const v = typeof n === 'string' ? Number(n.replace(',', '.')) : n;
  if (typeof v !== 'number' || !Number.isFinite(v) || v < 0) return '—';
  const r = Math.round(v * 100) / 100;
  return Number.isInteger(r) ? String(r) : r.toFixed(2).replace('.', ',');
}

function avFechaLegible(fecha, hhmm) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(fecha || ''));
  if (!m) return '';
  const a = Number(m[1]); const me = Number(m[2]); const di = Number(m[3]);
  const d = new Date(Date.UTC(a, me - 1, di));
  if (d.getUTCFullYear() !== a || d.getUTCMonth() !== me - 1 || d.getUTCDate() !== di) return '';
  const h = /^(\d{1,2}):(\d{2})$/.exec(String(hhmm || ''));
  const hora = h && Number(h[1]) < 24 && Number(h[2]) < 60 ? ' a las ' + String(h[1]).padStart(2, '0') + ':' + h[2] : '';
  return AV_DIAS[d.getUTCDay()] + ' ' + di + ' de ' + AV_MESES[me - 1] + hora;
}

function avAhoraLegible(ahoraMs) {
  if (!Number.isFinite(ahoraMs)) return '';
  const d = new Date(ahoraMs - AV_UTC_MENOS_4_MS);
  const hhmm = String(d.getUTCHours()).padStart(2, '0') + ':' + String(d.getUTCMinutes()).padStart(2, '0');
  return avFechaLegible(avFechaLocal(ahoraMs), hhmm);
}

function avCodigoCorto(ms) {
  const n = Number.isFinite(ms) ? Math.abs(Math.floor(ms)) % 1679616 : 0;
  return n.toString(36).toUpperCase().padStart(4, '0');
}

function avCotejoTexto(resultado) {
  if (resultado === 'simulado') return 'PRUEBA: cobro SIMULADO, no se movió dinero';
  if (resultado === 'cuadra') return 'comprobante: datos coinciden';
  if (resultado === 'no_cuadra') return 'comprobante: NO coinciden los datos';
  if (resultado === 'ilegible') return 'comprobante ilegible';
  if (resultado === 'sin_qr') return 'sin QR: se cobra al entregar o al recoger';
  if (resultado === 'qr_vencido') return 'QR vencido: coordinar el pago';
  if (resultado === 'sin_guardar') return 'comprobante sin guardar ni cotejar';
  return 'comprobante sin cotejar';
}

// El valor de la VARIABLE de plantilla del cotejo: el cuerpo de la plantilla ya dice «Comprobante: {{N}}», así que se quita la
// palabra repetida («NO coinciden los datos», «datos coinciden», «ilegible»). El texto libre (`avDetalle`) sigue con `avCotejoTexto`.
function avCotejoVariable(resultado) {
  return avCotejoTexto(resultado).replace(/^comprobante:?\s+/i, '');
}

// Teléfono legible, calculado SOLO con los dígitos: «+591 0000 0000» solo si empieza por 591 y tiene 11 dígitos. Con 12 a 15
// dígitos (otro país) «+» y los dígitos sin agrupar (no se conoce el largo del código de país); con 8 a 11 sin prefijo 591 solo
// los dígitos, sin «+» (no se puede saber el país). Devuelve '' si el valor trae letras o no tiene entre 8 y 15 dígitos.
function avTelefonoLegible(v) {
  const crudo = String(v === undefined || v === null ? '' : v);
  if (/\p{L}/u.test(crudo)) return '';
  const d = avDigitos(crudo);
  if (d.length < 8 || d.length > 15) return '';
  if (d.length === 11 && d.slice(0, 3) === '591') return '+591 ' + d.slice(3, 7) + ' ' + d.slice(7);
  return d.length >= 12 ? '+' + d : d;
}

function avModalidadTexto(m) {
  if (m === 'delivery') return 'Delivery';
  if (m === 'recojo') return 'Recojo en el local';
  return '—';
}

function avResultado(tipo, r) {
  const v = String(r === undefined || r === null ? '' : r);
  if (['cuadra', 'no_cuadra', 'ilegible', 'sin_cotejo', 'sin_guardar', 'sin_qr', 'qr_vencido', 'ya_cotejado', 'simulado'].indexOf(v) >= 0) return v;
  return tipo === 'pedido' ? 'sin_qr' : 'sin_cotejo';
}

function avLineas(lineas) {
  const out = [];
  for (const l of (Array.isArray(lineas) ? lineas : [])) {
    if (!l || typeof l !== 'object') continue;
    const c = Math.floor(Number(l.cantidad));
    out.push({ cantidad: Number.isFinite(c) && c >= 1 ? Math.min(c, 999) : 1, nombre: l.nombre, detalle: l.detalle });
    if (out.length >= 30) break;
  }
  return out;
}

/** Orden de variables de la plantilla: una permutación de `base`, en CSV o arreglo; si no lo es, `base`. */
function avOrden(valor, base) {
  if (valor === undefined || valor === null || valor === '') return { orden: base.slice(), valido: true };
  const lista = (Array.isArray(valor) ? valor : String(valor).split(/[,;\s]+/)).map((x) => String(x).trim().toLowerCase()).filter(Boolean);
  const ok = lista.length === base.length && base.every((b) => lista.indexOf(b) >= 0);
  return ok ? { orden: lista, valido: true } : { orden: base.slice(), valido: false };
}

// Clave de configuración → qué plantilla, idioma, forma y orden rige para el evento. NO HAY NOMBRE POR OMISIÓN: una plantilla
// sin configurar no se inventa; el evento falla cerrado (`plantilla_no_configurada_<evento>`) y los nombres reales viven en la
// configuración del negocio, no en el código.
//  - La clave de cada evento (`plantillaPedido`, `plantillaReserva`, `plantillaDerivacion`) manda; SOLO si falta (undefined o
//    null) rige el RESPALDO COMÚN `plantillaAviso` (y para el idioma, `idiomaPlantilla`, si falta el del evento). Una clave
//    vacía ('') es «sin plantilla» para ese evento y no cae al respaldo.
//  - La derivación NO hereda `plantillaReserva` (ni su idioma): exige `plantillaDerivacion` propia o el respaldo común.
//  - La forma de la reserva y de la derivación (`formaPlantillaReserva`, `formaPlantillaDerivacion`) es `cita` (4 variables:
//    destinatario, cuándo, detalle, código; la de por omisión) o `pedido` (las 4 variables de la plantilla de pedido, ver
//    `avVariablesDePedidoForma`); un valor que no es ninguna de las dos cae a `cita` y se anota `forma_invalida_<evento>`.
// `rol` (solo 'completo', solo en la reserva): las claves `*ReservaCompleto` pisan, una por una, las de la reserva.
function avConfigPlantilla(tipo, c, errores, rol) {
  const texto = (v) => String(v === undefined || v === null ? '' : v).trim();
  const falta = (v) => v === undefined || v === null;
  const elegir = (propia) => (falta(propia) ? texto(c.plantillaAviso) : texto(propia));
  const idiomaDe = (propio) => texto(propio) || texto(c.idiomaPlantilla) || 'es';
  let nombre; let idioma; let ordenCsv; let base; let evento; let forma = 'cita';
  const formaDe = (v, nombreClave) => {
    const f = texto(v).toLowerCase();
    if (f === '' || f === 'cita') return 'cita';
    if (f === 'pedido') return 'pedido';
    if (f === 'solicitud' && evento === 'reserva') return 'solicitud';
    errores.push('forma_invalida_' + (nombreClave || evento));
    return 'cita';
  };
  if (tipo === 'pedido' || tipo === 'comprobante') {
    evento = 'pedido';
    nombre = elegir(c.plantillaPedido);
    idioma = idiomaDe(c.idiomaPlantillaPedido);
    ordenCsv = c.ordenPedido; base = AV_ORDEN_PEDIDO;
  } else if (tipo === 'reserva') {
    evento = 'reserva';
    nombre = elegir(c.plantillaReserva);
    idioma = idiomaDe(c.idiomaPlantillaReserva);
    forma = formaDe(c.formaPlantillaReserva);
    if (rol === 'completo') {
      if (texto(c.plantillaReservaCompleto)) nombre = texto(c.plantillaReservaCompleto);
      if (texto(c.idiomaPlantillaReservaCompleto)) idioma = texto(c.idiomaPlantillaReservaCompleto);
      if (!falta(c.formaPlantillaReservaCompleto) && texto(c.formaPlantillaReservaCompleto)) forma = formaDe(c.formaPlantillaReservaCompleto, 'reserva_completo');
    }
    // La forma `solicitud` lleva el teléfono del cliente y es SOLO del rol `completo`: para cualquier otro rol (cocina), aunque la configure
    // `formaPlantillaReserva`, degrada a `pedido` (sin teléfono). `rol` ausente = la del evento, sin degradar.
    if (forma === 'solicitud' && rol !== undefined && rol !== 'completo') forma = 'pedido';
    ordenCsv = c.ordenReserva; base = forma === 'pedido' ? AV_ORDEN_PEDIDO : (forma === 'solicitud' ? AV_ORDEN_SOLICITUD : AV_ORDEN_AGENDA);
  } else {
    evento = 'derivacion';
    nombre = elegir(c.plantillaDerivacion);
    idioma = idiomaDe(c.idiomaPlantillaDerivacion);
    forma = formaDe(c.formaPlantillaDerivacion);
    ordenCsv = c.ordenDerivacion; base = forma === 'pedido' ? AV_ORDEN_PEDIDO : AV_ORDEN_AGENDA;
  }
  const o = avOrden(ordenCsv, base);
  if (!o.valido) errores.push('orden_invalido_' + evento);
  const valida = /^[a-z0-9_]{1,512}$/.test(nombre);
  if (nombre && !valida) errores.push('plantilla_invalida');
  return { nombre: valida ? nombre : '', configurada: nombre !== '', evento, idioma, forma, orden: o.orden };
}

// Un ítem compacto: «2 × Taco (sin cebolla)». Lo usan `avItemsCompactos` y las líneas de la plantilla por líneas.
function avPiezaItem(l, opc) {
  const nota = avLimpio(l.detalle, 80, opc);
  return l.cantidad + ' × ' + (avLimpio(l.nombre, 60, opc) || 'ítem') + (nota ? ' (' + nota + ')' : '');
}

// Los ítems compactos («2 × Taco (sin cebolla), 1 × Queso») que caben en `presupuesto` caracteres. Se corta POR ÍTEM: si no
// entran todos, la lista termina en «… y N más» (como `avDetalle`), nunca a mitad de un ítem. '' si ni la marca cabe.
function avItemsCompactos(lineas, opc, presupuesto) {
  const piezas = lineas.map((l) => avPiezaItem(l, opc));
  for (let k = piezas.length; k >= 0; k--) {
    const resto = piezas.length - k;
    const texto = piezas.slice(0, k).join(', ') + (resto > 0 ? (k > 0 ? ', ' : '') + '… y ' + resto + ' más' : '');
    if (texto.length <= presupuesto) return texto;
  }
  return '';
}

// La variable `modalidad` ({{3}} del pedido) por ROL: con la ventana cerrada es lo único del detalle que llega.
//  - `completo`, SIEMPRE (delivery o recojo): la modalidad (en delivery, «a <dirección> (<referencia>)»), quién recibe o
//    retira, su celular, las coordenadas de la ubicación compartida (en su propio segmento: no se cortan) y los ítems
//    compactos;
//  - `cocina`: modalidad + los ítems compactos con sus notas; SIN teléfono, dirección, nombre completo ni coordenadas.
// Sigue siendo UNA variable: sin saltos de línea, saneada como las demás y con el tope de la variable (500). Los segmentos
// del cliente van primero y los ítems ocupan lo que sobra (cortados por ítem, con «… y N más»).
// Nota: depende de que quien la llama termine en `avPlantilla`, que vuelve a sanear la variable (aquí no se garantiza el saneo final).
function avModalidadVariable(d, dest, opc, sinItems) {
  const tope = 500;
  const base = avModalidadTexto(d.modalidad);
  const delivery = d.modalidad === 'delivery';
  let segmentos = [base];
  let mapa = '';
  let posCoord = -1;
  if (dest.rol === 'completo') {
    const dir = delivery ? avLimpio(d.direccion, 160) : '';
    const ref = delivery ? avLimpio(d.referencia, 100) : '';
    const quien = avLimpio(d.nombre, 60);
    const tel = avDigitos(d.telefono);
    const coord = delivery ? avLimpio(d.coordenadas, 60) : '';
    // Con una ubicación válida (dos números, nunca texto del cliente) el enlace al mapa reemplaza a las coordenadas crudas.
    mapa = delivery ? avEnlaceDeUbicacion(d.ubicacion) : '';
    const telLegible = avTelefonoLegible(d.telefono);
    segmentos = [
      base + (dir ? ' a ' + dir : '') + (ref ? ' (' + ref + ')' : ''),
      quien ? (delivery ? 'recibe ' : 'cliente ') + quien : '',
      tel ? 'cel ' + (telLegible || tel) : '',
      coord,
    ].filter(Boolean);
    posCoord = coord ? segmentos.length - 1 : -1;
  }
  // La nota del cliente desde la pagina del catalogo (`notaPedido`) es una nota de cocina: la ven los dos roles (a cocina,
  // sin numeros largos). Va con los segmentos fijos, para que los items se corten antes que ella.
  const nota = typeof d.notaPedido === 'string' ? avLimpio(d.notaPedido, 100, opc) : '';
  if (nota) segmentos.push('nota: ' + nota);
  // El enlace va entero o no va: se prueba en el lugar de las coordenadas y, si con él lo fijo pasa del tope, se conservan las
  // coordenadas. No pasa por `avLimpio` (volvería «[enlace omitido]»); lo demás ya viene saneado por segmento.
  if (mapa) {
    const conMapa = segmentos.slice();
    const seg = 'mapa: ' + mapa;
    if (posCoord >= 0) conMapa[posCoord] = seg; else conMapa.splice(Math.min(3, conMapa.length), 0, seg);
    const fijoMapa = conMapa.join(' · ');
    if (fijoMapa.length <= tope) {
      if (sinItems === true) return fijoMapa;
      const itemsM = avItemsCompactos(avLineas(d.lineas), opc, tope - fijoMapa.length - 3);
      return itemsM ? fijoMapa + ' · ' + itemsM : fijoMapa;
    }
  }
  const fijo = segmentos.join(' · ');
  if (sinItems === true) return avParametro(fijo, tope, opc);
  const items = avItemsCompactos(avLineas(d.lineas), opc, tope - fijo.length - 3);
  return avParametro(items ? fijo + ' · ' + items : fijo, tope, opc);
}

// Reserva y derivación con la FORMA `pedido` (`formaPlantillaReserva` / `formaPlantillaDerivacion`): llenan las cuatro
// variables de la plantilla de pedido («Se registró un pedido en …: Pedido: {{1}}. Total de la comida: {{2}}. Modalidad:
// {{3}}. Comprobante: {{4}}.»), con textos fijos que no afirman nada: una reserva es siempre una SOLICITUD y no hay cobro.
// El texto fijo de la plantilla («Se registró un pedido… antes de despachar») lo pone Meta, no este código.
// Las marcas de una reserva para quien la lee en el local (texto fijo, sin nada del cliente): el grupo de más de `maxPersonasReserva` y el
// día lleno (`topeReservasDia`) YA NO se derivan al cliente: se anotan y el local las revisa.
function avMarcasReserva(r) {
  const m = [];
  if (r && r.grupoGrande === true) m.push('GRUPO GRANDE');
  if (r && r.diaLleno === true) m.push('VARIAS RESERVAS HOY DE ESTE NÚMERO/revisar');
  // Reserva de mañana (antes de `reservaDesde`, dato del negocio): una nota DENTRO del mismo aviso, 0 mensajes extra.
  if (r && typeof r.reservaManana === 'string' && /^\d{2}:\d{2}$/.test(r.reservaManana)) m.push('Reserva de mañana (antes de las ' + r.reservaManana + '): contactar para confirmar o cambiar la hora');
  // C-13 (06/11/2026): una marca de origen ya redactada por quien arma la reserva (`marcaOrigen`) va en el MISMO aviso, en la variable de notas; 0 mensajes extra.
  if (r && typeof r.marcaOrigen === 'string' && avLimpio(r.marcaOrigen, 80)) m.push(avLimpio(r.marcaOrigen, 80));
  return m;
}
function avVariablesDeForma(tipo, d, dest, ahoraMs) {
  const opc = { cocina: dest.rol === 'cocina' };
  if (tipo === 'reserva') {
    const r = (d.reserva && typeof d.reserva === 'object') ? d.reserva : {};
    const p = Math.floor(Number(r.personas));
    const cod = avLimpio(d.codigo, 20);
    const partes = [
      Number.isFinite(p) && p >= 1 ? p + (p === 1 ? ' persona' : ' personas') : 'personas sin indicar',
      avFechaLegible(r.fecha, r.hora) || 'fecha sin indicar',
      avLimpio(r.zona, 40, opc),
    ].filter(Boolean);
    // Las marcas (grupo grande, día lleno, reserva de mañana y origen del anuncio) van en `modalidad` (tope 500) y no en `items` (tope 200): juntas se cortaban a mitad de la nota.
    const marcas = avMarcasReserva(r);
    return {
      items: avParametro('SOLICITUD DE RESERVA' + (cod ? ' ' + cod : '') + ': ' + partes.join(', '), 200),
      total: avParametro('sin cobro', 30),
      modalidad: avParametro('reserva de mesa por confirmar con el cliente' + (marcas.length ? ' — ' + marcas.join(', ') : ''), 500),
      cotejo: avParametro('no aplica', 80),
    };
  }
  const cod = avLimpio(d.codigo, 20) || avCodigoCorto(ahoraMs);
  const motivo = avLimpio(d.motivo, 120, opc);
  // `comprobante: true`: no es una consulta, es la foto de un comprobante que el flujo no pudo revisar porque cambio el modo de cobro.
  const esComprobante = d.comprobante === true;
  if (esComprobante) {
    return {
      items: avParametro('COMPROBANTE ' + cod + (motivo ? ': ' + motivo : ''), 200),
      total: avParametro('sin cobro', 30),
      modalidad: avParametro('el cliente envió un comprobante que no se pudo revisar (cambió el modo de cobro)', 500),
      cotejo: avParametro('no aplica', 80),
    };
  }
  // UNA CONSULTA (07/11/2026, decisión de Andres: mientras WAM no apruebe una plantilla propia, se reescriben las VARIABLES): con el texto fijo de la plantilla de
  // pedido («Se registró un pedido… Pedido: {{1}}…») el local debe leer de entrada que NO es un pedido y qué tiene que hacer: responderle al cliente por WhatsApp.
  return {
    items: avParametro('NO ES UN PEDIDO — consulta ' + cod + ': ' + (motivo || 'el cliente pide hablar con una persona'), 200),
    total: avParametro('sin cobro', 30),
    modalidad: avParametro('responderle por WhatsApp', 500),
    cotejo: avParametro('no aplica', 80),
  };
}

// Reserva con la FORMA `solicitud` (plantilla `solicitud_reserva`, 5 variables). Cada una se recorta por campo para que Meta nunca la
// rechace por largo. Es una SOLICITUD por confirmar: ninguna variable dice «confirmada» (y la red de prohibidas las revisa, `avLimpio`).
// El teléfono del cliente va SOLO al rol `completo`; para `cocina` queda «—» (y sus números largos se quitan de cualquier campo).
function avVariablesSolicitud(d, dest) {
  const opc = { cocina: dest.rol === 'cocina' };
  const r = (d.reserva && typeof d.reserva === 'object') ? d.reserva : {};
  const p = Math.floor(Number(r.personas));
  const cod = avLimpio(d.codigo, 20);
  const nombre = (dest.rol === 'cocina' ? avPrimerNombre(r.nombre || d.nombre, opc) : avLimpio(r.nombre || d.nombre, 60)) || 'cliente';
  const zona = avLimpio(r.zona, 40, opc);
  const cuando = avFechaLegible(r.fecha, r.hora) || 'fecha sin indicar';
  const tel = dest.rol === 'completo' ? avDigitos(d.telefono) : '';
  const extras = avMarcasReserva(r).concat([
    avLimpio(r.celebracion, 120, opc) ? 'Celebración: ' + avLimpio(r.celebracion, 120, opc) : '',
    avLimpio(r.requerimiento, 150, opc) ? 'Pedido especial: ' + avLimpio(r.requerimiento, 150, opc) : '',
  ]).filter(Boolean);
  return {
    cliente: avParametro((cod ? cod + ' · ' : '') + nombre, 90),
    personas: avParametro(Number.isFinite(p) && p >= 1 ? p + (p === 1 ? ' persona' : ' personas') : 'personas sin indicar', 30),
    cuando: avParametro(cuando + (zona ? ', ' + zona : ''), 100),
    telefono: avParametro(tel && tel.length >= 8 && tel.length <= 15 ? (avTelefonoLegible(d.telefono) || tel) : '', 20),
    nota: avParametro(extras.length ? extras.join(' · ') : 'sin datos adicionales', 300),
  };
}

// Las cuatro variables, ya saneadas, por token. `rol` decide cuánto se muestra.
function avVariables(tipo, d, dest, resultado, ahoraMs, forma) {
  const opc = { cocina: dest.rol === 'cocina' };
  if (forma === 'solicitud' && tipo === 'reserva') return avVariablesSolicitud(d, dest);
  if (forma === 'pedido' && (tipo === 'reserva' || tipo === 'transferencia')) return avVariablesDeForma(tipo, d, dest, ahoraMs);
  const nombreDe = (n) => (dest.rol === 'cocina' ? avPrimerNombre(n, opc) : avLimpio(n, 60)) || 'cliente';
  if (tipo === 'pedido' || tipo === 'comprobante') {
    const lineas = avLineas(d.lineas);
    const n = lineas.reduce((a, l) => a + l.cantidad, 0);
    const cod = avLimpio(d.codigo, 20) || '—';
    return {
      items: avParametro((resultado === 'simulado' ? 'PRUEBA · ' : '') + 'N.º ' + cod + (n > 0 ? ' de ' + n + (n === 1 ? ' ítem' : ' ítems') : ''), 60),
      total: avParametro('Bs ' + avMonto(d.total) + (resultado === 'simulado' ? ' (SIMULADO)' : ''), 30),
      modalidad: avModalidadVariable(d, dest, opc),
      cotejo: avParametro(avCotejoVariable(resultado), 80),
    };
  }
  const destinatario = avParametro(dest.nombre || 'equipo', 40);
  if (tipo === 'reserva') {
    const r = (d.reserva && typeof d.reserva === 'object') ? d.reserva : {};
    const p = Math.floor(Number(r.personas));
    const partes = [
      'Reserva ' + (Number.isFinite(p) && p >= 1 ? p + (p === 1 ? ' persona' : ' personas') : '—'),
      nombreDe(r.nombre || d.nombre),
      avLimpio(r.zona, 40, opc),
    ].concat(avMarcasReserva(r)).filter(Boolean);
    return {
      destinatario,
      cuando: avParametro(avFechaLegible(r.fecha, r.hora), 70),
      detalle: avParametro(partes.join(' · '), 200),
      codigo: avParametro(avLimpio(d.codigo, 20), 20),
    };
  }
  const motivo = avLimpio(d.motivo, 120, opc);
  return {
    destinatario,
    cuando: avParametro(avAhoraLegible(ahoraMs), 70),
    detalle: avParametro([d.comprobante === true ? 'Comprobante de cliente (no se pudo revisar)' : 'Consulta de cliente', nombreDe(d.nombre), motivo ? 'Nota del cliente: ' + motivo : ''].filter(Boolean).join(' · '), 200),
    codigo: avParametro(avLimpio(d.codigo, 20) || avCodigoCorto(ahoraMs), 20),
  };
}

// PLANTILLAS POR LÍNEAS (aditivo, 24/10): `plantillasPedidoLineas` = CSV «2:nombre,4:nombre,6:nombre». Cada plantilla trae el
// salto de línea FIJO en su cuerpo y UNA variable por línea de producto; las variables nunca llevan saltos. Sin la clave (vacía o
// ausente) el pedido sale como siempre. Devuelve `{ 2: 'nombre', 4: …, 6: … }` solo con los tamaños válidos.
const AV_TAMANOS_LINEAS = [2, 4, 6];
function avPlantillasLineas(valor) {
  const out = {};
  const partes = String(valor === undefined || valor === null ? '' : valor).split(/[,;]+/);
  for (const tok of partes) {
    const i = tok.indexOf(':');
    if (i < 0) continue;
    const k = Number(tok.slice(0, i).trim());
    const nombre = tok.slice(i + 1).trim();
    if (AV_TAMANOS_LINEAS.indexOf(k) >= 0 && /^[a-z0-9_]{1,512}$/.test(nombre)) out[k] = nombre;
  }
  return out;
}

/** El menor tamaño (2, 4 o 6) que cabe `n` productos; con más de 6 productos, 6 (la última línea dice «… y K más»). */
function avTamanoLineas(n) {
  for (const t of AV_TAMANOS_LINEAS) if (n <= t) return t;
  return AV_TAMANOS_LINEAS[AV_TAMANOS_LINEAS.length - 1];
}

// Las variables de la plantilla por líneas, en su orden fijo: {{1}} pedido y total · {{2}} modalidad por rol (sin ítems) ·
// {{3}}…{{N+2}} un producto por variable («—» en las sobrantes; si sobran productos, la última dice «… y K más») · {{N+3}} cotejo.
function avVariablesLineas(d, dest, resultado, tamano) {
  const opc = { cocina: dest.rol === 'cocina' };
  const lineas = avLineas(d.lineas);
  const n = lineas.reduce((a, l) => a + l.cantidad, 0);
  const cod = avLimpio(d.codigo, 20) || '—';
  const primera = avParametro(
    (resultado === 'simulado' ? 'PRUEBA · ' : '') + 'N.º ' + cod + (n > 0 ? ' de ' + n + (n === 1 ? ' ítem' : ' ítems') : '')
    + '. Total de la comida: Bs ' + avMonto(d.total) + (resultado === 'simulado' ? ' (SIMULADO)' : ''), 120);
  const vars = [primera, avModalidadVariable(d, dest, opc, true)];
  const cuantos = lineas.length;
  for (let k = 0; k < tamano; k++) {
    if (cuantos > tamano && k === tamano - 1) vars.push(avParametro('… y ' + (cuantos - (tamano - 1)) + ' más', 40));
    else if (k < cuantos) vars.push(avParametro(avPiezaItem(lineas[k], opc), 200, opc));
    else vars.push('—');
  }
  // El cuerpo de la plantilla ya dice «Comprobante: {{N+3}}.»: sin la palabra repetida («Comprobante: comprobante: datos coinciden»).
  vars.push(avParametro(avCotejoVariable(resultado), 80));
  return vars;
}

// El enlace al mapa de la ubicación compartida (PR-A 05/10). Se arma SOLO con dos números —nunca con texto del cliente— y por eso NO pasa por
// `avLimpio` (que cambia toda URL por «[enlace omitido]»); a cambio se valida con la forma exacta y se devuelve '' ante cualquier duda: tipos
// que no son número, fuera de rango, no finitos o (0, 0) (el «punto nulo» de un GPS sin fijar). Solo lo usa el detalle de texto del rol `completo`:
// la variable de modalidad de la plantilla (ventana cerrada, rol completo) también lo lleva (`avModalidadVariable`).
const AV_FORMA_ENLACE_MAPA = /^https:\/\/www\.google\.com\/maps\/search\/\?api=1&query=-?\d{1,2}\.\d{6}%2C-?\d{1,3}\.\d{6}$/;
function avEnlaceDeUbicacion(u) {
  if (!u || typeof u !== 'object') return '';
  const lat = u.lat;
  const lng = u.lng;
  if (typeof lat !== 'number' || typeof lng !== 'number' || !Number.isFinite(lat) || !Number.isFinite(lng)) return '';
  if (Math.abs(lat) > 90 || Math.abs(lng) > 180 || (lat === 0 && lng === 0)) return '';
  const url = 'https://www.google.com/maps/search/?api=1&query=' + lat.toFixed(6) + '%2C' + lng.toFixed(6);
  return AV_FORMA_ENLACE_MAPA.test(url) ? url : '';
}

// Detalle completo en texto libre. Cada pieza dinámica pasa por `avLimpio`; el cierre va al final.
function avDetalle(tipo, d, rol, resultado, ahoraMs) {
  const opc = { cocina: rol === 'cocina' };
  const completo = rol === 'completo';
  const lineas = [];
  const nombre = completo ? avLimpio(d.nombre, 60) : avPrimerNombre(d.nombre, opc);
  const tel = avDigitos(d.telefono);
  const cliente = () => {
    if (completo) return 'Cliente: ' + (nombre || 'sin nombre') + (tel ? ' · tel ' + (avTelefonoLegible(d.telefono) || tel) : '');
    return nombre ? 'Cliente: ' + nombre : '';
  };
  let cierre = '';
  if (tipo === 'pedido' || tipo === 'comprobante') {
    const cod = avLimpio(d.codigo, 20) || '—';
    lineas.push(resultado === 'simulado'
      ? 'PEDIDO DE PRUEBA N.º ' + cod + ' (cobro SIMULADO: no se movió dinero)'
      : 'Pedido N.º ' + cod + ' (' + avCotejoTexto(resultado) + ')');
    lineas.push(cliente());
    if (d.modalidad === 'delivery') {
      const dir = completo ? avLimpio(d.direccion, 200) : '';
      const ref = completo ? avLimpio(d.referencia, 120) : '';
      lineas.push('Entrega: delivery' + (dir ? ' a ' + dir : '') + (ref ? ' (' + ref + ')' : ''));
      // Las coordenadas de la ubicación compartida van en su propia línea, solo para el rol completo.
      const coord = completo ? avLimpio(d.coordenadas, 80) : '';
      if (coord) lineas.push(coord.charAt(0).toUpperCase() + coord.slice(1));
      // El enlace al mapa: solo el rol completo y solo con una ubicación válida (de los números, no del texto de `coordenadas`).
      const mapa = completo ? avEnlaceDeUbicacion(d.ubicacion) : '';
      if (mapa) lineas.push('Ver en el mapa: ' + mapa);
    } else if (d.modalidad === 'recojo') {
      lineas.push('Entrega: recojo en el local');
    }
    lineas.push('Ítems:');
    const todas = avLineas(d.lineas);
    let largo = 0;
    for (let i = 0; i < todas.length; i++) {
      const l = todas[i];
      const nota = avLimpio(l.detalle, 120, opc);
      const linea = '• ' + l.cantidad + ' × ' + (avLimpio(l.nombre, 80, opc) || 'ítem') + (nota ? ' (' + nota + ')' : '');
      if (largo + linea.length > 2200) { lineas.push('• … y ' + (todas.length - i) + ' más'); break; }
      lineas.push(linea);
      largo += linea.length + 1;
    }
    if (!todas.length) lineas.push('• (sin ítems)');
    // La nota del cliente (`notaPedido`, de la pagina del catalogo): la ven completo y cocina (sin numeros largos para cocina).
    const notaPedido = typeof d.notaPedido === 'string' ? avLimpio(d.notaPedido, 300, opc) : '';
    if (notaPedido) lineas.push('Nota del cliente: «' + notaPedido + '»');
    lineas.push('Total de la comida: Bs ' + avMonto(d.total));
    if (completo && Array.isArray(d.diferencias) && d.diferencias.length) {
      const dif = d.diferencias.slice(0, 6).map((x) => avLimpio(x, 100)).filter(Boolean).join('; ');
      if (dif) lineas.push('Diferencias: ' + dif);
    }
    cierre = resultado === 'sin_qr' ? AV_CIERRE_SIN_QR : resultado === 'qr_vencido' ? AV_CIERRE_QR_VENCIDO : (resultado === 'simulado' ? AV_CIERRE_SIMULADO : AV_CIERRE_PAGO);
  } else if (tipo === 'reserva') {
    const r = (d.reserva && typeof d.reserva === 'object') ? d.reserva : {};
    const p = Math.floor(Number(r.personas));
    const cod = avLimpio(d.codigo, 20);
    lineas.push('Solicitud de reserva' + (cod ? ' N.º ' + cod : ''));
    lineas.push('• ' + (avFechaLegible(r.fecha, r.hora) || 'fecha sin indicar'));
    lineas.push('• ' + (Number.isFinite(p) && p >= 1 ? p + (p === 1 ? ' persona' : ' personas') : 'personas sin indicar')
      + (avLimpio(r.zona, 40, opc) ? ', ' + avLimpio(r.zona, 40, opc) : ''));
    const aNombre = completo ? avLimpio(r.nombre || d.nombre, 60) : avPrimerNombre(r.nombre || d.nombre, opc);
    lineas.push('• A nombre de ' + (aNombre || 'sin nombre'));
    if (avMarcasReserva(r).length) lineas.push('• ' + avMarcasReserva(r).join(' · '));
    if (avLimpio(r.celebracion, 120, opc)) lineas.push('• Celebración: ' + avLimpio(r.celebracion, 120, opc));
    if (avLimpio(r.requerimiento, 200, opc)) lineas.push('• Pedido especial: ' + avLimpio(r.requerimiento, 200, opc));
    if (completo && tel) lineas.push('Cliente: tel ' + (avTelefonoLegible(d.telefono) || tel));
    cierre = AV_CIERRE_RESERVA;
  } else {
    const cod = avLimpio(d.codigo, 20) || avCodigoCorto(ahoraMs);
    lineas.push((d.comprobante === true ? 'Comprobante de un cliente (no se pudo revisar: cambió el modo de cobro) N.º ' : 'Consulta de un cliente N.º ') + cod);
    lineas.push(cliente());
    const motivo = avLimpio(d.motivo, 300, opc);
    if (motivo) lineas.push('Nota del cliente: «' + motivo + '»');
    cierre = AV_CIERRE_DERIVACION;
  }
  lineas.push(cierre);
  // Última red: nada que coincida con la lista de palabras prohibidas sale en el detalle.
  return avSinProhibidas(lineas.filter(Boolean).join('\n')).trim();
}

// --- Armado -----------------------------------------------------------------------------------

function avNormalizarDestinatarios(destinatarios, d, c) {
  // Solo el interruptor de ensayo (`true` exacto) deja de descartar al propio número; ver `avDestinatarios`.
  const incluirPropio = c.avisarAlPropioNumero === true;
  const propio = incluirPropio ? '' : avDigitos(d.telefono || d.from);
  if (typeof destinatarios === 'string') return avDestinatarios(destinatarios, propio, c.prefijosPermitidos, incluirPropio);
  if (!Array.isArray(destinatarios)) return [];
  return avUnificar(destinatarios, propio, avPrefijos(c.prefijosPermitidos));
}

// Núcleo puro: ítems y errores, sin tope diario y sin tocar `sd`.
function avConstruir(tipo, datos, destinatarios, cfg, sd, ahoraMs) {
  const d = (datos && typeof datos === 'object') ? datos : {};
  const c = (cfg && typeof cfg === 'object') ? cfg : {};
  const errores = [];
  if (AV_TIPOS.indexOf(tipo) < 0) return { items: [], errores: ['tipo_desconocido'] };
  const esPedido = tipo === 'pedido' || tipo === 'comprobante';
  // `sinGuardar` (07/11/2026): la imagen que el filtro tomó por un anuncio y el código no confirmó; no se guardó ni se cotejó y el aviso lo dice tal cual.
  const resultado = esPedido ? avResultado(tipo, tipo === 'comprobante' && d.sinGuardar === true ? 'sin_guardar' : d.resultado) : '';
  if (resultado === 'ya_cotejado') return { items: [], errores: ['sin_aviso_ya_cotejado'] };
  if (tipo === 'reserva' && !(d.reserva && typeof d.reserva === 'object')) return { items: [], errores: ['sin_datos_reserva'] };
  const dests = avNormalizarDestinatarios(destinatarios, d, c);
  if (!dests.length) return { items: [], errores: ['sin_destinatarios'] };

  const plEvento = avConfigPlantilla(tipo, c, errores);
  // En simulado no hay comprobante que mostrar (la foto no se baja ni se lee): nunca sale la imagen, venga o no `mediaId`.
  const idMedio = resultado !== 'simulado' && /^[A-Za-z0-9_.-]{1,100}$/.test(String(d.mediaId || '')) ? String(d.mediaId) : '';
  const items = [];
  for (const dest of dests) {
    const abierta = avVentanaAbierta(sd, dest.tel, ahoraMs);
    const conTexto = () => {
      const cuerpo = avDetalle(tipo, d, dest.rol, resultado, ahoraMs);
      items.push({ para: dest.tel, rol: dest.rol, payload: avTexto(dest.tel, cuerpo), respaldo: null, esPlantilla: false, clase: 'detalle' });
    };
    const conPlantilla = () => {
      // La reserva del rol `completo` puede tener su propia plantilla (`*ReservaCompleto`); el resto, la del evento.
      let pl = plEvento;
      if (tipo === 'reserva') {
        const propios = [];
        pl = avConfigPlantilla(tipo, c, propios, dest.rol);
        for (const e of propios) if (errores.indexOf(e) < 0) errores.push(e);
      }
      if (!pl.nombre) {
        // Sin plantilla configurada no se inventa un nombre: el evento falla cerrado (con ventana abierta cae al texto).
        if (!pl.configurada && errores.indexOf('plantilla_no_configurada_' + pl.evento) < 0) errores.push('plantilla_no_configurada_' + pl.evento);
        return false;
      }
      // Pedido con la plantilla por líneas (solo si `plantillasPedidoLineas` trae algo): el menor tamaño que cabe; si ese tamaño
      // no tiene plantilla, cae a la de siempre y lo anota.
      let nombreFinal = pl.nombre;
      let params = null;
      if (esPedido && String(c.plantillasPedidoLineas === undefined || c.plantillasPedidoLineas === null ? '' : c.plantillasPedidoLineas).trim() !== '') {
        const tamano = avTamanoLineas(avLineas(d.lineas).length);
        const porTamano = avPlantillasLineas(c.plantillasPedidoLineas);
        if (porTamano[tamano]) {
          nombreFinal = porTamano[tamano];
          params = avVariablesLineas(d, dest, resultado, tamano);
        } else if (errores.indexOf('lineas_sin_plantilla_' + tamano) < 0) errores.push('lineas_sin_plantilla_' + tamano);
      }
      let idiomaFinal = pl.idioma;
      if (params) idiomaFinal = String(c.idiomaPlantillaPedidoLineas === undefined || c.idiomaPlantillaPedidoLineas === null ? '' : c.idiomaPlantillaPedidoLineas).trim() || pl.idioma;
      if (!params) {
        const vars = avVariables(tipo, d, dest, resultado, ahoraMs, pl.forma);
        params = pl.orden.map((k) => vars[k]);
      }
      const payload = avPlantilla(dest.tel, nombreFinal, idiomaFinal, params);
      if (!payload) return false;
      items.push({ para: dest.tel, rol: dest.rol, payload, respaldo: null, esPlantilla: true, clase: 'plantilla' });
      return true;
    };
    if (tipo === 'transferencia') {
      if (abierta) conTexto();
      else if (!conPlantilla() && errores.indexOf('sin_plantilla_derivacion') < 0) errores.push('sin_plantilla_derivacion');
      continue;
    }
    conPlantilla();
    if (abierta) {
      conTexto();
      if (tipo === 'comprobante' && dest.rol === 'completo' && idMedio) {
        const cod = avLimpio(d.codigo, 20);
        items.push({ para: dest.tel, rol: dest.rol, payload: avImagen(dest.tel, idMedio, 'Comprobante del pedido' + (cod ? ' N.º ' + cod : '')), respaldo: null, esPlantilla: false, clase: 'imagen' });
      }
    }
  }
  if (!items.length && !errores.length) errores.push('sin_aviso_posible');
  return { items, errores };
}

/** Los mensajes de aviso de un evento: `[{para, rol, payload, respaldo:null, esPlantilla, clase}]`. No toca `sd` ni aplica el tope. */
function avArmar(tipo, datos, destinatarios, cfg, sd, ahoraMs) {
  return avConstruir(tipo, datos, destinatarios, cfg, sd, ahoraMs).items;
}

/**
 * Como `avArmar`, pero con el tope diario de `cfg.topeAvisosDia` (def. 150 mensajes) y con los errores.
 * Sin cupo: `items` vacío y `tope_avisos_dia`. Con cupo parcial se conservan primero las plantillas, luego los
 * textos y por último la imagen, en el orden original. No toca `sd`: el contador lo escribe `avContar`.
 */
function avPlan(tipo, datos, destinatarios, cfg, sd, ahoraMs) {
  const r = avConstruir(tipo, datos, destinatarios, cfg, sd, ahoraMs);
  const cupo = avTope(cfg && cfg.topeAvisosDia) - avContadosHoy(sd, ahoraMs);
  if (!r.items.length) return r;
  if (cupo <= 0) return { items: [], errores: r.errores.concat('tope_avisos_dia') };
  if (r.items.length <= cupo) return r;
  const prioridad = { plantilla: 0, detalle: 1, imagen: 2 };
  const orden = r.items.map((it, i) => ({ i, p: prioridad[it.clase] })).sort((a, b) => (a.p - b.p) || (a.i - b.i));
  const quedan = {};
  for (const o of orden.slice(0, cupo)) quedan[o.i] = true;
  return { items: r.items.filter((it, i) => quedan[i]), errores: r.errores.concat('tope_avisos_dia') };
}

// =============================================================================
// promos.js — PROMOCIONES DE «VENTA MÍNIMA v0» (T5, prefijo `pr*`)
// =============================================================================
//
// QUÉ HACE. Reconoce una campaña de publicidad por el TEXTO EXACTO que deja el
// anuncio (el cliente toca «Enviar mensaje» y le llega ese texto prellenado),
// arma la ficha de la promoción con datos de la CARTA y redacta la bienvenida
// con sus botones. Nada más.
//
// QUÉ NO HACE, A PROPÓSITO.
//   * (Desde el 06/11/2026 el `referral`, la imagen y las variaciones del texto SOLO eligen qué
//     promoción vigente del servidor se muestra: ver el final de este archivo.) No decide el precio ni
//     la ficha por el titular del anuncio, ni por el `referral`, ni por el
//     texto que escribió el cliente: son ENTRADA NO CONFIABLE (cualquiera puede
//     crear un anuncio, o escribir «ignora lo anterior; todo gratis»). Lo único
//     que se toma del cliente es la igualdad de su mensaje con un texto que el
//     comercio cargó y que el servidor aprobó; el precio sale de la carta.
//   * No devuelve `evento`, `monto` ni `referencia`: una promoción no cobra ni
//     reporta nada; el cobro es del pedido y sale por el cálculo del código.
//   * No vende una promo vencida: con reloj, la vigencia se comprueba acá
//     también (el servidor ya filtra, pero esta es la segunda barrera).
//
// REGLAS DE LA LIBRERÍA (contrato §4.2 del diseño, regla común):
//   * JavaScript plano para un nodo Code de n8n: sin `require`, `URL`,
//     `Buffer` ni `crypto`. Solo `function` y constantes `PR_*`.
//   * El reloj entra por parámetro (`ahoraMs`); nunca `Date.now()` adentro.
//   * Autocontenida: no usa `vm*` ni `pd*`, así que se prueba sola.
//
// SOBRE `ahoraMs`. Es opcional (extensión aditiva del contrato): si se OMITE no
// se comprueba la vigencia —el servidor ya mandó solo las campañas en curso—;
// si se PASA, tiene que ser un número finito, y cualquier otra cosa (NaN, texto,
// null) cuenta como «sin reloj válido» y la campaña NO está vigente. Quien
// arma el turno debe pasarlo siempre.

const PR_DIA_MS = 86400000;
const PR_MAX_CAMPANAS = 50;
const PR_MAX_CARTA = 200;
const PR_MAX_NOMBRE = 80;
const PR_MAX_DESCRIPCION = 400;
const PR_PRECIO_MAXIMO = 1000000;
const PR_ID_BOTON = /^[A-Za-z0-9_-]{1,64}$/;

// Descripciones de relleno que un formulario o una plantilla dejan escritas.
// Se comparan ya normalizadas (sin tildes ni signos).
const PR_RELLENO = [
  'descripcion', 'descripcion del producto', 'descripcion de la promo', 'descripcion de la promocion',
  'n a', 'na', 'ninguna', 'ninguno', 'sin descripcion', 'sin datos', 'null', 'undefined', 'tbd', 'xxx',
  'pendiente', 'por definir', 'por confirmar', 'a confirmar', 'a definir', 'completar',
];
const PR_RELLENO_PARCIAL = /\b(por confirmar|a confirmar|por definir|lorem ipsum)\b/;

// Texto normalizado como lo compara el flujo: sin mayúsculas, tildes, signos ni
// emojis. LETRA POR LETRA lo mismo que `palabrasDeCampana` del servidor
// (`campanas.ts`): dos textos que acá son iguales allá son la misma campaña.
function prNorm(t) {
  return String(t === undefined || t === null ? '' : t).normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

// Una línea de texto segura para WhatsApp: sin controles, sin invisibles ni
// `<>&`, espacios colapsados y recortada.
function prLinea(t, max) {
  const s = String(t === undefined || t === null ? '' : t)
    .replace(/[\u00a0\u2028\u2029]/g, ' ')
    .replace(/[\u0000-\u001f\u007f\u200b-\u200f\u202a-\u202e\u2060\ufeff<>&]/g, ' ')
    .replace(/\s+/g, ' ').trim();
  return typeof max === 'number' && s.length > max ? s.slice(0, max).trim() : s;
}

// Un instante de una fecha de campaña. El servidor manda instantes ISO
// (`inicio` = comienzo del día en Bolivia, `fin` = comienzo del día siguiente);
// una fecha suelta «AAAA-MM-DD» se lee como día de La Paz (UTC-4 fijo), y su
// fin es inclusivo. Todo lo demás es inválido (NaN).
function prMs(valor, esFin) {
  if (typeof valor !== 'string') return NaN;
  const v = valor.trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(v)) {
    const base = Date.parse(v + 'T00:00:00-04:00');
    return esFin ? base + PR_DIA_MS : base;
  }
  if (!/^\d{4}-\d{2}-\d{2}T/.test(v)) return NaN;
  return Date.parse(v);
}

// ¿Está la campaña en curso en ese instante? `inicio <= ahora < fin`. Sin reloj
// válido o con fechas ilegibles: no.
function prVigente(campana, ahoraMs) {
  if (typeof ahoraMs !== 'number' || !isFinite(ahoraMs)) return false;
  if (typeof campana !== 'object' || campana === null) return false;
  const ini = prMs(campana.inicio, false);
  const fin = prMs(campana.fin, true);
  if (!isFinite(ini) || !isFinite(fin) || fin <= ini) return false;
  return ini <= ahoraMs && ahoraMs < fin;
}

// La campaña cuyo texto es EXACTAMENTE el del mensaje (palabra por palabra,
// con la normalización del servidor), o `null`. Devuelve una COPIA con solo
// `{id, texto, inicio, fin}`. Un texto vacío —o que al normalizar queda
// vacío— nunca coincide. Si hay reloj, solo cuentan las vigentes.
function prCampanaDelTexto(campanas, texto, ahoraMs) {
  if (!Array.isArray(campanas) || typeof texto !== 'string') return null;
  const buscado = prNorm(texto);
  if (buscado === '') return null;
  const conReloj = ahoraMs !== undefined;
  const tope = Math.min(campanas.length, PR_MAX_CAMPANAS);
  for (let i = 0; i < tope; i++) {
    const c = campanas[i];
    if (typeof c !== 'object' || c === null) continue;
    if (typeof c.id !== 'string' || c.id === '' || typeof c.texto !== 'string') continue;
    if (prNorm(c.texto) !== buscado) continue;
    if (conReloj && !prVigente(c, ahoraMs)) continue;
    return { id: c.id, texto: c.texto.trim(), inicio: c.inicio, fin: c.fin };
  }
  return null;
}

// Un precio vendible: número finito, mayor que cero y razonable.
function prPrecioValido(p) {
  return typeof p === 'number' && isFinite(p) && p > 0 && p <= PR_PRECIO_MAXIMO;
}

// ¿El ítem se puede vender hoy? Agotado, excluido o inactivo: no. Sin precio
// mayor que cero: no (una promo nunca sale «gratis» por un dato faltante).
function prVendible(item) {
  if (item.agotado === true || item.excluido === true || item.activo === false) return false;
  return prPrecioValido(item.precio);
}

// La descripción real de un ítem, o '' si no hay una que valga la pena decir.
// Se omite (y el texto sale sin ella, nunca «incluye [Descripción]») si está
// vacía, es de relleno, trae un marcador `[...]` o `{...}` sin reemplazar, o
// solo repite el nombre.
function prDescripcion(descripcion, nombre) {
  if (typeof descripcion !== 'string') return '';
  const d = prLinea(descripcion, PR_MAX_DESCRIPCION);
  if (d === '') return '';
  if (/[\[\]{}]/.test(d)) return '';
  const n = prNorm(d);
  if (n.length < 3) return '';
  if (PR_RELLENO.indexOf(n) !== -1 || PR_RELLENO_PARCIAL.test(n)) return '';
  if (n === prNorm(nombre)) return '';
  return d.replace(/[\s.!?:;,]+$/, '');
}

// La ficha de la promoción: el ítem de la carta cuyo nombre aparece COMPLETO,
// como palabra(s) entera(s), en el texto de la campaña; si hay varios, el de
// nombre más largo. Es `null` si no hay ninguno, si hay empate entre ítems
// distintos, o si el elegido está agotado, excluido o sin precio mayor que
// cero (no se le sustituye otro más corto: «Promo Dúo con refresco» agotada no
// se convierte en la ficha del refresco). Lee SOLO `campana.texto`: nunca un
// titular, un `referral` ni el texto que escribió el cliente.
function prFicha(campana, carta, ahoraMs) {
  if (typeof campana !== 'object' || campana === null || typeof campana.texto !== 'string') return null;
  if (ahoraMs !== undefined && !prVigente(campana, ahoraMs)) return null;
  if (!Array.isArray(carta)) return null;
  const texto = ' ' + prNorm(campana.texto) + ' ';
  if (texto === '  ') return null;
  const tope = Math.min(carta.length, PR_MAX_CARTA);
  let mejor = null;
  let largo = 0;
  let empate = false;
  for (let i = 0; i < tope; i++) {
    const it = carta[i];
    if (typeof it !== 'object' || it === null || typeof it.nombre !== 'string') continue;
    const nn = prNorm(it.nombre);
    if (nn === '' || texto.indexOf(' ' + nn + ' ') === -1) continue;
    if (nn.length > largo) { mejor = it; largo = nn.length; empate = false; continue; }
    if (nn.length === largo && mejor !== it) {
      const mismo = it.id !== undefined && it.id === mejor.id && nn === prNorm(mejor.nombre);
      if (!mismo) empate = true;
    }
  }
  if (mejor === null || empate || !prVendible(mejor)) return null;
  const nombre = prLinea(mejor.nombre, PR_MAX_NOMBRE);
  return {
    id: typeof mejor.id === 'string' || typeof mejor.id === 'number' ? String(mejor.id) : '',
    nombre: nombre,
    precio: mejor.precio,
    moneda: typeof mejor.moneda === 'string' ? mejor.moneda : '',
    descripcion: prDescripcion(mejor.descripcion, nombre),
    campanaId: typeof campana.id === 'string' ? campana.id : '',
  };
}

// La moneda a mostrar: la del ítem o la del negocio. «Bs» para Bolivia por
// defecto (y para «BOB»); otra sigue sus letras en mayúsculas, con tope.
function prMoneda(cfg, ficha) {
  const crudo = ficha && typeof ficha.moneda === 'string' && ficha.moneda !== ''
    ? ficha.moneda : (cfg && typeof cfg.moneda === 'string' ? cfg.moneda : '');
  const m = crudo.trim();
  if (m === '' || /^(bs\.?|bob)$/i.test(m)) return 'Bs';
  return /^[A-Za-z]{2,6}$/.test(m) ? m.toUpperCase() : 'Bs';
}

// El precio como se dice en Bolivia: «35» o «35,50» (centavos enteros, sin
// errores de punto flotante). `null` si no es un precio vendible.
function prPrecioLegible(precio) {
  if (!prPrecioValido(precio)) return null;
  const c = Math.round(precio * 100);
  const bs = Math.floor(c / 100);
  const cs = c % 100;
  return cs === 0 ? String(bs) : bs + ',' + (cs < 10 ? '0' : '') + cs;
}

// Los botones de la ficha. Cada uno solo con su capacidad ESTRICTAMENTE
// `true` (un «sí», 1 o «true» como texto no encienden nada):
//   «Pedir la promo»  pedidosActivo  g|pedir|<itemId>
//   «Reservar mesa»   reservasActivo m|reserva
//   «Ver la carta»    pedidosActivo  m|pedido
// Sin un id de ítem válido no hay «Pedir la promo» (el id no puede llevar `|`).
function prBotones(ficha, cfg) {
  const botones = [];
  const c = typeof cfg === 'object' && cfg !== null ? cfg : {};
  const id = ficha && typeof ficha.id === 'string' ? ficha.id : '';
  if (c.pedidosActivo === true && PR_ID_BOTON.test(id)) botones.push({ id: 'g|pedir|' + id, title: 'Pedir la promo' });
  if (c.reservasActivo === true) botones.push({ id: 'm|reserva', title: 'Reservar mesa' });
  if (c.pedidosActivo === true) botones.push({ id: 'm|pedido', title: 'Ver la carta' });
  return botones;
}

// El mensaje de la promoción: `{cuerpo, botones}`, o `null` si no hay ficha o
// la ficha no trae un nombre y un precio vendibles. La descripción se vuelve a
// depurar acá, así una ficha armada a mano tampoco puede sacar un relleno.
function prTexto(ficha, cfg) {
  if (typeof ficha !== 'object' || ficha === null) return null;
  const nombre = prLinea(ficha.nombre, PR_MAX_NOMBRE);
  const precio = prPrecioLegible(ficha.precio);
  if (nombre === '' || precio === null) return null;
  const desc = prDescripcion(ficha.descripcion, nombre);
  const medio = desc === '' ? nombre : nombre + ': ' + desc;
  return {
    cuerpo: '¡Hola! Qué bueno que viste nuestra promo. ' + medio + '. Precio: ' + precio + ' ' + prMoneda(cfg, ficha) + '.',
    botones: prBotones(ficha, cfg),
  };
}

// CAMPAÑA DE SOLO RESERVA (dato del negocio, 05/11): el comercio carga en «Config base» el texto exacto del anuncio
// (`campanaReservaTexto`) y la respuesta (`campanaReservaMensaje`). La campaña la sigue aprobando y vigenciando el servidor:
// esto solo se aplica a una campaña ya reconocida por `prCampanaDelTexto` (vigente) cuyo texto es IGUAL (normalizado) al dato.
// No vende ni cobra: su único botón es «Reservar mesa», y solo con `reservasActivo === true`. Nada sale del texto del cliente.
// Devuelve `{cuerpo, botones}` o `null` (entonces rige la ficha de siempre).
function prSoloReserva(campana, cfg) {
  if (typeof campana !== 'object' || campana === null || typeof campana.texto !== 'string') return null;
  const c = typeof cfg === 'object' && cfg !== null ? cfg : {};
  if (c.reservasActivo !== true) return null;
  const clave = prNorm(c.campanaReservaTexto);
  if (clave === '' || prNorm(campana.texto) !== clave) return null;
  const cuerpo = prLinea(c.campanaReservaMensaje, 900);
  if (cuerpo === '') return null;
  return { cuerpo: cuerpo, botones: [{ id: 'm|reserva', title: 'Reservar mesa' }] };
}

// CAMPAÑA DE PEDIDO CON MENSAJE DEL NEGOCIO (06/11, «Tortas mexicanas» de Q'Taco): igual que `prSoloReserva`, pero el único botón es
// «Hacer un pedido» (`m|pedido`, el mismo que abre la carta desde el menú), y solo con `pedidosActivo === true`. El texto exacto del
// anuncio (`campanaPedidoTexto`) y la respuesta (`campanaPedidoMensaje`, con los precios) son DATO del negocio; la campaña la sigue
// aprobando y vigenciando el servidor (`prCampanaDelTexto`). No vende ni cobra: los precios del mensaje son informativos y el pedido
// se arma con los de la carta. Devuelve `{cuerpo, botones}` o `null` (entonces rige la ficha de siempre).
function prPedidoConMensaje(campana, cfg) {
  if (typeof campana !== 'object' || campana === null || typeof campana.texto !== 'string') return null;
  const c = typeof cfg === 'object' && cfg !== null ? cfg : {};
  if (c.pedidosActivo !== true) return null;
  const clave = prNorm(c.campanaPedidoTexto);
  if (clave === '' || prNorm(campana.texto) !== clave) return null;
  let cuerpo = prLinea(c.campanaPedidoMensaje, 900);
  if (cuerpo === '') return null;
  // Solo se promete «te lleva directo a Promos» si se cumple (hay área y un enlace https del catálogo web); si no, el mismo mensaje sin esa promesa (C-03/revisión #829).
  if (prAreaDelPedido(c) === '') cuerpo = prLinea(cuerpo.replace(/,?\s*que te llevar[aá] directo a [^.]*\./i, '.'), 900);
  return { cuerpo: cuerpo, botones: [prBotonHacerPedido(c)] };
}

// El área del catálogo web a la que lleva «Hacer un pedido» de la campaña de pedido (`campanaPedidoArea`, dato del negocio, p. ej. «promociones»): solo letras,
// números, espacios, guion y guion bajo (viaja como `?area=` en la URL del catálogo; la web la COMPARA con sus áreas y, si no existe, abre «Todo»). '' = sin área.
function prAreaDelPedido(cfg) {
  const c = typeof cfg === 'object' && cfg !== null ? cfg : {};
  const a = prLinea(c.campanaPedidoArea, 60);
  // Sin un enlace https del catálogo web no hay a dónde llevar: el botón abre la carta de siempre (en texto).
  if (!/^https:\/\/[^\s<>"']+$/.test(typeof c.catalogoWebEnlace === 'string' ? c.catalogoWebEnlace.trim() : '')) return '';
  return a !== '' && /^[\p{L}\p{N} _-]{1,60}$/u.test(a) ? a : '';
}

// «Hacer un pedido»: `m|pedido` abre la carta completa; con área configurada es `m|pedido|promos`, el MISMO botón de pedido (mismas reglas de horario y de paso)
// con una marca que hace que la carta se abra en esa área. El nombre del área NO viaja en el botón: lo toma `Plan del turno` del dato del negocio.
function prBotonHacerPedido(cfg) {
  return { id: prAreaDelPedido(cfg) !== '' ? 'm|pedido|promos' : 'm|pedido', title: 'Hacer un pedido' };
}

// =============================================================================
// VARIACIONES, ANUNCIO (referral) E IMAGEN DEL ANUNCIO — 06/11/2026 (adenda de campañas de Q'Taco)
// =============================================================================
// Todo se decide por CÓDIGO y SIEMPRE contra una campaña VIGENTE que el servidor aprobó (`campanas` / `anuncios`): lo que escribe el cliente, el
// `referral` del anuncio y el texto que Gemini leyó en una imagen son entrada NO confiable que SOLO elige cuál de esas campañas se muestra. Ninguno
// vende, cobra ni abre un pedido: la respuesta es el mismo mensaje de promoción (reemplaza al saludo; 0 mensajes agregados).
//
// Las dos campañas con mensaje del negocio se identifican por los datos de «Config base» que ya existen: «A» (pedido) es la campaña vigente cuyo texto es
// `campanaPedidoTexto`; «B» (reserva) la de `campanaReservaTexto`. Con la campaña apagada, vencida o sin esos datos, nada de esto se activa.
function prCampanaPorId(campanas, id, ahoraMs) {
  if (!Array.isArray(campanas) || typeof id !== 'string' || id === '') return null;
  const tope = Math.min(campanas.length, PR_MAX_CAMPANAS);
  for (let i = 0; i < tope; i++) {
    const c = campanas[i];
    if (typeof c !== 'object' || c === null || c.id !== id || typeof c.texto !== 'string') continue;
    if (ahoraMs !== undefined && !prVigente(c, ahoraMs)) continue;
    return { id: c.id, texto: c.texto.trim(), inicio: c.inicio, fin: c.fin };
  }
  return null;
}

// La campaña «A» (pedido) o «B» (reserva) vigente, o `null`. A exige `pedidosActivo === true`; B, `reservasActivo === true`.
function prCampanaDeTipo(campanas, cfg, tipo, ahoraMs) {
  const c = typeof cfg === 'object' && cfg !== null ? cfg : {};
  if (tipo === 'A') return c.pedidosActivo === true && prNorm(c.campanaPedidoTexto) !== '' ? prCampanaDelTexto(campanas, c.campanaPedidoTexto, ahoraMs) : null;
  if (tipo === 'B') return c.reservasActivo === true && prNorm(c.campanaReservaTexto) !== '' ? prCampanaDelTexto(campanas, c.campanaReservaTexto, ahoraMs) : null;
  return null;
}

// Minúsculas y sin tildes, CONSERVANDO los signos (para ver el «+» de «Jueves de +2»).
function prSinTildes(t) {
  return String(t === undefined || t === null ? '' : t).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
}

// Palabras que dicen «hablo de la promoción o del anuncio» (ya normalizado).
const PR_DICE_PROMO = /\b(promo|promos|promocion|promociones|oferta|ofertas|anuncio|anuncios|publicidad|publicacion|propaganda|facebook|face|fb|instagram|insta|ig|vi|vimos|redes)\b/;
// Pide los detalles de lo que incluye el combo (campaña B).
const PR_PIDE_DETALLE = /\b(que (incluye|incluyen|trae|traen|viene|vienen|lleva|llevan|contiene|contienen|tiene|tienen)|incluye|incluyen|detalles?|detallame|en que consiste|mas info|mas informacion|informacion|de que se trata|que es lo que (incluye|trae|viene))\b/;
// Pregunta por qué el arte dice «solo delivery» (campaña A).
const PR_PREGUNTA_DELIVERY = /\b(solo|solamente|unicamente|nomas)\b.*\b(delivery|domicilio)\b|\b(delivery|domicilio)\b.*\b(solo|solamente|unicamente|nomas)\b/;

// ¿El texto habla de la promo de las tortas mexicanas? Exige «tortas mexicanas» Y una palabra de promoción/anuncio: «quiero tortas», «quiero 2 tortas mexicanas
// con queso» (un pedido) o «una torta» NO la activan, y siguen el camino de siempre.
function prMencionaA(n) {
  return (/\btortas? mexicanas?\b/.test(n) && PR_DICE_PROMO.test(n)) || prPromoJuntoA(n, prEsTorta);
}
// ¿Habla del «Jueves de +2» o de agrandar el Q'Taco Dúo? «jueves de +2» / «jueves +2» / «jueves de mas 2» valen solos (las dos primeras, la marca del anuncio; la
// tercera, como antes del 07/11); «jueves mas 2» (sin «de») y «jueves de 2 mas» solo con una palabra de promoción o si son el mensaje ENTERO («el jueves más 2
// amigos» no es la promo); «jueves de 2» (sin el «+») solo con una palabra de promoción y sin ser un horario («jueves de 2 a 4»); la palabra de promoción PEGADA al
// jueves («promo jueves», «la promo del jueves», «oferta de los jueves»); «agrandar … Q'Taco Dúo» en cualquier orden.
function prMencionaB(crudo, n) {
  if (/\bjueves ?(de |del )?\+ ?2\b/.test(crudo) || /\bjueves de ?mas ?2\b/.test(crudo)) return true;
  const entero = /^((quiero|quisiera) )?((la|el) )?((promo|promocion|oferta) )?((de|del) )?(los |el )?jueves /.test(n);
  if (/\bjueves (del )?mas 2\b/.test(n) && (PR_DICE_PROMO.test(n) || (entero && /\bjueves (del )?mas 2$/.test(n)))) return true;
  if (/\bjueves de 2\b/.test(n) && !/\bjueves de 2 (a|al|am|pm|hrs?|horas?|y|hasta|de la|en la|personas?|pax|gente|amig\w+|invitad\w+)\b/.test(n) && PR_DICE_PROMO.test(n)) return true;
  if (/\bjueves (de |del )?2 mas\b/.test(n) && (PR_DICE_PROMO.test(n) || (entero && /\bjueves (de |del )?2 mas$/.test(n)))) return true;
  // Pegada al jueves, salvo que nombre OTRA cifra («la promoción Jueves de +3» no es el «Jueves de +2»).
  const otraCifra = /\bjueves ?(de |del )?(\+ ?|mas ?)?(\d+)/.exec(crudo);
  if (!(otraCifra && otraCifra[3] !== '2') && prPromoJuntoA(n, (w) => w === 'jueves')) return true;
  return /\bagrand\w*\b/.test(n) && /\b(q ?taco|qtaco) duo\b/.test(n);
}
// C (07/11/2026, prueba de Andres): «quiero la promo tortas», «promo tortaa», «promoción de tortas», «la promo de las tortas», «tortas de la promo». Solo cuando una
// palabra de PROMOCIÓN está PEGADA a la palabra (a lo sumo con «de/del/la/las/el/los» entre medio), en cualquiera de los dos órdenes. «quiero una torta mexicana con
// queso» (sin palabra de promoción) es un pedido de carta y no activa nada.
const PR_PALABRA_PROMO = ['promo', 'promos', 'promocion', 'promociones', 'oferta', 'ofertas', 'anuncio', 'anuncios'];
const PR_RELLENO_PROMO = ['de', 'del', 'la', 'las', 'el', 'los'];
function prPromoJuntoA(n, esLaPalabra) {
  const ps = n.split(' ').filter(Boolean);
  for (let i = 0; i < ps.length; i++) {
    if (PR_PALABRA_PROMO.indexOf(ps[i]) < 0) continue;
    for (const paso of [1, -1]) {
      let j = i + paso;
      let saltos = 0;
      while (j >= 0 && j < ps.length && PR_RELLENO_PROMO.indexOf(ps[j]) >= 0 && saltos < 2) { j += paso; saltos += 1; }
      if (j >= 0 && j < ps.length && esLaPalabra(ps[j])) return true;
    }
  }
  return false;
}
// «torta» o «tortas», o una de ellas con UNA letra cambiada, de más o de menos («tortaa», «tortss»), SIEMPRE con el prefijo «tort» («tarta» o «tosta» no son
// tortas).
function prEsTorta(w) {
  if (typeof w !== 'string' || w.slice(0, 4) !== 'tort' || w.length < 5 || w.length > 7) return false;
  return prDistanciaUno(w, 'torta') || prDistanciaUno(w, 'tortas');
}
// ¿Distancia de edición (Levenshtein) de 1 o menos entre dos palabras cortas?
function prDistanciaUno(a, b) {
  if (a === b) return true;
  if (Math.abs(a.length - b.length) > 1) return false;
  let fila = [];
  for (let j = 0; j <= b.length; j++) fila.push(j);
  for (let i = 1; i <= a.length; i++) {
    const nueva = [i];
    for (let j = 1; j <= b.length; j++) nueva.push(Math.min(fila[j] + 1, nueva[j - 1] + 1, fila[j - 1] + (a.charAt(i - 1) === b.charAt(j - 1) ? 0 : 1)));
    fila = nueva;
  }
  return fila[b.length] <= 1;
}

// Palabras que una pregunta SOBRE la promoción puede traer sin pedir nada más (saludos, la propia promo, precio, pedir o reservar). Si queda alguna otra, la
// pregunta es de otra cosa (C-09, 06/11/2026).
const PR_VOCABULARIO_PROMO = ('hola buenas buenos dias tardes noches vi vimos el la las los lo un una unos unas de del al en a y o u e que cual cuales como cuanto cuantos cuesta cuestan precio precios '
  + 'es son hay tienen tiene tienes quiero quisiera queria quisieramos saber info informacion promo promos promocion promociones anuncio anuncios oferta ofertas torta tortas mexicana mexicanas '
  + 'jueves mas 2 agrandar agranda agrandan agrandarlo q taco tacos qtaco duo por para con sin queso facebook face fb instagram insta ig redes publicidad publicacion me puedes pueden favor gracias '
  + 'ver sobre acerca esta esa ese este se mi su tu si no pedido pedir hacer reserva reservar mesa dime decir dinos delivery envio envios domicilio recoger recojo recogerlo llevar local restaurante sucursal variedades variedad sabores sabor tamano tamanos hacen hace venden manejan puede puedo agrandado dia dias solo disponible vigente aun todavia valida valido').split(' ');
// ¿Es una PREGUNTA (con «?» o que empieza con una palabra interrogativa) que el mensaje de la promoción NO contesta? Solo se dice cuando queda al menos una
// palabra fuera del vocabulario de la promo. Ante la duda se pasa con el local: hay falsos positivos (se avisa de más), nunca una promesa.
function prPreguntaSinResponder(texto) {
  if (typeof texto !== 'string') return false;
  const corto = texto.slice(0, 600);
  const n = prNorm(corto);
  if (n === '') return false;
  if (!/[?¿]/.test(corto) && !/^(que|cual|cuales|cuanto|cuantos|como|donde|cuando|hay|tienen|puedo|se puede|pueden|hacen|aceptan|incluye|tiene|venden|quien)\b/.test(n)) return false;
  const palabras = n.split(' ');
  for (let i = 0; i < palabras.length; i++) {
    if (palabras[i] !== '' && PR_VOCABULARIO_PROMO.indexOf(palabras[i]) === -1) return true;
  }
  return false;
}

// El mensaje de una campaña SIN lo que apunta a su botón: se corta desde «tocando/toca el botón…» y se quita una pregunta final («¿Quieres…?») y lo que le sigue, para
// los casos en que el único botón del mensaje es otro («Escribir al local»). Siempre termina en punto.
function prCuerpoSinBoton(cuerpo) {
  let t = prLinea(cuerpo, 900);
  t = t.replace(/\s*(tocando|toca)\s+el\s+bot[oó]n.*$/i, '').replace(/\s*¿[^¿?]*\?.*$/, '').replace(/\s*(\.\s*)?(👇|👉)\s*$/u, '').replace(/[\s,;:]+$/, '');
  if (t === '') return '';
  return /[.!?]$/.test(t) ? t : t + '.';
}

// La VARIACIÓN del texto de una campaña: `{campana, variante}` o `null`. `variante`: 'promo' (el mensaje de la promoción), 'detalle' (campaña B: «¿qué incluye?»)
// o 'solo_delivery' (campaña A: «¿por qué dice solo delivery?»). `contexto` ('A', 'B' o ''): la campaña que el cliente acaba de ver (estado de la conversación) o
// la de la imagen que mandó; con contexto, una pregunta SUELTA («¿qué incluye?», «¿solo delivery?», de hasta 200 caracteres) se atiende, y sin pregunta
// específica nunca activa nada. Nombrar las dos campañas a la vez es ambiguo: `null`. Sin campaña vigente que mostrar: `null`.
function prVariacion(texto, campanas, cfg, ahoraMs, contexto) {
  if (typeof texto !== 'string') return null;
  const corto = texto.slice(0, 600);
  const n = prNorm(corto);
  if (n === '') return null;
  const crudo = prSinTildes(corto);
  const dichoA = prMencionaA(n);
  const dichoB = prMencionaB(crudo, n);
  if (dichoA && dichoB) return null;
  const tipo = dichoA ? 'A' : dichoB ? 'B' : (contexto === 'A' || contexto === 'B') && n.length <= 200 ? contexto : '';
  if (tipo === '') return null;
  const campana = prCampanaDeTipo(campanas, cfg, tipo, ahoraMs);
  if (!campana) return null;
  if (tipo === 'B' && PR_PIDE_DETALLE.test(n)) return { campana: campana, variante: 'detalle' };
  if (tipo === 'A' && PR_PREGUNTA_DELIVERY.test(n)) return { campana: campana, variante: 'solo_delivery' };
  return dichoA || dichoB ? { campana: campana, variante: 'promo', sinResponder: prPreguntaSinResponder(texto) } : null;
}

// Las respuestas a una pregunta específica, con DATO del negocio (`campanaReservaDetalle`, `campanaPedidoEntrega`): `{cuerpo, botones}` o `null` si falta el
// dato o la capacidad (entonces rige el mensaje de la promoción). Nunca cobra ni vende: el botón es el mismo de la campaña.
function prRespuestaDeVariante(campana, cfg, variante) {
  if (typeof campana !== 'object' || campana === null) return null;
  const c = typeof cfg === 'object' && cfg !== null ? cfg : {};
  if (variante === 'detalle') {
    const base = prSoloReserva(campana, c);
    const cuerpo = prLinea(c.campanaReservaDetalle, 900);
    return base && cuerpo !== '' ? { cuerpo: cuerpo, botones: base.botones } : null;
  }
  if (variante === 'solo_delivery') {
    const base = prPedidoConMensaje(campana, c);
    const cuerpo = prLinea(c.campanaPedidoEntrega, 900);
    return base && cuerpo !== '' ? { cuerpo: cuerpo, botones: base.botones } : null;
  }
  return null;
}

// El anuncio por el que llegó el cliente (`referral` de WhatsApp: ya reducido a `{headline, body}` por `Interpretar entrada`). `reconocer` es
// `anuncioPorTitular` (módulo core, inyectado): compara el titular y el cuerpo con los `titulares` de los anuncios VIGENTES del servidor. Devuelve la campaña
// vigente de ese anuncio o `null` (referral ajeno, forjado, sin coincidencia, o dos campos que apuntan a anuncios distintos). NO vende ni abre nada.
function prCampanaDelReferral(campanas, anuncios, referral, ahoraMs, reconocer) {
  if (typeof referral !== 'object' || referral === null || typeof reconocer !== 'function' || !Array.isArray(anuncios)) return null;
  const ids = [];
  const campos = [referral.headline, referral.body];
  for (let i = 0; i < campos.length; i++) {
    const t = prLinea(campos[i], 200);
    if (t === '') continue;
    let a = null;
    try { a = reconocer(t, anuncios); } catch (e) { a = null; }
    if (a && typeof a.id === 'string' && a.id !== '') ids.push(a.id);
  }
  if (!ids.length || ids.some(function (x) { return x !== ids[0]; })) return null;
  return prCampanaPorId(campanas, ids[0], ahoraMs);
}

// Un titular leído de una imagen, apto SOLO para compararse: sin precios (el clasificador no debe devolverlos) y sin más de 100 caracteres.
function prTitularSeguro(v) {
  const t = prLinea(v, 100);
  if (/\b(bs|bob)\b|\$|\d{3,}|\d+\s*[.,]\s*\d{2}\b/i.test(t)) return '';
  return t;
}

// La campaña vigente a la que corresponde la IMAGEN que mandó el cliente, según lo que leyó el clasificador (`crudoGemini`: su respuesta como TEXTO, un JSON
// `{categoria, titular_principal, campana}`). Solo cuenta `categoria: 'publicidad'`. Se decide por el titular (`reconocer` = `anuncioPorTitular`, contra los
// anuncios vigentes) Y/O por el campo `campana` ('A' o 'B', el arte reconocido por sus elementos visuales); si los dos hablan y no coinciden, `null`. Lo leído
// en la imagen NUNCA llega a un modelo ni al cliente: solo decide un id de campaña aprobada. Una imagen no vende ni cobra.
function prCampanaDeLaImagen(campanas, anuncios, crudoGemini, ahoraMs, reconocer, cfg) {
  if (typeof crudoGemini !== 'string') return null;
  const m = /\{[\s\S]*\}/.exec(crudoGemini);
  if (!m) return null;
  let o = null;
  try { o = JSON.parse(m[0]); } catch (e) { o = null; }
  if (typeof o !== 'object' || o === null || Array.isArray(o)) return null;
  if (typeof o.categoria !== 'string' || prNorm(o.categoria) !== 'publicidad') return null;
  let porTitular = null;
  const titular = prTitularSeguro(o.titular_principal);
  if (titular !== '' && typeof reconocer === 'function' && Array.isArray(anuncios)) {
    let a = null;
    try { a = reconocer(titular, anuncios); } catch (e) { a = null; }
    if (a && typeof a.id === 'string') porTitular = prCampanaPorId(campanas, a.id, ahoraMs);
  }
  const letra = typeof o.campana === 'string' ? o.campana.trim().toUpperCase() : '';
  const porCampo = letra === 'A' || letra === 'B' ? prCampanaDeTipo(campanas, cfg, letra, ahoraMs) : null;
  if (porTitular && porCampo) return porTitular.id === porCampo.id ? porTitular : null;
  return porTitular || porCampo;
}

// C-12 (06/11/2026): ¿es jueves en La Paz (UTC-4 fijo) en ese instante? Lo calcula el código; el día de la semana nunca lo dice el modelo.
function prEsJueves(ahoraMs) {
  if (typeof ahoraMs !== 'number' || !isFinite(ahoraMs)) return false;
  return new Date(ahoraMs - 4 * 3600000).getUTCDay() === 4;
}

// ¿Qué campaña de mensaje del negocio es esta (para recordarla en el estado y atender la pregunta que sigue)? 'A', 'B' o ''.
function prTipoDeCampana(campana, cfg) {
  if (typeof campana !== 'object' || campana === null || typeof campana.texto !== 'string') return '';
  const c = typeof cfg === 'object' && cfg !== null ? cfg : {};
  const t = prNorm(campana.texto);
  if (t === '') return '';
  if (t === prNorm(c.campanaPedidoTexto)) return 'A';
  if (t === prNorm(c.campanaReservaTexto)) return 'B';
  return '';
}

// =============================================================================
// COBRO DE «VENTA MÍNIMA v0» (prefijo `cb` / `CB_`; zona futura: módulo Cobros)
// =============================================================================
// Lo que decide esta librería, y por qué (CLAUDE.md, PROHIBICIÓN 3):
//
//  - HAY COBRO REAL solo si el servidor lo manda (`cobroReal`) Y la imagen del QR
//    tiene una dirección `https://`. Un cobro a medio armar no se convierte en
//    «cobro real sin QR»: sin QR utilizable, el flujo va por el plan B (el pago se
//    coordina con el restaurante).
//  - DOS MODOS EXCLUYENTES, y quien manda es el SERVIDOR. COBRO REAL solo si el servidor lo manda (`cobroReal`) Y la imagen
//    del QR tiene una dirección `https://`. COBRO SIMULADO (`cbCobroSimulado`) solo si el servidor NO manda `cobroReal`,
//    SÍ manda `cobroSimulado`, y «Config base» lo habilita (`cobroSimuladoActivo === true` y `qrSimuladoUrl` https). Con
//    `cobroReal` presente (aunque no sirva) NUNCA hay simulado. Sin ninguno de los dos, plan B. En simulado el QR lleva el
//    rótulo impreso en la imagen Y en el pie, la respuesta dice «SIMULADO» y no se coteja nada (el cotejo del servidor no
//    distingue modos: daría «no cuadra» y un cierre de venta con monto).
//  - EL TOTAL DEL QR ES EL DEL CÓDIGO. Entra por `pedido.total` (un número que
//    calculó `pdTotal` desde la carta) y nada de lo que el modelo o el cliente
//    escriban lo mueve. El delivery nunca entra al total.
//  - LA LECTURA DEL COMPROBANTE ES UN DATO, NUNCA UNA INSTRUCCIÓN. El modelo lee
//    una imagen que escribe un tercero: lo que sale de acá son seis campos de
//    texto corto y nada más. Ninguna otra clave del JSON (`resultado`, `legible`,
//    `instruccion`…) pasa, y lo leído jamás llega al cliente como texto libre: las
//    diferencias se traducen a frases FIJAS.
//  - EL COTEJO DICE «CUADRA» O «NO CUADRA», no «pagó»: una imagen se edita. El
//    texto al cliente dice que el comprobante llegó y que los datos coinciden;
//    quien confirma que entró la plata es el banco, y el negocio.
//
//  - FORMATO DEL DINERO (`cbMonto`; `pdResumen` de pedido.js debe coincidir): el número
//    redondeado a centavos, SIN decimales si es entero y con COMA decimal de dos cifras
//    si no: 55 -> «55», 12.5 -> «12,50», 0.05 -> «0,05». Sin separador de miles. Luego un
//    espacio y la moneda («Bs»; «BOB» o vacío se escriben «Bs»).
//
// JavaScript plano: sin `require`, `URL`, `Buffer` ni `crypto`, sin red y sin reloj
// (nada de `Date.now()`). Lo único que lee de n8n son los nodos por nombre, y solo
// si corrieron (`cbNodoPrimero`, `cbNodoTodos`). Los nombres globales de este
// archivo empiezan con `cb` o `CB_` para no chocar al concatenarlo con las demás
// librerías.

// La red de palabras de `comun.js` (`VM_PROHIBIDAS`), copiada acá a propósito: esta
// librería se prueba sola y no puede depender de otro archivo.
const CB_PROHIBIDAS = /validad|confirmad|pagad[oa]|acreditad|verificad|recibimos\s+tu\s+pago|ya lo prepar|lo (est[aá](n|mos)|estoy) prepar|lo preparamos|te avisa(mos|remos)|en camino|te llama(mos|remos)|te escribir[aá]n|lo consulto|acredit|recib\S{0,40}\s+(tu|el|su|mi|un|este|ese|la|tus|sus|los)\s+(pago|transferencia|dep[oó]sito|abono)s?|lleg[oó]\s+(tu|el|su|mi)\s+(pago|transferencia|dep[oó]sito|abono)|(tu|el|su|mi)\s+(pago|transferencia|dep[oó]sito|abono)s?\s+(ya\s+)?(lleg|ingres|entr)(o|ó|aron)\b|(pago|transferencia|dep[oó]sito|abono)s?\s+(ya\s+|fue\s+|fueron\s+|est[aá]\s+)?(recibid|aprobad|[eé]xitos|realizad|registrad|llegad|ingresad|efectuad)|confirm(amos|ó|o)\s+(tu|tus|su|sus|la|el|lo|los|las)\b|\b(?:est[aá]n?|qued[oó]|queda|quedan|quedaron|fue|fueron|ya)\s+(?:ya\s+)?reservad|reserva\s+((est[aá]|qued[oó])\s+)?(registrad|agendad)|reservamos tu|\b(?:te|le|les|se|lo|la|ya)\s+confirm(?:o|amos|é|ó|aron)\b|gracias\s+por\s+(tu|su|el)\s+(pago|transferencia|dep[oó]sito|abono)s?|\b(lleg|ingres|entr)(o|ó|aron)\s+(tu|tus|el|los|su|sus|mi|la|las)\s+(pago|transferencia|dep[oó]sito|abono|dinero|plata|monto)|\b(tu|tus|el|los|su|sus|mi|la|las)\s+(pago|transferencia|dep[oó]sito|abono|dinero|plata|monto)s?\s+(ya\s+)?(lleg|ingres|entr)(o|ó|aron)\b|\brecib(imos|i|í|ido)\s+(el|la|tu|su)\s+(dinero|plata|monto)|(pago|transferencia|dep[oó]sito|abono|cobro)s?\s+(ya\s+|fue\s+|fueron\s+|est[aá]\s+|qued[oó]\s+|se\s+)?(ya\s+)?(recibid|aprobad|[eé]xitos|realizad|registrad|llegad|ingresad|efectuad|aceptad|completad|procesad|reflejad|comprobad)|\breflej(o|ó)\s+(tu|el|su)\s+(pago|transferencia|dep[oó]sito|abono)|\b(verificamos|comprobamos|validamos|aceptamos|tenemos|vimos|cobramos)\s+(tu|tus|su|sus|el|la)\s+(pago|transferencia|dep[oó]sito|abono|dinero|plata)|\bpago\s+(listo|ok)\b|\b(tu|su|el)\s+pago\s+(ya\s+)?(est[aá]|qued[oó])\s+(ya\s+)?(listo|ok|en\s+orden|bien|correcto|completo|hecho)\b|en\s+orden\s+con\s+(tu|su|el)\s+pago|\bsaldad[oa]s?\b|\b(pedido|cuenta|pago|total|orden|deuda)s?\s+((ya\s+)?(est[aá]n?|qued[oó]|fue|queda)\s+)?(ya\s+)?cancelad[oa]s?\b|\bya\s+nos\s+pag(aste|o|ó|aron)\b|\bgracias\s+por\s+pagar\b|\bya\s+pagaste\W{0,3}\s*(muchas\s+)?gracias|\brecib(imos|i|í|ido)\s+(bs\.?\s*|bob\s*)?\d+([.,]\d+)?\s*(bs|bob|bolivianos)\b|\bconfirm(amos|e|é)\s+que\s+(ya\s+)?pag|(pago|transferencia|dep[oó]sito|abono)s?\s+(ya\s+)?se\s+reflej/i;

// El total que acepta el servidor para cotejar (`TOTAL_VENTA_MAXIMO`).
const CB_TOTAL_MAXIMO = 1000000;

// El rótulo del QR simulado en el pie (el otro va IMPRESO en la imagen): sin él, el simulado no sale (PROHIBICIÓN 3).
const CB_ROTULO_SIMULADO = 'PRUEBA · COBRO SIMULADO: este QR es de demostración, no cobra ni mueve dinero.';

// ---------------------------------------------------------------------------
// Utilidades mínimas
// ---------------------------------------------------------------------------

// Confusables latino/cirílico/griego plegados a ASCII SOLO para comparar (S-1); las dos cadenas van en paralelo, letra por letra.
const CB_CONFUSABLES_DE = 'аеорсухіјѕԁһӏ' + 'αεικορτυχνηβı';
const CB_CONFUSABLES_A = 'aeopcyxijsdhl' + 'aeikoptuxvnbi';

// La forma en que se COMPARA contra `CB_PROHIBIDAS` (S-1): NFKC, sin controles C1 (\u0080-\u009f) ni caracteres de formato
// (`\p{Cf}`), NFD sin marcas (`\p{M}`), en minúsculas y con los confusables plegados a ASCII.
function cbCanon(t) {
  return String(t === undefined || t === null ? '' : t).normalize('NFKC').replace(/[\u0080-\u009f]/g, '').replace(/\p{Cf}/gu, '').replace(/[\u115f\u1160\u3164\uffa0\u2800]/g, '')
    .normalize('NFD').replace(/\p{M}/gu, '').toLowerCase()
    .replace(/[Ͱ-ϿЀ-ԯı]/g, (c) => {
      const i = CB_CONFUSABLES_DE.indexOf(c);
      return i < 0 ? c : CB_CONFUSABLES_A.charAt(i);
    });
}

// El nodo `nombre` si existe Y corrió en esta ejecución; si no, null.
function cbNodo(nombre) {
  try {
    const n = $(nombre);
    return n && n.isExecuted ? n : null;
  } catch (e) {
    return null;
  }
}
function cbNodoPrimero(nombre) {
  const n = cbNodo(nombre);
  if (!n) return null;
  try {
    const i = n.first();
    return i && i.json ? i.json : null;
  } catch (e) {
    return null;
  }
}
function cbNodoTodos(nombre) {
  const n = cbNodo(nombre);
  if (!n) return [];
  try {
    return n.all().map((i) => (i && i.json) || {});
  } catch (e) {
    return [];
  }
}

// Una línea de texto: sin controles, sin `<>&`, espacios colapsados, recortada.
function cbLinea(t, max) {
  const s = String(t === undefined || t === null ? '' : t)
    .replace(/[\u0000-\u001f\u007f]+/g, ' ').replace(/[<>&]/g, '').replace(/\s+/g, ' ').trim();
  return s.length > max ? s.slice(0, max).trimEnd() : s;
}

function cbEsObjeto(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

// El total de un pedido: SOLO un número del código. Un texto («63»), NaN, cero, un
// negativo o uno por encima del tope del servidor no son un total: devuelve null.
function cbTotalValido(v) {
  if (typeof v !== 'number' || !Number.isFinite(v)) return null;
  const r = Math.round(v * 100) / 100;
  return r > 0 && r <= CB_TOTAL_MAXIMO ? r : null;
}

// «55» o «12,50»: enteros sin decimales, y con coma decimal (así se lee en Bolivia).
function cbMonto(n) {
  const c = Math.round(Number(n) * 100);
  if (!Number.isFinite(c)) return '';
  const a = Math.abs(c);
  const cen = a % 100;
  return (c < 0 ? '-' : '') + Math.floor(a / 100) + (cen ? ',' + (cen < 10 ? '0' : '') + cen : '');
}

function cbMoneda(m) {
  const s = cbLinea(m, 8);
  return s === '' || /^(bob|bs)\.?$/i.test(s) ? 'Bs' : s;
}

// El código del pedido que se le muestra al cliente: letras y dígitos, sin más.
function cbCodigo(c) {
  const limpio = String(c === undefined || c === null ? '' : c).replace(/[^A-Za-z0-9]/g, '').slice(0, 12);
  // Un código que formara una palabra de la red de prohibidas no se muestra.
  return CB_PROHIBIDAS.test(cbCanon(limpio)) ? '' : limpio;
}

// ---------------------------------------------------------------------------
// Cobro real: solo si el servidor lo manda y el QR tiene una dirección https
// ---------------------------------------------------------------------------

// La URL del QR: solo `https://`, con un dominio con nombre (la última parte empieza con una letra: nada de IP, de
// «localhost» ni de números sueltos), SIN usuario (`@`) ni puerto, sin espacios ni comillas. Hasta 2.000 caracteres.
// (La expresión es lineal: cada parte del dominio está acotada a 63 caracteres y separada por un punto.)
function cbUrlSegura(u) {
  const s = typeof u === 'string' ? u.trim() : '';
  return s.length > 0 && s.length <= 2000
    && /^https:\/\/(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z](?:[a-z0-9-]{0,61}[a-z0-9])?(?:[/?#][^\s<>"'@]*)?$/i.test(s);
}

// `cuerpoPanel` es el cuerpo completo de `configuracionFlujo`. Sale `activo:false`
// con todo lo demás vacío en cualquier duda: sin QR utilizable no hay cobro real.
function cbCobroReal(cuerpoPanel) {
  const r = cbEsObjeto(cuerpoPanel) ? cuerpoPanel : {};
  const cr = cbEsObjeto(r.cobroReal) ? r.cobroReal : null;
  const cb = cbEsObjeto(r.cobro) ? r.cobro : {};
  const qr = cbEsObjeto(cb.qr) ? cb.qr : {};
  const url = typeof qr.url === 'string' ? qr.url.trim() : '';
  const activo = cr !== null && cb.activo !== false && cbUrlSegura(url);
  if (!activo) {
    return {
      activo: false, qrUrl: '', titular: '', banco: '', pendiente: false, monto: null,
      pedidoRef: '', vencidoHaceMin: null, venceEl: '',
    };
  }
  const monto = cbTotalValido(cb.monto);
  const vencido = typeof cb.vencidoHaceMin === 'number' && Number.isFinite(cb.vencidoHaceMin) && cb.vencidoHaceMin >= 0
    ? Math.floor(cb.vencidoHaceMin) : null;
  return {
    activo: true,
    qrUrl: url,
    titular: cbLinea(cr.nombreCuenta, 120),
    banco: cbLinea(cr.banco, 80),
    // Un QR esperando comprobante: lo dice el servidor mirando a ESTE teléfono.
    pendiente: cb.pendiente === true,
    monto: monto,
    pedidoRef: typeof cb.pedido === 'string' ? cbLinea(cb.pedido, 120) : '',
    vencidoHaceMin: vencido,
    // El último día de vigencia del QR (`aaaa-mm-dd`, el que registró el comercio). Solo se copia; `cbQrVencido` lo interpreta.
    // Tal cual, sin recortar a 10 ni limpiar: el servidor exige el formato exacto, y un valor ilegible aquí debe seguir siendo ilegible.
    venceEl: typeof cr.venceEl === 'string' ? cr.venceEl.slice(0, 40) : '',
  };
}

// `cuerpoPanel` = cuerpo de `configuracionFlujo`; `base` = «Config base». null si no corresponde simulado.
function cbCobroSimulado(cuerpoPanel, base) {
  const r = cbEsObjeto(cuerpoPanel) ? cuerpoPanel : null;
  const b = cbEsObjeto(base) ? base : null;
  if (!r || !b) return null;
  if (r.cobroReal !== undefined) return null;          // EXCLUSIÓN: si el cuerpo trae `cobroReal` (aunque sea null, vacío o no sirva), nunca simulado
  if (!cbEsObjeto(r.cobroSimulado)) return null;       // el servidor no declaró simulado
  if (b.cobroSimuladoActivo !== true) return null;     // solo el booleano true (ni «true», ni 1)
  const url = typeof b.qrSimuladoUrl === 'string' ? b.qrSimuladoUrl.trim() : '';
  if (!cbUrlSegura(url)) return null;
  const cb = cbEsObjeto(r.cobro) ? r.cobro : {};
  const vencido = typeof cb.vencidoHaceMin === 'number' && Number.isFinite(cb.vencidoHaceMin) && cb.vencidoHaceMin >= 0
    ? Math.floor(cb.vencidoHaceMin) : null;
  return {
    activo: false, modo: 'simulado', qrUrl: url, titular: '', banco: '',
    pendiente: cb.pendiente === true, monto: cbTotalValido(cb.monto),
    pedidoRef: typeof cb.pedido === 'string' ? cbLinea(cb.pedido, 120) : '', vencidoHaceMin: vencido,
  };
}

// ¿Hay un QR que mandar? Real encendido con https, o simulado (activo false) con https. Nunca los dos.
function cbHayQr(cobro) {
  const c = cbEsObjeto(cobro) ? cobro : {};
  if (!cbUrlSegura(c.qrUrl)) return false;
  if (c.modo === 'real') return c.activo === true;
  if (c.modo === 'simulado') return c.activo !== true;
  return false;
}

// ¿El QR del cobro REAL ya venció? MISMO criterio que la Function `imagenDeCobro` (modulos/cobros/cobro.ts, `finDelDiaBoliviano`): `venceEl` (`aaaa-mm-dd`)
// vale hasta las 23:59:59 de ESE día en Bolivia (UTC-4 fijo) y está vencido si ese instante ya pasó (`<=`). Sin fecha, o con una que no tiene el formato exacto,
// NO está vencido: el servidor tampoco bloquea la imagen en ese caso (registros anteriores al campo). `ahoraMs` es el del turno (nunca el reloj suelto).
// Solo aplica al modo real: el QR simulado no vence. Un QR vencido el servidor lo responde con 404, así que ofrecerlo promete una imagen que no llega.
function cbQrVencido(cobro, ahoraMs) {
  const c = cbEsObjeto(cobro) ? cobro : {};
  if (c.modo !== 'real') return false;
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(typeof c.venceEl === 'string' ? c.venceEl : '');
  if (!m) return false;
  const finDelDia = Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3]), 23, 59, 59) + 4 * 3600000;
  const ahora = Number(ahoraMs);
  if (!Number.isFinite(finDelDia) || !Number.isFinite(ahora)) return false;
  return finDelDia <= ahora;
}

// ---------------------------------------------------------------------------
// El QR: pie y mensaje
// ---------------------------------------------------------------------------

// Voz 05/10 (6a): el resumen corto del pedido para el pie del QR y para la confirmación del comprobante: «1 × Birriamen, 2 × Taco de birria, recojo en el local»
// (hasta 3 productos y «… y N más»; sin dirección, sin precios ni notas: la dirección es un dato personal y el pie del QR sale al chat). `lineas` = las del pedido
// (nunca un precio del modelo, solo `cantidad` y `nombre`). '' si no hay nada que decir o si el texto cae en la red de frases prohibidas (el resumen se omite, no
// el mensaje); con `real` también se omite si un producto se llama «prueba»/«simulado»: el pie del QR real no puede traer esas palabras (`amQr`).
function cbResumenCorto(lineas, modalidad, opciones) {
  const o = cbEsObjeto(opciones) ? opciones : {};
  const partes = [];
  for (const l of Array.isArray(lineas) ? lineas : []) {
    if (!cbEsObjeto(l)) continue;
    const nombre = cbLinea(l.nombre, 40);
    const cant = Math.floor(Number(l.cantidad));
    if (nombre && cant >= 1) partes.push(cant + ' × ' + nombre);
  }
  if (!partes.length) return '';
  let txt = partes.slice(0, 3).join(', ') + (partes.length > 3 ? ', … y ' + (partes.length - 3) + ' más' : '');
  const entrega = modalidad === 'delivery' ? 'delivery' : (modalidad === 'recojo' ? 'recojo en el local' : '');
  if (entrega) txt += ', ' + entrega;
  const canon = cbCanon(txt);
  if (CB_PROHIBIDAS.test(canon)) return '';
  if (o.real === true && /simulad|simulacr|demostracion|prueba/.test(canon)) return '';
  return txt;
}

// El pie del QR (hasta 1.024 caracteres, el tope de Meta). `pedido` = {codigo, total}.
// Sin un total válido devuelve '': no se manda un QR sin decir cuánto se paga.
function cbCaption(pedido, opciones) {
  const p = cbEsObjeto(pedido) ? pedido : {};
  const o = cbEsObjeto(opciones) ? opciones : {};
  const total = cbTotalValido(p.total);
  if (total === null) return '';
  const codigo = cbCodigo(p.codigo);
  // El nombre del titular viene de la ficha del QR, no de un cliente; igual se
  // sanea, y si cae en la red de palabras prohibidas se omite.
  let titular = cbLinea(o.titular, 120);
  if (CB_PROHIBIDAS.test(cbCanon(titular))) titular = '';
  const resumenReal = cbResumenCorto(p.lineas, p.modalidad, { real: true });
  const resumenSim = cbResumenCorto(p.lineas, p.modalidad);
  const cabeza = codigo ? 'Pedido #' + codigo + (resumenSim ? ' (' + resumenSim + ')' : '') + '. ' : '';
  // Voz 05/10: el QR real abre agradeciendo y nombrando el pedido («¡Gracias por tu pedido! Es el #YZBL.»); el simulado conserva su rótulo y no se toca.
  const cabezaReal = codigo ? '¡Gracias por tu pedido! Es el #' + codigo + (resumenReal ? ': ' + resumenReal : '') + '.\n' : '¡Gracias por tu pedido!' + (resumenReal ? ' ' + resumenReal + '.' : '') + '\n';
  const delivery = o.delivery === true ? '; el delivery se paga aparte, al repartidor' : '';
  if (o.simulado === true) {
    // Simulado: el rótulo va primero y no se nombra al titular (no hay cuenta a la que pagar).
    const sim = CB_ROTULO_SIMULADO + '\n' + cabeza + 'Total de la prueba: ' + cbMonto(total) + ' ' + cbMoneda(o.moneda)
      + ' (solo la comida' + delivery + ').\n'
      + 'No intentes pagarlo: tu banco lo va a rechazar. Para seguir con la prueba, envíame aquí cualquier foto como comprobante simulado.';
    return sim.slice(0, 1024);
  }
  const texto = cabezaReal + 'Total a pagar con este QR: ' + cbMonto(total) + ' ' + cbMoneda(o.moneda)
    + ' (solo la comida' + delivery + ').\n'
    + 'Escanéalo con la app de tu banco' + (titular ? ' (la cuenta es de ' + titular + ')' : '')
    + ' y después envíame aquí la foto o el PDF del comprobante.';
  return texto.slice(0, 1024);
}

// El mensaje del QR en la forma del `Plan del turno`: la imagen con su pie, y lo
// que se reporta al servidor para que coteje contra ESE número (`qr_enviado`).
// `pedido` = {pedidoId, codigo, total}; `cobro` = lo que dio `cbCobroReal`.
// Devuelve null si no hay cobro real, QR https, pedido o total válido.
function cbMensajeQr(pedido, cobro, opciones) {
  const p = cbEsObjeto(pedido) ? pedido : {};
  const c = cbEsObjeto(cobro) ? cobro : {};
  const total = cbTotalValido(p.total);
  const id = typeof p.pedidoId === 'string' ? p.pedidoId.trim() : '';
  const url = typeof c.qrUrl === 'string' ? c.qrUrl : '';
  if (c.activo !== true || !cbUrlSegura(url) || total === null || id === '') return null;
  const o = cbEsObjeto(opciones) ? opciones : {};
  const cuerpo = cbCaption({ codigo: p.codigo, total: total, lineas: p.lineas, modalidad: p.modalidad }, {
    titular: c.titular, moneda: o.moneda, delivery: o.delivery === true,
  });
  return {
    tipo: 'imagen',
    cuerpo: cuerpo,
    url: url,
    // El respaldo, si Meta no acepta la imagen: el mismo pie y el enlace.
    respaldo: cuerpo + '\n\nAbre el QR aquí: ' + url,
    evento: 'qr_enviado',
    referencia: id,
    monto: total,
  };
}

// ---------------------------------------------------------------------------
// La lectura del comprobante (port de `interpretar-lectura.js` del Demo B)
// ---------------------------------------------------------------------------

// El texto de una respuesta de Gemini (generateContent, o el nodo de LangChain con
// `simplify`). '' si vino un error o algo que no se reconoce.
function cbTextoDeGemini(j) {
  if (!j || typeof j !== 'object' || j.error) return '';
  const partes = (c) => (c && Array.isArray(c.parts))
    ? c.parts.map((p) => (p && typeof p.text === 'string') ? p.text : '').join('\n') : '';
  if (typeof j.content === 'string') return j.content;
  const c1 = partes(j.content);
  if (c1) return c1;
  const cand = Array.isArray(j.candidates) ? j.candidates[0] : null;
  const c2 = cand ? partes(cand.content) : '';
  if (c2) return c2;
  for (const k of ['text', 'output', 'response']) {
    if (typeof j[k] === 'string' && j[k].trim()) return j[k];
  }
  return '';
}

// El ÚNICO objeto `{…}` de nivel superior del texto, ya interpretado. Si hay dos o
// más (una frase del modelo con otro JSON, un texto de la imagen que se coló) o no
// se puede interpretar, null: es ilegible y se pide de nuevo. Mejor pedirlo otra
// vez que elegir cuál de dos objetos creerle.
function cbObjetoUnico(texto) {
  const t = String(texto === undefined || texto === null ? '' : texto).slice(0, 20000);
  const objetos = [];
  let prof = 0;
  let ini = -1;
  let enCadena = false;
  let escape = false;
  for (let i = 0; i < t.length; i++) {
    const ch = t[i];
    if (enCadena) {
      if (escape) escape = false;
      else if (ch === '\\') escape = true;
      else if (ch === '"') enCadena = false;
      continue;
    }
    if (ch === '"' && prof > 0) { enCadena = true; continue; }
    if (ch === '{') {
      if (prof === 0) ini = i;
      prof++;
    } else if (ch === '}' && prof > 0) {
      prof--;
      if (prof === 0) objetos.push(t.slice(ini, i + 1));
    }
  }
  if (objetos.length !== 1) return null;
  try {
    const o = JSON.parse(objetos[0]);
    return cbEsObjeto(o) ? o : null;
  } catch (e) {
    return null;
  }
}

// Un campo leído: un número finito tal cual, o un texto corto sin controles. Solo
// claves PROPIAS del objeto, y cualquier otra cosa (objeto, lista, booleano) es ''.
function cbCampoLeido(o, k, max) {
  if (!Object.prototype.hasOwnProperty.call(o, k)) return '';
  const v = o[k];
  if (typeof v === 'number' && Number.isFinite(v)) return v;
  if (typeof v !== 'string') return '';
  return v.replace(/[\u0000-\u001f\u007f]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
}

// `respGemini` = el item que devolvió el nodo de Gemini (o el cuerpo de
// `generateContent`). Salen SEIS campos y `legible`; nada más. NO compara nada:
// compara el servidor, contra el total que se cotizó con el QR.
function cbLectura(respGemini) {
  const objeto = cbObjetoUnico(cbTextoDeGemini(respGemini)) || {};
  const leido = {
    monto: cbCampoLeido(objeto, 'monto', 40),
    cuentaDestino: cbCampoLeido(objeto, 'cuentaDestino', 60),
    nombreCuenta: cbCampoLeido(objeto, 'nombreCuenta', 120),
    fecha: cbCampoLeido(objeto, 'fecha', 40),
    hora: cbCampoLeido(objeto, 'hora', 20),
    banco: cbCampoLeido(objeto, 'banco', 80),
  };
  const legible = String(leido.monto) !== '' || String(leido.cuentaDestino) !== '';
  return { legible: legible, leido: leido };
}

// ---------------------------------------------------------------------------
// El resultado del cotejo (port de `respuesta-del-cobro.js`)
// ---------------------------------------------------------------------------

// `respCotejo` = la respuesta completa del HTTP (`{statusCode, body}`).
//   cuadra | no_cuadra | ilegible  -> 200 con ese resultado.
//   ya_cotejado                    -> 409 `sin_sena_pendiente`: el servidor ya cerró
//                                     ese pedido con un comprobante que cuadró.
//   sin_cotejo                     -> todo lo demás (otro 409, error, sin respuesta).
// `previo` (opcional) es el resultado que ya se guardó del pedido: con un 409
// `sin_sena_pendiente`, solo se dice `ya_cotejado` si ese resultado fue `cuadra`
// (si el QR venció, no se afirma que ya hay un comprobante aceptado).
function cbResultado(respCotejo, previo) {
  const r = cbEsObjeto(respCotejo) ? respCotejo : {};
  const codigo = Number(r.statusCode);
  let cuerpo = r.body;
  if (typeof cuerpo === 'string') {
    try { cuerpo = JSON.parse(cuerpo); } catch (e) { cuerpo = {}; }
  }
  cuerpo = cbEsObjeto(cuerpo) ? cuerpo : {};
  const diferencias = Array.isArray(cuerpo.diferencias)
    ? cuerpo.diferencias.map((d) => cbLinea(d, 240)).filter(Boolean).slice(0, 10) : [];
  const importe = typeof cuerpo.importe === 'number' && Number.isFinite(cuerpo.importe) && cuerpo.importe > 0
    ? cuerpo.importe : null;
  const cierreId = typeof cuerpo.cierreId === 'string' ? cbLinea(cuerpo.cierreId, 160) : '';
  let resultado = 'sin_cotejo';
  if (codigo === 200 && ['cuadra', 'no_cuadra', 'ilegible'].indexOf(cuerpo.resultado) >= 0) {
    resultado = cuerpo.resultado;
  } else if (codigo === 409 && cuerpo.error === 'sin_sena_pendiente'
    && (previo === undefined || previo === 'cuadra')) {
    resultado = 'ya_cotejado';
  }
  return {
    resultado: resultado,
    diferencias: resultado === 'no_cuadra' ? diferencias : [],
    importe: importe,
    cierreId: cierreId,
  };
}

// La ruta que devolvió `guardarComprobante` (200 `{ruta}`), o null: cualquier otra cosa (409 sin cobro de regla 2 abierto, 413, 415, 502, un error de red, una
// ruta que no tiene la forma `tenants/<comercio>/comprobantes/<aaaa-mm-dd>/<nombre>.<jpg|png|webp|pdf>`) es «no se guardó». El cotejo corre igual, con `ruta: null`.
// (Misma función que la de `rroca-ruben`; el servidor la vuelve a validar con `rutaValidaDe`: este patrón no es el límite, es la primera defensa.)
function cbRutaGuardada(resp) {
  const r = cbEsObjeto(resp) ? resp : {};
  let cuerpo = r.body;
  if (typeof cuerpo === 'string') {
    try { cuerpo = JSON.parse(cuerpo); } catch (e) { cuerpo = {}; }
  }
  if (Number(r.statusCode) !== 200 || !cbEsObjeto(cuerpo) || typeof cuerpo.ruta !== 'string') return null;
  const ruta = cuerpo.ruta;
  return ruta.length <= 300 && /^tenants\/[A-Za-z0-9_-]{1,60}\/comprobantes\/\d{4}-\d{2}-\d{2}\/[A-Za-z0-9_-]{1,100}\.(?:jpg|png|webp|pdf)$/.test(ruta) ? ruta : null;
}

// ---------------------------------------------------------------------------
// Qué se le dice al cliente y qué se le avisa al restaurante
// ---------------------------------------------------------------------------

// El estado que va en {{1}} del aviso. null = este resultado no genera aviso
// (`ya_cotejado`). Sin resultado de cotejo (`sin_qr` o vacío) es el plan B.
function cbEstadoParaAviso(resultado) {
  if (resultado === 'cuadra') return 'comprobante: datos coinciden';
  if (resultado === 'no_cuadra') return 'comprobante: NO coinciden';
  if (resultado === 'ilegible') return 'comprobante ilegible';
  if (resultado === 'sin_cotejo') return 'comprobante sin cotejar';
  if (resultado === 'ya_cotejado') return null;
  if (resultado === 'simulado') return 'PRUEBA: cobro SIMULADO, sin dinero';
  if (resultado === 'qr_vencido') return 'QR vencido: coordinar el pago';
  return 'sin QR: cobrar al entregar';
}

// Un importe como lo escribe el servidor («21.00», «1,5», «1.234,50») en la forma de Bolivia, sin decimales sobrantes: «21», «1,50», «1234,50». Con un solo
// separador, es el decimal; con los dos, el que aparece último es el decimal. Un valor que no es un número finito se deja como llegó (ya solo trae dígitos y separadores).
function cbImporteDelServidor(t) {
  const x = String(t);
  const ult = Math.max(x.lastIndexOf('.'), x.lastIndexOf(','));
  const n = ult < 0 ? Number(x) : Number(x.slice(0, ult).replace(/[.,]/g, '') + '.' + x.slice(ult + 1));
  return Number.isFinite(n) ? cbMonto(n) : x;
}

// Las diferencias que da el servidor, a una frase FIJA. Lo leído de la imagen (un
// nombre, una cuenta) NUNCA se copia al cliente: ahí puede venir cualquier texto.
// Solo pasan dos números, que el servidor ya tradujo de la lectura. Reconoce la
// primera que sabe decir; si no reconoce ninguna, ''.
function cbDiferencia(diferencias, moneda) {
  const lista = Array.isArray(diferencias) ? diferencias : [diferencias];
  for (let i = 0; i < lista.length; i++) {
    const d = String(lista[i] === undefined || lista[i] === null ? '' : lista[i]);
    // Cada patrón se ancla al INICIO de la frase del servidor: un nombre leído de la
    // imagen que repita otra frase no cambia cuál se reconoce.
    const m = /^\s*El comprobante dice (\d+(?:[.,]\d+)*) y el pedido es de (\d+(?:[.,]\d+)*)/i.exec(d);
    if (m) return 'el comprobante dice ' + cbImporteDelServidor(m[1]) + ' ' + cbMoneda(moneda) + ' y tu pedido es de ' + cbImporteDelServidor(m[2]) + ' ' + cbMoneda(moneda);
    if (/^\s*No se pudo leer el importe/i.test(d)) return 'no pude leer el importe';
    if (/^\s*No se pudo leer la fecha/i.test(d)) return 'no pude leer la fecha';
    if (/^\s*El comprobante es anterior al pedido/i.test(d)) return 'la fecha del comprobante es anterior a tu pedido';
    if (/^\s*El comprobante tiene una fecha posterior/i.test(d)) return 'la fecha del comprobante no es correcta';
    if (/^\s*El comprobante no muestra a qué cuenta/i.test(d)) return 'en el comprobante no se ve a qué cuenta se depositó';
    if (/^\s*El depósito fue a la cuenta/i.test(d)) return 'la cuenta de destino no es la del QR';
    if (/^\s*El depósito figura a/i.test(d)) return 'el nombre del destinatario no coincide con el de la cuenta';
  }
  return '';
}

// El texto al cliente según el resultado. `opciones`:
//   codigo      el código corto del pedido;
//   avisoSalio  true SOLO si Meta devolvió un `wamid` para al menos un aviso;
//   diferencia  la diferencia (texto o lista) que dio el servidor;
//   ilegibles   cuántos comprobantes ilegibles lleva el pedido, contando este;
//   entrega     'delivery' o 'recojo' (para `sin_qr`);
//   moneda      la moneda del negocio («Bs») para decir los montos de una diferencia.
// Devuelve {cuerpo, enlace, aviso}: `enlace` = lleva el botón «Escribir al local»;
// `aviso` = hay que avisar a nuestro equipo (y de ahí depende `avisoSalio`).
// «Ya lo pasé a nuestro equipo» solo sale con `avisoSalio === true`: nunca se promete lo que no se cumplió (`AM_PASE` lo atrapa si no). El texto nunca llama
// «pago» a un comprobante que no es el banco (prohibición 3): se agradece el COMPROBANTE («Gracias por enviar tu comprobante»), nunca «gracias por tu pago».
// Voz 05/10: el restaurante habla en «nosotros / nuestro equipo»; nada de «ellos», «escríbeles» ni «con los datos que leí».
function cbTextoAlCliente(resultado, opciones) {
  const o = cbEsObjeto(opciones) ? opciones : {};
  const cod = cbCodigo(o.codigo);
  const pedido = cod ? 'tu pedido #' + cod : 'tu pedido';
  // Voz 05/10 (6a): cuando los datos coinciden, la confirmación dice de qué pedido se trata («tu pedido #X (1 × …, recojo en el local)»).
  const resumen = cbLinea(o.resumen, 200);
  const pedidoCon = resumen && cod ? pedido + ' (' + resumen + ')' : pedido;
  const salio = o.avisoSalio === true;
  const sinAviso = 'No pude pasarle tu pedido a nuestro equipo en este momento: escríbenos directamente con el botón.';
  const guardar = 'Guarda tu comprobante por si te lo pedimos.';
  const gracias = 'Gracias por enviar tu comprobante.';

  if (resultado === 'cuadra') {
    return salio
      ? {
        cuerpo: gracias + ' Los datos coinciden con ' + pedidoCon + '. Ya lo pasé a nuestro equipo, que revisa el pago en nuestro banco antes de despachar tu pedido.',
        enlace: false, aviso: true,
      }
      : {
        cuerpo: gracias + ' Los datos coinciden con ' + pedidoCon + '. ' + sinAviso,
        enlace: true, aviso: true,
      };
  }
  if (resultado === 'no_cuadra') {
    const dif = cbDiferencia(o.diferencia, o.moneda);
    const veo = 'Veo una diferencia con ' + pedido + (dif ? ': ' + dif : '') + '.';
    return {
      cuerpo: salio
        ? gracias + ' ' + veo + ' Ya lo pasé a nuestro equipo para que lo revise; guárdalo por si te lo pedimos. Si quieres escribirnos directamente, toca el botón.'
        : gracias + ' ' + veo + ' ' + sinAviso + ' ' + guardar,
      enlace: true, aviso: true,
    };
  }
  if (resultado === 'ilegible') {
    const n = Number(o.ilegibles);
    if (!(n >= 2)) {
      return {
        cuerpo: 'Gracias por enviarlo. No pude leer bien tu comprobante: ¿me lo envías de nuevo, más nítido o en PDF desde la app de tu banco?',
        enlace: false, aviso: false,
      };
    }
    return {
      cuerpo: salio
        ? 'Gracias por enviarlo de nuevo. Como no se lee bien, ya lo pasé a nuestro equipo para que revise ' + pedido + ' directamente; guárdalo por si te lo pedimos. Si quieres escribirnos, toca el botón.'
        : 'Gracias por enviarlo de nuevo. Como no se lee bien, ' + sinAviso.charAt(0).toLowerCase() + sinAviso.slice(1) + ' ' + guardar,
      enlace: true, aviso: true,
    };
  }
  if (resultado === 'sin_cotejo') {
    return {
      cuerpo: salio
        ? 'Gracias por enviar el comprobante de ' + pedido + '. Ya lo pasé a nuestro equipo para que lo revise directamente; guárdalo por si te lo pedimos. Si quieres escribirnos, toca el botón.'
        : 'Gracias por enviar el comprobante de ' + pedido + '. ' + sinAviso + ' ' + guardar,
      enlace: true, aviso: true,
    };
  }
  if (resultado === 'simulado') {
    const cabezaSim = 'Recibí tu comprobante SIMULADO de ' + pedido + '. Es una prueba: no se movió dinero.';
    return salio
      ? { cuerpo: cabezaSim + ' Ya lo pasé a nuestro equipo como pedido de PRUEBA.', enlace: false, aviso: true }
      : { cuerpo: cabezaSim + ' ' + sinAviso, enlace: true, aviso: true };
  }
  if (resultado === 'ya_cotejado') {
    return {
      cuerpo: 'Ya tengo el comprobante de ' + pedido + '. Si necesitas algo más, toca el botón.',
      enlace: true, aviso: false,
    };
  }
  if (resultado === 'sin_qr') {
    // Plan B: sin cobro real, el pago se coordina con nuestro equipo.
    return salio
      ? {
        cuerpo: 'Listo: pasé ' + pedido + ' a nuestro equipo. El pago lo coordinas con nosotros '
          + (o.entrega === 'delivery' ? 'al recibir' : 'al recoger') + '.',
        enlace: false, aviso: true,
      }
      : { cuerpo: sinAviso, enlace: true, aviso: true };
  }
  if (resultado === 'qr_vencido') {
    // El QR real venció: no se ofrece el QR ni el total a pagar. Lo único que se ofrece es pasar con recepción (aviso + botón «Escribir al local»).
    const cabeza = 'No puedo mostrarte el QR en este momento.';
    return salio
      ? { cuerpo: cabeza + ' Pasé ' + pedido + ' a nuestro equipo. Para coordinar el pago, toca «Escribir al local» y lo ves directamente con ellos.', enlace: true, aviso: true }
      : { cuerpo: cabeza + ' No pude pasarle tu pedido a nuestro equipo: escríbenos directamente con el botón.', enlace: true, aviso: true };
  }
  return { cuerpo: 'Eso lo ve directamente nuestro equipo. Toca el botón para escribirnos.', enlace: true, aviso: false };
}

// MÓDULO PEDIDOS — LO QUE EL FLUJO REPORTA AL ENVIAR EL QR PARA QUE EL SERVIDOR CREE EL PEDIDO `wa_<referencia>`.
// Se INCLUYE en los flujos que lo usan (construir.mjs), nunca se copia. Funciones puras, sin red ni globales de Node.
//
// El servidor (admin/functions/src/modulos/pedidos/pedidoDelQr.ts) recalcula precios y total desde el catálogo del tenant:
// del flujo salen SOLO identificadores, cantidades y un detalle de texto. Aquí nunca viaja precio, nombre, total ni la
// facturación del cliente: ese dato no sale del flujo por este camino.
const PQR_MAX_LINEAS = 30;
const PQR_MAX_DETALLE = 120;
const PQR_MAX_DIRECCION = 200;
function _pqrTexto(v, max) {
  if (typeof v !== 'string') return '';
  return v.slice(0, 1000).replace(/[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Zl}\p{Zp}<>&]/gu, ' ')
    .replace(/\s+/g, ' ').trim().slice(0, max).trim();
}
// Recorta a `max` sin partir un par sustituto (emoji): si el corte cae entre las dos mitades, se quita la mitad que quedó.
function _pqrCorta(t, max) {
  let r = t.slice(0, max);
  if (/[\ud800-\udbff]$/.test(r)) r = r.slice(0, -1);
  return r.trim();
}
// [{id, cantidad, detalle}] — junta el mismo id sumando cantidades (el servidor se queda solo con la primera línea de cada id).
// Con más de una variante de detalle se anota la cantidad de cada una: «1 sin indicación · 1 sin cebolla».
// La suma NO se recorta: si pasa de 50 se manda tal cual y el servidor descarta esa línea y la deja en `descartados`
// (armarPedidoWa), en vez de que el pedido diga menos unidades de las que el cliente pidió.
function pqrLineas(lineas) {
  const porId = new Map();
  const orden = [];
  const crudas = Array.isArray(lineas) ? lineas.slice(0, PQR_MAX_LINEAS) : [];
  for (const l of crudas) {
    if (!l || typeof l !== 'object') continue;
    const id = l.id;
    if (typeof id !== 'string' || !/^[A-Za-z0-9][A-Za-z0-9._-]{0,79}$/.test(id) || id.includes('..')) continue;
    const c = typeof l.cantidad === 'number' ? Math.trunc(l.cantidad)
      : (typeof l.cantidad === 'string' && /^\s*\d{1,3}\s*$/.test(l.cantidad) ? Number(l.cantidad) : NaN);
    if (!Number.isFinite(c) || c < 1) continue;
    const detalle = _pqrTexto(l.detalle, PQR_MAX_DETALLE);
    let p = porId.get(id);
    if (!p) { p = { id: id, cantidad: 0, variantes: new Map() }; porId.set(id, p); orden.push(p); }
    p.cantidad += c;
    p.variantes.set(detalle, (p.variantes.get(detalle) || 0) + c);
  }
  return orden.map((p) => {
    let detalle = '';
    if (p.variantes.size === 1) detalle = Array.from(p.variantes.keys())[0];
    else if (p.variantes.size > 1) {
      detalle = _pqrCorta(Array.from(p.variantes.entries()).map((e) => e[1] + ' ' + (e[0] || 'sin indicación')).join(' · '), PQR_MAX_DETALLE);
    }
    return { id: p.id, cantidad: p.cantidad, detalle: detalle };
  });
}
function _pqrUbicacion(u) {
  if (!u || typeof u !== 'object' || Array.isArray(u)) return null;
  const lat = u.lat; const lng = u.lng;
  if (typeof lat !== 'number' || typeof lng !== 'number' || !isFinite(lat) || !isFinite(lng)) return null;
  if (lat < -90 || lat > 90 || lng < -180 || lng > 180) return null;
  if (lat === 0 && lng === 0) return null;
  return { lat: lat, lng: lng };
}
// {tipo:'envio', direccion, ubicacion?} para delivery, {tipo:'retiro'} para lo demás.
function pqrEntrega(e) {
  const x = e && typeof e === 'object' ? e : {};
  const crudo = [x.entrega, x.modalidad, x.tipo].find((v) => typeof v === 'string' && v);
  const t = String(crudo || '').toLowerCase().trim();
  if (!/^(delivery|domicilio|envio|envío|courier|encomienda)$/.test(t)) return { tipo: 'retiro' };
  const dir = _pqrTexto(x.direccion, PQR_MAX_DIRECCION);
  const ref = _pqrTexto(x.referencia || x.ciudad, PQR_MAX_DIRECCION);
  const direccion = _pqrTexto(dir && ref ? dir + ' · ' + ref : (dir || ref), PQR_MAX_DIRECCION);
  const ub = _pqrUbicacion(x.ubicacion);
  const out = { tipo: 'envio' };
  if (direccion) out.direccion = direccion;
  if (ub) out.ubicacion = ub;
  return out;
}
// Los campos extra del mensaje `qr_enviado`. {} si es simulado, si el pedido es del checkout web (`cat_…`: ya lo creó el servidor)
// o si no queda ninguna línea. NUNCA devuelve facturación.
// `catOriginal` es el `cat_…` del checkout web que este pedido modificó en el chat: viaja como `reemplaza` (solo esa cadena, validada)
// para que el servidor marque el pedido web como reemplazado y la Consola no muestre dos pedidos por una compra.
function pqrCampos(ref, lineas, entrega, simulado, catOriginal) {
  if (simulado) return {};
  if (typeof ref !== 'string' || ref === '' || ref.indexOf('cat_') === 0) return {};
  const ls = pqrLineas(lineas);
  if (!ls.length) return {};
  const out = { lineas: ls, entrega: pqrEntrega(entrega) };
  if (typeof catOriginal === 'string' && /^cat_[A-Za-z0-9_-]{1,56}$/.test(catOriginal)) out.reemplaza = catOriginal;
  return out;
}

// EL ANUNCIO SE RECONOCE POR SU TITULAR, Y LO DECIDE EL CODIGO (PR-3 de core, 23/10/2026).
//
// QUE RESUELVE. Un cliente manda la captura de un anuncio del negocio. Hasta hoy el
// asistente comparaba el texto leido con lo que el prompt sabia de las campañas, y los
// anuncios de Ruben vivian CABLEADOS en su flujo. Ahora el anuncio es un DATO del tenant
// (la clave `anuncios` de `configuracionFlujo`, solo vigentes y aprobados) y la
// coincidencia la decide este codigo; el modelo nunca decide que anuncio es.
//
// CONTRATO.  anuncioPorTitular(titularLeido, anuncios) -> anuncio | null
//   anuncios = [{ id, titulares: [<=3 textos], angulo, producto: {id,nombre,precio,agotado}|null }]
//   Devuelve una COPIA saneada { id, titular, angulo, producto }: `titular` es el CANONICO
//   del dato (titulares[0]), NUNCA el texto leido de la imagen. Sin coincidencia, null.
//
// NIVELES, en este orden (el primero que algun anuncio cumpla gana):
//   1) igualdad con algun titular
//   2) el titular del DATO, con 3 palabras o mas, esta contenido en lo leido (palabras completas)
//   3) similitud de Dice por bigramas >= 0,85, con 12 caracteres o mas y las MISMAS cifras
// Se calcula el nivel de TODOS los anuncios: si coinciden varios en niveles distintos, o varios por
// contencion con el mismo largo, no hay coincidencia (null). Una igualdad unica siempre gana.
// Si dos anuncios DISTINTOS cumplen el mejor nivel, no hay coincidencia (null): ante la
// duda el asistente cae en su comportamiento de siempre, que es preguntar.
//
// NORMALIZACION: NFKC; NFD sin diacriticos; minusculas; homoglifos cirilicos y griegos a
// latinos; lo que no sea [a-z0-9] pasa a espacio; espacios colapsados.
//
// ENTRADA MALA (no es array, vacio, elementos sin id o sin titulares): null, sin lanzar.
//
// QUIEN LO USA. `preparar-imagen.js` (se incluye DESPUES de este archivo en el mismo nodo
// Code). Cada flujo cuyo clasificador de imagen quiera este reconocimiento debe pedir en
// su esquema el campo `titular_principal`: «el titular PRINCIPAL: el texto mas grande o el
// de mas arriba, nunca una insignia de precio». Eso lo adopta cada cliente en su propio
// prompt; sin el campo, o sin `anuncios` en `Config del negocio`, todo queda como antes.
const anuncioPorTitular = (() => {
  const DE = 'аеорсухіѕјԁοανρτκιε';
  const A = 'aeopcyxisjdoavptkie';
  const TILDES = new RegExp('[\\u0300-\\u036f]', 'g');
  const norm = (v) => {
    if (typeof v !== 'string') return '';
    const base = v.slice(0, 500).normalize('NFKC').normalize('NFD').replace(TILDES, '').toLowerCase();
    let s = '';
    for (const c of base) { const i = DE.indexOf(c); s += i >= 0 ? A.charAt(i) : c; }
    return s.replace(/[^a-z0-9]+/g, ' ').trim();
  };
  const palabras = (s) => (s ? s.split(' ') : []);
  const contiene = (grande, chico) => (' ' + grande + ' ').indexOf(' ' + chico + ' ') >= 0;
  const bigramas = (s) => {
    const m = new Map();
    for (let i = 0; i < s.length - 1; i++) { const b = s.slice(i, i + 2); m.set(b, (m.get(b) || 0) + 1); }
    return m;
  };
  const dice = (a, b) => {
    if (a.length < 2 || b.length < 2) return 0;
    const ma = bigramas(a);
    const mb = bigramas(b);
    let comun = 0;
    for (const [k, n] of ma) comun += Math.min(n, mb.get(k) || 0);
    return (2 * comun) / ((a.length - 1) + (b.length - 1));
  };
  // { nivel, largo } si el texto leido coincide con ese titular; nivel 0 si no.
  //  1) igualdad  2) el titular DEL DATO (>= 3 palabras) esta contenido en lo leido, por palabras completas
  //  3) Dice >= 0,85 con 12 caracteres o mas Y las mismas cifras en el mismo orden ('3x1' no es '2x1').
  const cifras = (x) => (x.match(/\d+/g) || []).join(',');
  const nivelContra = (t, h) => {
    if (!t || !h) return { nivel: 0, largo: 0 };
    if (t === h) return { nivel: 1, largo: h.length };
    if (palabras(h).length >= 3 && contiene(t, h)) return { nivel: 2, largo: h.length };
    if (t.length >= 12 && h.length >= 12 && cifras(t) === cifras(h) && dice(t, h) >= 0.85) return { nivel: 3, largo: h.length };
    return { nivel: 0, largo: 0 };
  };
  // Un campo con caracteres de control, bidireccionales o de ancho cero se OMITE (queda vacio), no se limpia.
  const RARO = new RegExp('[\\u0000-\\u001f\\u007f-\\u009f\\u200b-\\u200f\\u202a-\\u202e\\u2060-\\u206f\\ufeff\\u00ad]');
  const texto = (v, tope) => (typeof v === 'string' && !RARO.test(v)
    ? v.replace(/[\[\]{}<>"`]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, tope) : '');
  const producto = (p) => {
    if (!p || typeof p !== 'object' || Array.isArray(p)) return null;
    const nombre = texto(p.nombre, 120);
    if (!nombre) return null;
    const precio = (typeof p.precio === 'number' && Number.isFinite(p.precio)) ? p.precio
      : (typeof p.precio === 'string' && p.precio.trim() !== '' ? texto(p.precio, 40) : null);
    return { id: texto(typeof p.id === 'string' ? p.id : '', 80), nombre, precio, agotado: p.agotado === true };
  };
  return (titularLeido, anuncios) => {
    try {
      const t = norm(titularLeido);
      if (!t || !Array.isArray(anuncios)) return null;
      const validos = [];
      for (const a of anuncios.slice(0, 50)) {
        if (!a || typeof a !== 'object' || Array.isArray(a)) continue;
        const id = typeof a.id === 'string' ? a.id.trim() : '';
        const crudos = Array.isArray(a.titulares) ? a.titulares.filter((x) => typeof x === 'string' && norm(x) !== '') : [];
        if (!id || !crudos.length) continue;
        validos.push({ a, id, crudos: crudos.slice(0, 3) });
      }
      // El nivel de TODOS los anuncios, antes de decidir: nadie gana solo por mirarse primero.
      const hallados = [];
      for (const v of validos) {
        let mejorDe = { nivel: 0, largo: 0 };
        for (const c of v.crudos) {
          const r = nivelContra(t, norm(c));
          if (r.nivel && (!mejorDe.nivel || r.nivel < mejorDe.nivel || (r.nivel === mejorDe.nivel && r.largo > mejorDe.largo))) mejorDe = r;
        }
        if (mejorDe.nivel) hallados.push({ v, ...mejorDe });
      }
      if (!hallados.length) return null;
      const ids = new Set(hallados.map((h) => h.v.id));
      let ganadores;
      if (ids.size === 1) ganadores = [hallados[0]];
      else {
        // Varios anuncios distintos coinciden. Solo se resuelve si hay igualdad (nivel 1) unica, o si todos son
        // contencion (nivel 2) y uno contiene un titular estrictamente mas largo que los demas. Todo lo demas: ninguno.
        const igualdad = hallados.filter((h) => h.nivel === 1);
        if (igualdad.length) ganadores = igualdad;
        else if (hallados.every((h) => h.nivel === 2)) {
          const tope = Math.max(...hallados.map((h) => h.largo));
          ganadores = hallados.filter((h) => h.largo === tope);
        } else return null;
        if (new Set(ganadores.map((h) => h.v.id)).size !== 1) return null;
      }
      const g = ganadores[0].v;
      return { id: texto(g.id, 80), titular: texto(g.crudos[0], 100),
        angulo: texto(g.a.angulo, 300), producto: producto(g.a.producto) };
    } catch (e) { return null; }
  };
})();

// DECIDIR TURNO («Venta mínima v0»): qué hace este turno, ANTES de llamar a ningún modelo.
//
// Todo lo que no necesita entender lenguaje se decide acá, con código: el resultado del
// cotejo, los medios, los botones, la campaña, la derivación a una persona, la pregunta por
// la identidad, los reinicios, las consultas fijas y el horario. SOLO el texto libre de un
// pedido o de una reserva va al modelo (`accion: 'extraer_pedido' | 'extraer_reserva'`), y
// solo para EXTRAER datos: ningún texto al cliente sale del modelo.
//
// UN «SÍ» ESCRITO NO CONFIRMA NADA. Un pedido o una reserva se confirman tocando el botón
// (`p|confirmar`, `r|enviar`): con un «sí», «dale» u «ok» suelto en un paso de confirmación
// se vuelve a mostrar el paso con sus botones (`accion: 'boton'`, `boton: null`).
//
// El estado NO se escribe acá: se lee (del servidor: `vmSes`), se copia (`estado`) y lo fija `Plan del turno`; lo
// compromete `Armar mensajes` ANTES de enviar.
//
// ORDEN (diseño §4.5, sin modelo): 1) cotejo, o comprobante simulado → `comprobante`; 2) medios (imagen o documento
// sin QR pendiente, audio); 3) botón, validado contra el estado; 4) texto exacto de una
// campaña vigente → `promo`; 5) pide una persona → `transferir`, pregunta si es una IA →
// `identidad` (la identidad se revisa primero); 5b) pide EXPRESAMENTE la ubicación o la dirección del LOCAL → `consulta:direccion_local`
// (09/10, Q'Taco: en cualquier paso y también por audio; `Plan del turno` responde SIN tocar el estado); 6) intenciones GLOBALES, en cualquier paso salvo
// `esperando_comprobante` (ahí «menú» y pedir una persona NO sacan del cobro: se conserva el paso): «menú», «cancelar», «carta», «reserva» y,
// estando en una reserva, «pedir»; 7) en `inicio` o `menu`, consulta fija; 8) por paso; 9) pedido
// fuera de horario.
//
// CARRITO Y RESERVA VIVEN POR SEPARADO (03/10): ninguna transición borra uno por pasar al otro. Solo se
// limpian al confirmar, al cancelar (`limpiar` = 'pedido' | 'reserva' | 'todo' en la salida de `menu`) o al
// vencer el estado. «Menú» (texto o botón `m|menu`) muestra el menú y no borra el carrito ni la reserva (el paso pasa a `menu`); con un
// comprobante en espera conserva el paso y el pedido, y muestra el recordatorio del comprobante (`Plan del turno`: `aMenu`).
//
// EL CARRITO DEL CATÁLOGO WEB (`tipo: 'carrito'`) no es un mensaje de WhatsApp: se decide antes que todo lo demás, en
// `decidirCarrito` (ventana cerrada, panel sin respuesta, otro comercio, pedidos apagados, local cerrado, QR pendiente).
//
// LIBRERÍAS QUE LLAMA (contrato §4.2; en la suite van dobles mínimos):
//   comun: vmCfg, vmPrimero, vmNodo, vmSes, vmEstadoBase, vmLeerEstado, vmLeerBoton, vmNorm,
//     vmLinea, vmRecorte, vmTextoDeGemini, vmHorario, vmAbierto.
//   pedido: pdCarta, pdCuerpoExtraccion.   reserva: rsCuerpoExtraccion.   promos: prCampanaDelTexto, prVariacion, prPreguntaSinResponder, prCampanaDelReferral, prCampanaDeLaImagen, prTipoDeCampana.   core/medios: anuncioPorTitular.
//
// SUPUESTOS DECLARADOS (los de la tarea T7a, aprobados por la coordinadora):
//  1. `entrega` (en el estado) = {entrega, modalidad, direccion, referencia, nombre}.
//  6. `accion: 'boton'` con `boton: null` = «mostrar el paso actual» (botón viejo o no
//     válido en este paso, «sí» suelto, ubicación, pregunta orden/unidad pendiente); el
//     porqué va en `motivo` (`boton_viejo`, `si_suelto`, `ubicacion`, `forma_pendiente`).
//  7. «Pide una persona» exige «hablar con (una) persona/alguien/humano…» (o «quiero un
//     asesor», «pásame con el encargado») o una palabra inequívoca (reclamo, queja, humano);
//     (06/11: también «escribir al local» —la frase del botón— y «hablar con el local», que derivan igual que el botón; «escribir mi nombre» no.)
//     «persona», «asesor» o «encargado» sueltos NO derivan («mesa para 1 persona», «déjalo con el
//     encargado del edificio»). La pregunta por la identidad se revisa primero.
// SUPUESTOS PROPIOS (a confirmar en la integración):
//  a. Las banderas de capacidad (`pedidosActivo`, `reservasActivo`, `promosActivo`) valen
//     solo si son `true` (lo mismo que `promos.js`); la lista de áreas y de zonas se pasa a
//     `pd*`/`rs*` como arreglo (acepta también un CSV en la configuración).
//  b. El estado por teléfono tiene, además de lo de `vmEstadoBase()`: `paso`, `carrito`,
//     `pendiente`, `entrega`, `reserva`, `pedido`, `vacias`, `ilegibles`, `transferencias`.
//  c. Un botón `m|*` vale en cualquier paso salvo `esperando_comprobante`, donde solo `m|menu` vale;
//     `g|pedir|<id>` y `g|agregar|<id>|<cantidad>` valen en `inicio`, `menu` y los pasos de pedido; `f|<i>|<forma>`
//     con la pregunta `i` pendiente; `e|…` en `pedido_entrega`; `p|…` en `pedido_confirmar`;
//     `r|…` en `reserva_confirmar`; `q|…` en `esperando_comprobante`. En otro paso, un botón
//     viejo muestra el paso actual y no cambia nada. `q|cancelar` es `menu` con el pedido
//     descartado (`limpiar: 'pedido'`); `q|reenviar` es `reenviar_qr`. LÍMITE CONOCIDO: `q|cancelar` descarta el pedido del
//     estado pero NO avisa al servidor (el cobro abierto por `qr_enviado` vence solo): no se construye aquí.
//  d. «Hacer un pedido» (`m|pedido`) y «Ver la carta» son la misma acción: `carta`.
//  e. Sin horario en la configuración (`horario` vacío) no se bloquea ningún pedido; con un
//     horario ilegible tampoco, pero se anota en `errores`.
//  f. Una ubicación compartida no se toma como dirección (supuesto 6): muestra el paso
//     actual, que en `pedido_datos` vuelve a pedir la dirección por escrito. (`Plan del turno` la traduce a
//     `entrega.ubicacion`: con delivery, el paso de entrega la toma como dirección.)
//  g. Tipos de mensaje que no son texto, botón, audio, imagen, documento ni ubicación
//     (sticker, contactos, pedido de catálogo…) → `medio_no_leido`.
const cfg = vmCfg();
const t = vmPrimero('Interpretar entrada') || {};
const ahora = Number(t.ahoraMs) || Date.now();
const ses = vmSes(t.from, ahora);
const previo = Object.assign(estadoBase(), vmLeerEstado(ses, t.from, ahora));
const estado = Object.assign({}, previo, { ultimoMensajeMs: ahora });
// El ANCLA de las claves estables (B0): el `ultimoMensajeMs` del estado tal como se LEYO, antes de ponerle la hora de este
// turno. Dos ejecuciones simultaneas (doble toque) leen el mismo estado y ven la misma ancla; `Plan del turno` la usa para
// derivar `pedidoId`, el codigo y la referencia de la reserva sin mirar el reloj. 0 si no habia estado (o estaba vencido).
const anclaMs = Number(previo.ultimoMensajeMs) || 0;
const errores = [];
const pedidosOn = cfg.pedidosActivo === true;
const reservasOn = cfg.reservasActivo === true;

let texto = vmRecorte(String(t.texto === undefined || t.texto === null ? '' : t.texto).trim(), 1500);
let tipoEf = t.tipo;

const salir = (accion, extra) => [{ json: Object.assign({
  accion: accion, boton: null, consulta: '', campana: null, motivo: '', cuerpoExtraccion: null,
  texto: texto, estado: estado, errores: errores, anclaMs: anclaMs,
}, extra || {}) }];

// --- 1. Resultado del cotejo: el comprobante llegó hasta el servidor ----------------------
// (o llegó una foto con el cobro SIMULADO y el QR pendiente, `comprobanteSimulado`, que no se coteja; o llegó una imagen que
// `Interpretar entrada` marcó como comprobante pero la lectura o el
// cotejo no corrieron: `Plan del turno` lo trata como «sin cotejar», nunca como «cuadra»).
// H5: una foto con PIE llegada FUERA del cobro (el cliente ya no espera un comprobante: cancelo, termino o empezo otro pedido) es una imagen con pie y el
// pie se atiende como texto. Una sola excepcion: si la referencia del QR pendiente es un pedido REAL y de ESTE telefono (el modo cambio a simulado), la foto
// puede ser un pago y sigue como comprobante (`Plan del turno` la manda sin cotejo al restaurante). Sin pie, una foto fuera del cobro sigue siendo un
// comprobante (ya cotejado, o sin pendiente) y no toca el paso.
const fotoConPieFueraDelCobro = (() => {
  if (t.comprobanteSimulado !== true || previo.paso === 'esperando_comprobante' || !String(t.texto || '').trim()) return false;
  const ref = String((cfg.cobro && cfg.cobro.pedidoRef) || '');
  const guardados = ses.pedidos;
  const p = ref && Object.prototype.hasOwnProperty.call(guardados, ref) ? guardados[ref] : null;
  const esRealMio = !!p && typeof p === 'object' && String(p.from) === String(t.from) && p.simulado !== true;
  return !esRealMio;
})();
// EL ARTE DE UN ANUNCIO CON UN QR PENDIENTE (decisión de Andres, 07/11/2026): `¿Es comprobante?` mandó la imagen aquí, sin guardarla ni cotejarla, porque `Clasificar
// imagen` la reconoció como el arte de una campaña vigente. Se vuelve a comprobar con el criterio completo (`prCampanaDeLaImagen`): si coincide, se muestra la promoción
// (`Plan del turno` no toca el cobro ni el pedido y recuerda el comprobante pendiente); si NO coincide, es un comprobante, sin cotejo (aviso con la foto al local):
// un comprobante real nunca se pierde; el aviso dice «comprobante sin guardar ni cotejar» (`motivo: 'anuncio_no_confirmado'`), nada más. La imagen no vende ni cobra
// por sí sola. CRITERIO del filtro (`¿Es comprobante?`): `publicidad` y, si la lectura trae letra («A»/«B») Y titular, los DOS deben apuntar a la misma campaña vigente;
// con solo uno de los dos, ese basta. Aquí `prCampanaDeLaImagen` solo puede confirmar o descartar lo que el filtro ya dejó pasar.
const llegoComoAnuncio = t.esComprobante === true && t.clasificarAntes === true && !!vmNodo('Clasificar imagen')
  && !vmNodo('Cotejar en el servidor') && !vmNodo('Guardar comprobante') && !vmNodo('¿Es PDF?');
if (llegoComoAnuncio && cfg.promosActivo === true) {
  const lectura = vmTextoDeGemini(vmPrimero('Clasificar imagen'));
  const deLaImagen = lectura ? prCampanaDeLaImagen(cfg.campanas, cfg.anuncios, lectura, ahora, anuncioPorTitular, cfg) : null;
  if (deLaImagen) return salir('promo', { campana: deLaImagen, variante: 'promo', via: 'imagen_con_qr_pendiente' });
}
if (llegoComoAnuncio) return salir('comprobante', { motivo: 'anuncio_no_confirmado' });
if (vmNodo('Cotejar en el servidor') || t.esComprobante === true || (t.comprobanteSimulado === true && !fotoConPieFueraDelCobro)) return salir('comprobante');
// Un pedido SIMULADO con el cobro real encendido y su QR pendiente: la foto no es un comprobante real ni se coteja; se pasa con una persona.
if (t.comprobanteCruzado === true) return salir('transferir', { motivo: 'el modo de cobro cambió: comprobante de un pedido simulado' });

// --- 1b. El carrito del catalogo web (no es un mensaje de WhatsApp: decide `decidirCarrito`, mas abajo) ----
if (t.tipo === 'carrito') return decidirCarrito();

// --- 2. Medios -------------------------------------------------------------------------
if (t.tipo === 'audio') {
  // El audio llega transcripto por fuera; acá solo se decide si se entendió.
  const dicho = t.esAudio === true ? vmLinea(vmTextoDeGemini(vmPrimero('Transcribir audio')), 1000) : '';
  if (!dicho) return salir('medio_no_leido', { motivo: 'audio' });
  texto = dicho;
  tipoEf = 'text';
} else if (t.tipo === 'image' || t.tipo === 'document') {
  // Una imagen o un documento NO son un pago si no hay un QR esperando comprobante (si lo hubiera,
  // `esComprobante` ya los habría mandado arriba). Con pie de foto, el pie es un texto más.
  // EL ARTE DE UN ANUNCIO (adenda de campañas, 06/11/2026): una IMAGEN que `Interpretar entrada` marcó `esPosibleAnuncio` pasó por `Clasificar imagen`. Si el código
  // reconoce una campaña VIGENTE del servidor por su titular y/o por el campo `campana` (`prCampanaDeLaImagen`), se muestra el mensaje de esa promoción (o la respuesta
  // a la pregunta del pie, `prVariacion`). Lo leído en la imagen nunca llega al cliente ni a un modelo; Gemini sin saldo o con error = sin lectura = comportamiento de siempre.
  if (t.tipo === 'image' && t.esPosibleAnuncio === true && cfg.promosActivo === true) {
    const lectura = vmTextoDeGemini(vmPrimero('Clasificar imagen'));
    const deLaImagen = lectura ? prCampanaDeLaImagen(cfg.campanas, cfg.anuncios, lectura, ahora, anuncioPorTitular, cfg) : null;
    if (deLaImagen) {
      const delPie = texto ? prVariacion(texto, cfg.campanas, cfg, ahora, prTipoDeCampana(deLaImagen, cfg)) : null;
      const especifica = delPie && delPie.campana.id === deLaImagen.id ? delPie.variante : 'promo';
      // C-09: un pie de foto que pregunta algo que el mensaje no contesta se pasa con el local, además de la bienvenida de la promo.
      return salir('promo', { campana: deLaImagen, variante: especifica, via: 'imagen', sinResponder: especifica === 'promo' && prPreguntaSinResponder(texto) });
    }
  }
  if (texto) tipoEf = 'text';
  else return salir('imagen_sin_pendiente');
} else if (t.tipo === 'location' || t.ubicacion) {
  return salir('boton', { motivo: 'ubicacion' });
} else if (['text', 'interactive', 'button'].indexOf(tipoEf) < 0) {
  return salir('medio_no_leido', { motivo: 'tipo' });
}

const paso = previo.paso;
const norm = vmNorm(texto);

// --- 3. Botón: se valida contra el estado; uno viejo muestra el paso actual --------------
const idBoton = t.boton;
if (idBoton) {
  const b = typeof idBoton === 'object' ? idBoton : vmLeerBoton(String(idBoton));
  const viejo = () => salir('boton', { motivo: 'boton_viejo' });
  if (!b || typeof b.tipo !== 'string' || !Array.isArray(b.partes)) return viejo();
  const p0 = String(b.partes[0] === undefined ? '' : b.partes[0]);
  const enMenu = paso === 'inicio' || paso === 'menu';
  const enComp = paso === 'esperando_comprobante';
  const enPedido = paso.indexOf('pedido') === 0;
  const esDePedido = (b.tipo === 'm' && p0 === 'pedido') || ['g', 'f', 'e', 'p'].indexOf(b.tipo) >= 0;
  // Con un comprobante en espera el boton de pedido no saca del cobro (cae abajo en el recordatorio), ni siquiera con el local cerrado.
  if (esDePedido && pedidosOn && !enComp && cerrado()) return salir('fuera_de_horario');

  // «Menú» (`m|menu`) es valido en todo paso, pero con un comprobante en espera NO sale del cobro: muestra el recordatorio (`Plan del turno`: `aMenu`).
  // Los demás `m|*` valen salvo con un comprobante en espera.
  if (b.tipo === 'm' && p0 === 'menu') return salir('menu', { boton: b, motivo: 'boton_menu' });
  if (b.tipo === 'm' && !enComp) {
    if (p0 === 'persona') return salir('transferir', { boton: b, motivo: 'pidió hablar con una persona' });
    if (p0 === 'pedido' && pedidosOn) return salir('carta', { boton: b });
    if (p0 === 'reserva' && reservasOn) return salir('boton', { boton: b });
    if (p0 === 'promos' && cfg.promosActivo === true) return salir('consulta', { boton: b, consulta: 'promociones' });
  }
  if (b.tipo === 'g' && (enMenu || enPedido) && pedidosOn && p0 === 'pedir' && b.partes[1]) return salir('boton', { boton: b });
  if (b.tipo === 'g' && (enMenu || enPedido) && pedidosOn && p0 === 'agregar' && b.partes[1] && /^\d{1,2}$/.test(String(b.partes[2]))) return salir('boton', { boton: b });
  if (b.tipo === 'f' && paso === 'pedido') {
    // Solo se pregunta la primera pendiente (`pdResolverForma` resuelve `pendiente[0]`).
    const forma = b.partes[1];
    if (p0 === '0' && Array.isArray(previo.pendiente) && previo.pendiente.length
      && (forma === 'orden' || forma === 'unidad')) return salir('boton', { boton: b });
  }
  if (b.tipo === 'e' && paso === 'pedido_entrega' && (p0 === 'delivery' || p0 === 'recojo')) return salir('boton', { boton: b });
  if (b.tipo === 'p' && paso === 'pedido_confirmar' && (p0 === 'confirmar' || p0 === 'cambiar')) return salir('boton', { boton: b });
  // «Dejarlo como estaba» (tras «Cambiar algo»): vale mientras el pedido anterior siga guardado (`carritoAnterior`).
  if (b.tipo === 'p' && p0 === 'seguir' && enPedido) return salir('boton', { boton: b });
  if (b.tipo === 'p' && p0 === 'dejar' && (enPedido || paso === 'menu') && previo.carritoAnterior && typeof previo.carritoAnterior === 'object') return salir('boton', { boton: b });
  if (b.tipo === 'r' && paso === 'reserva_confirmar' && (p0 === 'enviar' || p0 === 'corregir')) return salir('boton', { boton: b });
  if (b.tipo === 'q' && paso === 'esperando_comprobante') {
    if (p0 === 'reenviar') return salir('reenviar_qr', { boton: b });
    if (p0 === 'cancelar') return salir('cancelar', { boton: b, motivo: 'cancelar_pedido', limpiar: 'pedido' });
  }
  return viejo();
}

// Desde acá todo es TEXTO (escrito, dicho o el pie de una foto).

// --- 4. Texto exacto de una campaña vigente (reinicia el estado) ------------------------
if (cfg.promosActivo === true && Array.isArray(cfg.campanas) && cfg.campanas.length) {
  const campana = prCampanaDelTexto(cfg.campanas, texto, ahora);
  if (campana) return salir('promo', { campana: campana });
}

// --- 5. Identidad primero; después, pide una persona ---------------------------------------
const PREGUNTA_IDENTIDAD = /\b(eres|sos|seras|hablo con|hablando con|estoy hablando con|me atiende|me atiendes|atiende) (un |una |el |la )?(robot|bot|chatbot|ia|inteligencia artificial|maquina|programa|humano|humana|persona|real)\b|\b(robot|chatbot|bot|inteligencia artificial)\b/;
const PIDE_PERSONA = /\b(hablar|conversar|comunicar|comunicarme|comunicarnos|contactar|contactarme|pasar|pasame|pasenme|comunicame) (con|a) (una |un |la |el |algun |alguna |otra )?(persona|alguien|humano|humana|encargad[oa]|asesor|asesora|duen[oa]|gerente|administrador|administradora|recepcion)\b|\b(quiero|necesito|prefiero|quisiera|pido) (a )?(una |un |la |el )?(persona|humano|humana|asesor|asesora|encargad[oa])\b|\b(reclamo|queja|humano|humana)\b|\b(hablar|conversar|comunicarme|comunicarnos|comunicar|contactar|contactarme) (con|a) (el|la) (local|negocio|restaurante|tienda|equipo)\b|\b(escribir|escribirle|escribirles|escribirnos) (al|a la|con el|con la) (local|negocio|restaurante|tienda|recepcion|equipo|encargad[oa]|duen[oa])\b|^(escribanme|escribame)( por favor)?$/;
if (PREGUNTA_IDENTIDAD.test(norm)) return salir('identidad');
if (PIDE_PERSONA.test(norm)) return salir('transferir', { motivo: 'pidió hablar con una persona' });

// --- 5b. Pide la ubicación o la dirección del LOCAL (09/10/2026, pedido de Q'Taco) ---------------------------------------
// «Cada vez que una persona pida expresamente la ubicación o la dirección del local, se le manda el enlace de Google Maps, sea cual sea el
// flujo que siga o la etapa en que esté.» Va ANTES de las intenciones globales y del «por paso»: con un comprobante en espera, un pedido a medias
// o una reserva en curso la consulta se responde igual y el estado NO se toca (`Plan del turno`: `aUbicacionLocal`). Solo si hay algo que dar
// (la dirección en texto o un enlace de Maps válido); sin ninguno no se intercepta y todo sigue como antes. Cero llamadas al modelo.
// DAR no es PEDIR: dentro de `pedido_datos` con delivery el flujo está pidiendo SU dirección de entrega, así que ahí «ubicación» o «dirección»
// sueltas se leen como darla y solo cuenta lo que nombra al local (`pideElLocal(norm, true)`). Compartir la ubicación (`type: location`) ya salió arriba.
// MISMO criterio que `Plan del turno` (`aUbicacionLocal`): la dirección sin los puntos ni los espacios finales; una que sea solo puntuación no cuenta como dato.
const hayDatoDelLocal = !!vmLinea(cfg.direccion, 200).replace(/[.\s]+$/, '') || !!vmEnlaceDeMapa(cfg.direccionMaps);
const pidiendoSuDireccion = paso === 'pedido_datos' && !!previo.entrega && previo.entrega.entrega === 'delivery';
if (hayDatoDelLocal && pideElLocal(norm, pidiendoSuDireccion)) return salir('consulta', { consulta: 'direccion_local', motivo: 'ubicacion_del_local' });

// --- 5c. El anuncio por el que llegó (`referral`, adenda de campañas 06/11/2026) -----------------------------------------------
// El `referral` solo ELIGE qué promoción mostrar: compara su titular y su cuerpo con los titulares de los anuncios vigentes del servidor (`anuncioPorTitular`). Nunca vende,
// cobra ni abre un pedido. Solo en `inicio` (el primer mensaje), con un mensaje corto que no pide otra cosa (un pedido, una mesa para otro anuncio, hablar con alguien ya salieron).
if (paso === 'inicio' && cfg.promosActivo === true && Array.isArray(cfg.campanas) && cfg.campanas.length && t.referral && typeof t.referral === 'object'
  && Array.isArray(cfg.anuncios) && cfg.anuncios.length && norm.split(' ').filter(Boolean).length <= 8 && !intencionDePedir(norm)) {
  const delAnuncio = prCampanaDelReferral(cfg.campanas, cfg.anuncios, t.referral, ahora, anuncioPorTitular);
  if (delAnuncio && !(/reserv|\bmesa\b/.test(norm) && prTipoDeCampana(delAnuncio, cfg) === 'A')) return salir('promo', { campana: delAnuncio, via: 'referral' });
}

// --- 6. Intenciones GLOBALES: valen en cualquier paso, antes del «por paso» ------------------------
// Con un comprobante en espera (`esperando_comprobante`) «menú» no sale del cobro (muestra el recordatorio) y lo
// demás recibe el recordatorio. «Menú» no borra nada; «cancelar» y «empezar de nuevo» sí limpian.
const enComprobante = paso === 'esperando_comprobante';
// CANCELAR (04/10): «cancela mi pedido» y sus variantes naturales CANCELAN el pedido guardado (`Plan del turno`: `aCancelar`), no derivan a una persona.
// Un rechazo («no cancela», «no quiero cancelar») NO cancela: el pedido sigue donde estaba.
const cancelacion = intencionDeCancelar(norm);
if (cancelacion === 'no') {
  if (enComprobante || (paso.indexOf('pedido') === 0 && (previo.carrito.length > 0 || previo.carritoAnterior))) return salir('boton', { motivo: 'no_cancela' });
} else if (cancelacion && enComprobante) {
  // Con el QR enviado, escribir «cancela mi pedido» es lo mismo que tocar «Cancelar pedido».
  if (cancelacion !== 'reserva') return salir('cancelar', { motivo: 'cancelar_pedido', limpiar: 'pedido' });
}
// «¿Qué tengo guardado?»: muestra el pedido guardado con sus botones (sin pedido, lo dice). Con un QR esperando comprobante rige el recordatorio de siempre.
if (pedidosOn && !enComprobante && /^(ver |mostrar |muestrame |dime |cual es |quiero ver )?(mi |el )?(pedido|carrito)( guardado| actual)?$|^(que|cual) (tengo|llevo|pedi)( guardado| en mi pedido| en el pedido| pedido)?$|^cuanto (va|llevo)( en mi pedido| en el pedido| mi pedido)?$|^(mi pedido|mi carrito)$/.test(norm)
  && /\b(pedido|carrito|tengo|llevo|pedi|va)\b/.test(norm) && norm !== 'pedido' && norm.length <= 40) {
  return salir('boton', { motivo: 'ver_pedido' });
}
// --- 6a. VARIACIONES del texto de una campaña (adenda 06/11/2026, C-07) -----------------------------------------------------
// Quien pregunta con otras palabras por «las tortas mexicanas» o por «Jueves de +2», o hace la pregunta que sigue al mensaje («¿qué incluye?», «¿por qué dice solo delivery?»).
// Por código, solo con la campaña vigente del servidor y nunca con un saludo común (ver `prVariacion`). SOLO en `inicio` y `menu` (en un pedido o una reserva en curso el
// mensaje sigue ese camino), y DESPUÉS de pedir una persona y de cancelar (esas intenciones ganan). La pregunta suelta solo cuenta en `menu`, con la campaña que se acaba
// de mostrar (`campanaVista` del estado). El texto EXACTO de la campaña (paso 4) vale en cualquier paso, como siempre.
if (!cancelacion && (paso === 'inicio' || paso === 'menu') && cfg.promosActivo === true && Array.isArray(cfg.campanas) && cfg.campanas.length) {
  const vista = paso === 'menu' && (previo.campanaVista === 'A' || previo.campanaVista === 'B') ? previo.campanaVista : '';
  const variacion = prVariacion(texto, cfg.campanas, cfg, ahora, vista);
  if (variacion) return salir('promo', { campana: variacion.campana, variante: variacion.variante, sinResponder: variacion.sinResponder === true });
}
const quierePedir = /\b(pedir|pedido)\b|\bdelivery\b|para llevar|\bquiero \d/.test(norm) || intencionDePedir(norm);
const quiereReservar = /reserv|\bmesa\b/.test(norm);
// FALSOS POSITIVOS (revisión del PR #382): las intenciones globales de CARTA y RESERVA valen en `inicio` y `menu` sin límite de largo, pero
// en los demás pasos solo con un mensaje CORTO (hasta 60 caracteres) y nunca mientras se piden los datos de entrega (`pedido_entrega`,
// `pedido_datos`, donde la reserva solo vale con el verbo «reservar»): una dirección («edificio Mesa Grande») o una referencia no es «quiero una mesa». «Que tienen» no es la carta si el
// mensaje ya pide algo («quiero tacos, ¿qué tienen de postre?»), y «pedir» dentro de una reserva no es cambiar de rumbo si es una
// pregunta («¿se puede pedir torta?»).
const enDatosDeEntrega = paso === 'pedido_entrega' || paso === 'pedido_datos';
const globalCorto = paso === 'inicio' || paso === 'menu' || (norm.length <= 60 && !enDatosDeEntrega);
const pideAlgo = /\b(quiero|quisiera|queremos|necesito|dame|me das|ponme|pedir|pedido)\b/.test(norm);
const esPregunta = /[?¿]/.test(texto) || /\b(se puede|puedo|pueden|podria|podrian|hay|tienen|aceptan)\b/.test(norm);
if (/^(menu|menu principal|inicio|volver al menu|volver a inicio|volver al inicio)$/.test(norm) || (!enComprobante && /^(hola|volver|atras)$/.test(norm))) {
  return salir('menu', { motivo: 'menu' });
}
if (!enComprobante) {
  if (/^(empezar de nuevo|empezar otra vez|volver a empezar|reiniciar)$/.test(norm)) return salir('menu', { motivo: 'reinicio', limpiar: 'todo' });
  if (cancelacion === 'pedido') return salir('cancelar', { motivo: 'reinicio', limpiar: 'pedido' });
  if (cancelacion === 'reserva') return salir('menu', { motivo: 'reinicio', limpiar: 'reserva' });
  if (cancelacion === 'todo') return salir('cancelar', { motivo: 'reinicio', limpiar: 'todo' });
  // «cancelar» a secas cancela lo que se está haciendo; sin nada en curso, todo.
  if (cancelacion === 'solo') {
    if (paso.indexOf('reserva') === 0) return salir('menu', { motivo: 'reinicio', limpiar: 'reserva' });
    return salir('cancelar', { motivo: 'reinicio', limpiar: paso.indexOf('pedido') === 0 ? 'pedido' : 'todo' });
  }
  // La carta, en cualquier paso. Un pedido que la nombra («tres tacos de la carta») no es esta intención.
  if (pedidosOn && globalCorto && norm.length <= 80 && !/\d/.test(norm) && (/\b(carta|catalogo)\b/.test(norm) || (/\bque tienen\b/.test(norm) && !pideAlgo))
    && !/\b(de|en|segun) la carta\b/.test(norm)) return salir('carta', { motivo: 'carta', consulta: 'carta' });
  // La reserva, en cualquier paso (en un paso de reserva sigue su camino «por paso»).
  // En los pasos de datos de entrega solo vale el VERBO («quiero reservar», corto y sin numeros); «mesa» suelta es parte de una direccion.
  const reservaEnDatos = norm.length <= 60 && !/\d/.test(norm) && /\breserv/.test(norm);
  if (reservasOn && quiereReservar && paso.indexOf('reserva') !== 0 && (enDatosDeEntrega ? reservaEnDatos : globalCorto)) return extraerReserva();
  // El pedido, estando en una reserva: el carrito sigue donde se dejó.
  if (pedidosOn && paso.indexOf('reserva') === 0 && norm.length <= 60 && !esPregunta && /\b(pedir|pedido)\b/.test(norm)) return extraerPedido();
}

// --- Pedido en curso: cosas que se resuelven con código, sin modelo --------------------------------
// «Dejarlo como estaba», escrito: vuelve el pedido de antes de «Cambiar algo» (el botón de enlace de la carta no admite un botón de respuesta).
// Tras «Cambiar algo» el carrito está vacío: lo que vale es que el pedido anterior siga guardado.
// Se reconocen por código las formas naturales de pedir lo mismo («déjalo como estaba», «no, déjalo no más», «te dije que lo deses como estaba», «ya no cambio»)
// (`intencionDeVolver`). También con el paso en `menu`: una derivación manda el paso a `menu` y el pedido anterior sigue guardado.
// TOLERANCIA SOLO AL ELEGIR DE NUEVO (revisión de seguridad del PR #426): con tipeo/voz tolerados y con «duda» posible únicamente cuando el carrito nuevo está
// vacío, sin una pregunta pendiente y sin que el cliente esté dando datos de entrega. Con un pedido nuevo en curso (carrito con productos, `pedido_entrega`,
// `pedido_datos`) valen solo las formas CERRADAS y nunca se pregunta: «Déjalo en portería nomás» es una instrucción de entrega, no volver al pedido anterior.
// La pregunta se hace UNA vez (`preguntoDejar`); la segunda vez la frase sigue su camino normal.
if (!enComprobante && (paso.indexOf('pedido') === 0 || paso === 'menu') && previo.carritoAnterior && typeof previo.carritoAnterior === 'object') {
  const hayCarritoNuevo = (Array.isArray(previo.carrito) && previo.carrito.length > 0) || (Array.isArray(previo.pendiente) && previo.pendiente.length > 0);
  const dandoDatos = paso === 'pedido_entrega' || paso === 'pedido_datos';
  const tolerante = !hayCarritoNuevo && !dandoDatos && (paso === 'pedido' || paso === 'menu');
  // «No, dejarlo como estaba» (con coma o punto tras el «no»): el «no» es una respuesta aparte y lo que sigue es lo que quiere, no un rechazo del verbo (LOW del PR
  // #426). Sin la puntuación («no dejarlo como estaba») sigue siendo un rechazo. `vmNorm` borra la puntuación: se mira el texto crudo.
  const sinNoAparte = String(texto).replace(/^\s*(?:(?:ya|pues|mejor)\s+)?no\s*[,;:.!]+\s*(?=\S)/i, '');
  const quiere = intencionDeVolver(sinNoAparte !== String(texto) ? vmNorm(sinNoAparte) : norm, tolerante);
  const sePuedePedir = !(pedidosOn && cerrado()); // el camino por texto respeta el horario igual que el botón
  if (quiere === 'si') return sePuedePedir ? salir('boton', { motivo: 'dejar_como_estaba', boton: { tipo: 'p', partes: ['dejar'] } }) : salir('fuera_de_horario');
  if (quiere === 'duda' && previo.preguntoDejar !== true) return sePuedePedir ? salir('boton', { motivo: 'dejar_o_elegir' }) : salir('fuera_de_horario');
}
const enPasoDePedido = paso.indexOf('pedido') === 0 && Array.isArray(previo.carrito) && previo.carrito.length > 0;
if (!enComprobante && enPasoDePedido) {
  // CAMBIO DE ENTREGA por texto («prefiero recoger», «¿puedo cambiar al delivery?», «quiero que me manden», «mándamelo», «a domicilio», «mejor recojo»),
  // también con tipeo («quiero que me mandn»): `cambioDeEntrega` exige que TODAS las palabras sean de un vocabulario cerrado (una dirección o una referencia
  // —«Barrio El Retiro», «ella va a recoger en portería», «Calle Domicilio 5»— tiene palabras ajenas y NO es un cambio), sin «no/nada/sin», y que no mezcle
  // delivery con recojo. Mensaje entero y corto (revisión de seguridad del PR #417/#426).
  const eligioDelivery = previo.entrega && previo.entrega.entrega === 'delivery';
  const cambio = cambioDeEntrega(norm);
  if (cambio === 'recojo' && cfg.aceptaRetiroEnLocal !== false && (eligioDelivery || paso === 'pedido_entrega')
    && ['pedido_entrega', 'pedido_datos', 'pedido_confirmar'].indexOf(paso) >= 0) {
    if (pedidosOn && cerrado()) return salir('fuera_de_horario');
    return salir('boton', { motivo: 'cambio_a_recojo', boton: { tipo: 'e', partes: ['recojo'] } });
  }
  if (cambio === 'delivery' && cfg.aceptaDelivery !== false && ['pedido_entrega', 'pedido_confirmar'].indexOf(paso) >= 0) {
    if (pedidosOn && cerrado()) return salir('fuera_de_horario');
    return salir('boton', { motivo: 'cambio_a_delivery', boton: { tipo: 'e', partes: ['delivery'] } });
  }
  // El costo del delivery no es algo que el asistente cobre ni decida: se pasa con el local, SIN la frase de «menú» (el pedido sigue guardado).
  const preguntaCostoDelivery = norm.length <= 100
    && (/\b(cobrar|cobren|cobras|cobran|cobre|cobres|cobrarme|costo|cuesta|cuanto|precio|gratis|pagar)\b.*\b(delivery|envio|domicilio)\b|\b(delivery|envio|domicilio)\b.*\b(gratis|cobr\w*|costo|cuesta|precio|cuanto)\b/.test(norm));
  if (preguntaCostoDelivery && paso !== 'pedido') return salir('transferir', { motivo: 'consulta sobre el costo del delivery', sinFraseMenu: true });
}

// --- Un «sí» suelto no confirma nada; una pregunta orden/unidad pendiente se vuelve a mostrar --
const RELLENO = ['si', 'ya', 'dale', 'ok', 'okey', 'okay', 'listo', 'claro', 'bueno', 'confirmo', 'acepto', 'perfecto', 'adelante',
  'de', 'acuerdo', 'correcto', 'esta', 'bien', 'vale', 'sip', 'va', 'pues', 'una', 'enviar', 'envia', 'envialo', 'enviala',
  'manda', 'mandalo', 'mandala', 'confirmar', 'por', 'favor', 'gracias', 'asi', 'es', 'eso', 'lo', 'la', 'quiero'];
const palabras = norm.split(' ').filter(Boolean);
const soloAfirma = palabras.length > 0 && palabras.length <= 6 && palabras.every((w) => RELLENO.indexOf(w) >= 0);
if ((paso === 'pedido_confirmar' || paso === 'reserva_confirmar') && soloAfirma) return salir('boton', { motivo: 'si_suelto' });
// Lo mismo con el pedido a medias (entrega, datos del delivery, o la carta ya armada): «quiero confirmar», «confirmo», «ok» no se toman por una
// pregunta ni se derivan a una persona; vuelve a salir el paso en que está (el resumen con «Confirmar pedido» cuando ya tiene todo). No confirma solo.
const CONFIRMA = /^(quiero|quisiera|deseo|voy a) (confirmar|enviar|mandar)( (mi|el|este))?( pedido)?( por favor)?$|^(confirmar|confirmo|confirma|enviar|mandar)( (mi|el|este))? pedido( por favor)?$/;
const pedidoEnCurso = ['pedido_entrega', 'pedido_datos'].indexOf(paso) >= 0 || (paso === 'pedido' && Array.isArray(previo.carrito) && previo.carrito.length > 0 && !(Array.isArray(previo.pendiente) && previo.pendiente.length));
if (pedidoEnCurso && !enComprobante && (soloAfirma || CONFIRMA.test(norm))) return salir('boton', { motivo: 'si_suelto' });
if (paso === 'pedido_confirmar' && CONFIRMA.test(norm)) return salir('boton', { motivo: 'si_suelto' });
// Con el resumen mostrado, pedir por texto que se cambie el pedido («cámbiame el pedido», «quiero cambiar mi pedido», «modifica el pedido») abre el cambio igual que el botón
// «Cambiar algo» (`p|cambiar`: la carta de nuevo; lo que se elija reemplaza el pedido). Vocabulario cerrado y comprobación lineal por palabras (sin regex con cuantificadores
// anidados): si la frase lleva algo más («… a recoger», «… de la mesa 3», una dirección), no es esto y sigue su camino de siempre. Cero mensajes agregados: sale el de la carta.
function pideCambiarElPedido(ps) {
  const PRE = ['mejor', 'ya', 'pues', 'entonces', 'por', 'favor', 'quiero', 'quisiera', 'necesito', 'deseo', 'queremos', 'puedo', 'podria', 'puedes', 'podrias', 'voy', 'a'];
  const VERBO = ['cambia', 'cambiame', 'cambialo', 'cambiar', 'cambiarlo', 'modifica', 'modificame', 'modificalo', 'modificar', 'modificarlo', 'corrige', 'corrigeme', 'corregir', 'corregirlo'];
  let i = 0;
  while (i < ps.length && PRE.indexOf(ps[i]) >= 0) i += 1;
  if (i >= ps.length || VERBO.indexOf(ps[i]) < 0) return false;
  i += 1;
  while (i < ps.length && ['me', 'nos', 'el', 'mi', 'mis', 'este', 'la', 'lo'].indexOf(ps[i]) >= 0) i += 1;
  if (i >= ps.length || ['pedido', 'orden', 'compra'].indexOf(ps[i]) < 0) return false;
  i += 1;
  while (i < ps.length && ['por', 'favor', 'otra', 'vez'].indexOf(ps[i]) >= 0) i += 1;
  return i === ps.length;
}
if (paso === 'pedido_confirmar' && pedidosOn && pideCambiarElPedido(palabras)) return cerrado() ? salir('fuera_de_horario') : salir('boton', { motivo: 'cambiar_pedido', boton: { tipo: 'p', partes: ['cambiar'] } }); // respeta el horario igual que el botón
// Una respuesta a la pregunta orden/unidad («sueltos», «la orden», «dale») repite la pregunta sin gastar un modelo; cualquier otro
// texto es un mensaje nuevo y se atiende (si no, «quiero un helado» recibía la misma pregunta una y otra vez). La
// pregunta sigue pendiente en el estado y vuelve a salir en cuanto el pedido avanza.
const RESPUESTA_FORMA = /^((la|las|en|por|una|un|el) )?(orden|ordenes|suelt[oa]s?|unidad|unidades)( completa)?$/;
if (paso === 'pedido' && Array.isArray(previo.pendiente) && previo.pendiente.length && (RESPUESTA_FORMA.test(norm) || soloAfirma)) return salir('boton', { motivo: 'forma_pendiente' });

// --- 7. En inicio o menú: consulta fija (dirección, horario, delivery, promociones, carta) ----
if (paso === 'inicio' || paso === 'menu') {
  const consulta = consultaFija();
  if (consulta === 'carta') return salir('carta', { consulta: consulta });
  if (consulta) return salir('consulta', { consulta: consulta });
}

// --- 8. Por paso ------------------------------------------------------------------------------
if (paso === 'esperando_comprobante') return salir('recordatorio_comprobante');
if (paso.indexOf('reserva') === 0) return extraerReserva();
if (paso.indexOf('pedido') === 0) return extraerPedido();
// inicio o menu, sin consulta fija: la intención de pedido o de reserva, o el menú.
if (pedidosOn && quierePedir) return extraerPedido();
return salir('menu');

// ---------------------------------------------------------------------------------------------
// EL CARRITO DEL CATALOGO WEB (`tipo === 'carrito'`, que solo produce `Carga de entrada` cuando corrio «Carrito del catálogo»).
// El servidor ya escribio el pedido en la consola y recalculo los precios; aca solo se decide si el flujo contesta y como.
// `carrito_*` en `motivo` = no se contesta nada (`Plan del turno` sale sin mensajes, sin aviso y sin tocar el estado):
//   1. ventana de 24 h cerrada (la calculo el servidor): fuera de ella Meta solo acepta una plantilla aprobada y no hay una
//      para esto; no sale nada y el pedido sigue en la consola (el Demo B tampoco manda plantilla);
//   2. el panel no contesto: no hay carta con que armar nada, se pasa con el local (aviso + boton);
//   3. el tenant del carrito no es el del panel de ESTE numero: no es de este comercio, no se contesta;
//   4. pedidos apagados: no hay nada que tomar;
//   5. con un QR esperando comprobante: el carrito se ignora y se recuerda el comprobante (antes que el horario);
//   6. local cerrado: fuera de horario (como un pedido por texto);
//   7. si no, `carrito`: `Plan del turno` arma el pedido desde la carta y sigue con el paso que corresponda.
function decidirCarrito() {
  const c = t.carrito && typeof t.carrito === 'object' ? t.carrito : {};
  if (c.ventanaAbierta !== true) return salir('carrito', { motivo: 'carrito_ventana_cerrada' });
  if (cfg.panelSinRespuesta === true) return salir('transferir', { motivo: 'carrito del catálogo sin respuesta del panel' });
  if (!mismoTexto(c.tenantId, tenantDelPanel())) return salir('carrito', { motivo: 'carrito_otro_tenant' });
  if (!pedidosOn) return salir('carrito', { motivo: 'carrito_sin_pedidos' });
  // El comprobante pendiente se revisa ANTES del horario: un cliente que ya pagó recibe el recordatorio de su comprobante aunque el local cerró.
  if (previo.paso === 'esperando_comprobante') return salir('recordatorio_comprobante');
  if (cerrado()) return salir('fuera_de_horario');
  return salir('carrito');
}

// El tenant que dijo el panel para este numero (`Traer configuración`): vacio si el panel no contesto con uno.
function tenantDelPanel() {
  const r = vmPrimero('Traer configuración') || {};
  let b = r.body;
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = null; } }
  return Number(r.statusCode) === 200 && b && typeof b === 'object' && typeof b.tenantId === 'string' ? b.tenantId : '';
}

// Igualdad de dos textos sin salida temprana; dos vacios NO son iguales (sin tenant no hay a quien atribuir el carrito).
function mismoTexto(a, b) {
  const x = String(a === undefined || a === null ? '' : a);
  const y = String(b === undefined || b === null ? '' : b);
  if (!x || !y) return false;
  let d = x.length === y.length ? 0 : 1;
  const n = Math.max(x.length, y.length);
  for (let i = 0; i < n; i++) d |= (x.charCodeAt(i) || 0) ^ (y.charCodeAt(i) || 0);
  return d === 0;
}

// ---------------------------------------------------------------------------------------------
function estadoBase() {
  return Object.assign(vmEstadoBase(), {
    paso: 'inicio', carrito: [], pendiente: [],
    entrega: { entrega: '', modalidad: '', direccion: '', referencia: '', nombre: '' },
    reserva: null, pedido: null, vacias: 0, ilegibles: 0, transferencias: [],
    carritoGuardado: 0,
  });
}

// ¿El texto PIDE comida sin decir «pedir» ni escribir un dígito? (05/10: un audio transcrito «quiero cuatro tacos de birria» caía al menú sin llamar al modelo.)
// Cuenta si hay un verbo de pedido («quiero», «dame», «ponme», «mándame», «necesito», «me das»…) junto a una cantidad en palabras que no deja dudas
// («dos» a «diez», «media docena», «docena») o a una palabra de la CARTA CARGADA (sus nombres, con `vmNorm`: nada de productos escritos en el código), o una cantidad
// fuerte junto a una palabra de la carta sin verbo («cuatro tacos de birria por favor»). «un/una» solos NO son cantidad (sin una palabra de la carta, «quiero un
// descuento» no es un pedido). Nunca si habla de una persona, una mesa, la ubicación, el horario o una reserva: eso lo atienden otras reglas.
// El resto sigue igual: si el modelo no saca líneas, no se inventa nada (la carta, o pasar con el local a la segunda vez).
function intencionDePedir(n) {
  if (!n || n.length > 200 || /\b(persona|personas|mesa|mesas|reserv\w*|ubicacion|direccion|horario|hablar|asesor\w*|encargad\w*|humano|humana|queja|reclamo)\b/.test(n)) return false;
  const verbo = /\b(quiero|quisiera|queremos|quisieramos|dame|deme|damelo|ponme|pongame|ponga|mandame|mandeme|necesito|necesitamos|pido|pedimos|traeme|traigame|regalame|me das|me da|me pones|me pone|me manda|me mandas|me regalas|voy a querer|vamos a querer)\b/.test(n);
  const fuerte = /\b(\d+|dos|tres|cuatro|cinco|seis|siete|ocho|nueve|diez|once|doce|docena|media docena)\b/.test(n);
  const sueltas = n.split(' ').filter(Boolean);
  const comunes = ['orden', 'ordenes', 'combo', 'combos', 'promo', 'promos', 'para', 'sin', 'con', 'del', 'los', 'las', 'una', 'unos', 'unas', 'plato', 'platos'];
  const raiz = (w) => w.replace(/(es|s)$/, '');
  // Solo lo que se vende (`cartaDelNegocio`: sin áreas excluidas, agotados ni precios inválidos), y sin las palabras del propio nombre del negocio
  // («Q'Taco» no vuelve «quiero la promo de Q'Taco» un pedido de tacos).
  const delNegocio = vmNorm(cfg.nombreNegocio).split(' ');
  const deLaCarta = [];
  for (const it of cartaDelNegocio()) {
    for (const w of vmNorm(it.nombre).split(' ')) if (w.length >= 4 && comunes.indexOf(w) < 0) deLaCarta.push(raiz(w));
  }
  const nombraLaCarta = sueltas.some((w) => w.length >= 4 && comunes.indexOf(w) < 0 && delNegocio.indexOf(w) < 0 && deLaCarta.indexOf(raiz(w)) >= 0);
  return (verbo && (fuerte || nombraLaCarta)) || (fuerte && nombraLaCarta);
}

// ¿Qué quiere cancelar? '' = nada; 'no' = lo rechaza («no cancela», «no quiero cancelar»); 'pedido' («cancela mi pedido», «ya no quiero el pedido»);
// 'reserva'; 'todo' («cancela todo»); 'solo' = la palabra a secas («cancelar», «quiero cancelar»: se cancela lo que se está haciendo). Mensaje ENTERO
// y corto: «cancelar» dentro de otra frase («¿se puede cancelar después?») no cancela nada.
function intencionDeCancelar(norm) {
  if (!norm || norm.length > 50 || /\d/.test(norm)) return '';
  if (/\bno\b.{0,20}\b(cancel\w*|anul\w*)\b/.test(norm) || /\b(cancel\w*|anul\w*)\b.{0,12}\bno\b/.test(norm)) return /\b(cancel|anul)/.test(norm) ? 'no' : '';
  const V = '(cancelar|cancela|cancelo|cancelame|anular|anula|anulame)';
  if (new RegExp('^(quiero |quisiera |deseo |necesito |voy a |por favor |ya |entonces )*' + V + ' (la |mi |esta |esa )?reserva( por favor)?$').test(norm)) return 'reserva';
  if (new RegExp('^(quiero |quisiera |deseo |necesito |voy a |por favor |ya |entonces )*' + V + ' (todo|todo mi pedido|todo el pedido|todo por favor)( por favor)?$').test(norm)) return 'todo';
  if (new RegExp('^(quiero |quisiera |deseo |necesito |voy a |por favor |ya |entonces )*' + V + '( me)? ?(mi |el |este |ese )(pedido|orden)( por favor)?$').test(norm)
    || /^(cancelar|cancela) pedido( por favor)?$/.test(norm)) return 'pedido';
  if (/^(ya )?no quiero (el |mi |este |ese )?(pedido|nada)( por favor)?$/.test(norm)) return 'pedido';
  if (new RegExp('^(quiero |quisiera |deseo |necesito |voy a |por favor |ya |entonces )*' + V + '(lo|la|melo)?( por favor)?$').test(norm)) return 'solo';
  return '';
}

// ¿Hay un «no» seguido (con «lo/la/me/se/te» a lo sumo) de una palabra que es el verbo dejar en SUBJUNTIVO o INFINITIVO con un error de una letra («dejez», «deges»,
// «dejarl»)? El imperativo afirmativo («dejalo», «dejala», «deja», «dejemoslo») y sus tipeos NO cuentan: «No déjalo como estaba no más.» sigue siendo «volver».
function rechazoConTipeo(palabras) {
  const NEGATIVAS = ['dejes', 'dejen', 'deses', 'dejar', 'dejarlo', 'dejarla'];
  const AFIRMATIVAS = ['dejalo', 'dejala', 'dejemoslo'];
  for (let i = 0; i < palabras.length; i++) {
    if (palabras[i] !== 'no') continue;
    let j = i + 1;
    while (j < palabras.length && ['lo', 'la', 'me', 'se', 'te'].indexOf(palabras[j]) >= 0) j++;
    const w = palabras[j];
    if (!w || w.length < 5) continue;
    if (AFIRMATIVAS.some((k) => distancia(w, k) <= 1)) continue;
    if (NEGATIVAS.some((k) => distancia(w, k) <= 1)) return true;
  }
  return false;
}

// ¿El mensaje ES un pedido de cambiar la entrega? 'delivery' | 'recojo' | ''. TODAS las palabras deben ser del vocabulario cerrado de abajo (rellenos,
// verbos de cambiar, y las palabras de delivery o de recojo, con tolerancia de una letra para las de 5 o más letras: «mandn», «envien», «recojer»);
// sin dígitos, de hasta 8 palabras, y nunca con «no», «nada», «sin», «ni» ni mezclando las dos entregas.
function cambioDeEntrega(norm) {
  const palabras = norm.split(' ').filter(Boolean);
  if (!palabras.length || palabras.length > 8 || norm.length > 60 || /\d/.test(norm)) return '';
  const RELLENO = ['quiero', 'quisiera', 'queremos', 'que', 'me', 'lo', 'la', 'el', 'al', 'a', 'mi', 'por', 'para', 'favor', 'mejor', 'prefiero', 'prefiere',
    'preferimos', 'ya', 'entonces', 'pues', 'yo', 'en', 'local', 'casa', 'puedo', 'podria', 'podrian', 'se', 'puede', 'es', 'posible', 'cambiar', 'cambio',
    'cambialo', 'cambiarlo', 'cambiamelo', 'pasar', 'pasarlo', 'pasalo', 'pasame', 'paso', 'voy', 'ire', 'si', 'ok', 'dale', 'bueno', 'nomas', 'tambien', 'pero'];
  const DELIVERY = ['delivery', 'domicilio', 'envio', 'enviar', 'enviarlo', 'envien', 'envienlo', 'envienmelo', 'enviamelo', 'envialo', 'envian', 'manden', 'mandar',
    'mandarlo', 'mandamelo', 'mandalo', 'mandenlo', 'mandenmelo', 'mandan', 'traigan', 'traer', 'traerlo', 'traiganlo', 'traiganmelo', 'traen', 'lleven', 'llevar',
    'llevarlo', 'llevenlo', 'llevenmelo', 'llevamelo', 'llevan'];
  const RECOJO = ['recoger', 'recogerlo', 'recojo', 'recogo', 'retirar', 'retirarlo', 'retiro', 'buscar', 'buscarlo', 'buscaria'];
  const cerca = (w, lista) => lista.some((k) => w === k || (w.length >= 5 && k.length >= 5 && distancia(w, k) <= 1));
  if (palabras.some((w) => ['no', 'nada', 'sin', 'ni', 'nunca', 'jamas'].indexOf(w) >= 0)) return '';
  let hayDelivery = false;
  let hayRecojo = false;
  for (const w of palabras) {
    if (RELLENO.indexOf(w) >= 0) continue;
    if (cerca(w, DELIVERY)) { hayDelivery = true; continue; }
    if (cerca(w, RECOJO)) { hayRecojo = true; continue; }
    return ''; // una palabra ajena: es una dirección, una referencia o una pregunta, no el pedido de cambiar
  }
  if (hayDelivery === hayRecojo) return '';
  // Un verbo suelto («enviar», «mándalo») es la forma de CONFIRMAR («un “sí” escrito no confirma nada», más abajo), no un cambio de entrega: una sola palabra
  // vale solo si es delivery/domicilio/envío o lleva el «me» («mándamelo»).
  if (palabras.length === 1 && hayDelivery && !/melo$/.test(palabras[0]) && ['delivery', 'domicilio', 'envio'].indexOf(palabras[0]) < 0) return '';
  return hayDelivery ? 'delivery' : 'recojo';
}

// Distancia de edición (Levenshtein) entre dos palabras cortas.
function distancia(a, b) {
  const m = a.length;
  const n = b.length;
  if (Math.abs(m - n) > 1) return 2; // corte temprano: todos los usos comparan con `<= 1`
  let fila = [];
  for (let j = 0; j <= n; j++) fila.push(j);
  for (let i = 1; i <= m; i++) {
    const nueva = [i];
    for (let j = 1; j <= n; j++) nueva.push(Math.min(fila[j] + 1, nueva[j - 1] + 1, fila[j - 1] + (a.charAt(i - 1) === b.charAt(j - 1) ? 0 : 1)));
    fila = nueva;
  }
  return fila[n];
}

// ¿Quiere volver al pedido de antes de «Cambiar algo»? 'si' = se entiende sin duda; 'duda' = habla de dejarlo pero no se entiende del todo o lo rechaza
// («no quiero dejarlo como estaba»); '' = es otra cosa. `norm` ya viene sin tildes, en minúscula y sin signos. Un «no» aislado al comienzo
// («no, déjalo como estaba») es parte de la respuesta y cuenta como volver; un «no» pegado al verbo («no lo dejes») es un rechazo y se trata como duda.
// `tolerante` = solo cuando se está eligiendo de nuevo (carrito nuevo vacío). Reglas de seguridad (PR #426):
//  - TODAS las palabras del mensaje deben ser del vocabulario cerrado de abajo (como `soloAfirma`): una palabra de más («portería», «guardia», «hermana»)
//    hace que NO sea «volver» ni «duda»;
//  - nunca con dígitos ni con más de 6 palabras para la duda (8 para el «sí»);
//  - la tolerancia de edición vale solo para palabras de 5 letras o más (las de 4, por igualdad exacta) y hay una lista negra («deme», «dije», «debe»…);
//  - sin `tolerante` (pedido nuevo en curso) solo valen las formas cerradas y NUNCA se devuelve 'duda'.
function intencionDeVolver(norm, tolerante) {
  const palabras = norm.split(' ').filter(Boolean);
  if (!palabras.length || palabras.length > 8) return '';
  const DEJAR = ['dejalo', 'dejarlo', 'deja', 'dejar', 'deje', 'dejes', 'dejemoslo', 'dejala'];
  const NEGRAS = ['deme', 'dije', 'debe', 'debes', 'dejo', 'teja', 'reja', 'deben', 'dedo'];
  const esDejar = (w) => NEGRAS.indexOf(w) < 0 && DEJAR.some((k) => w === k || (w.length >= 5 && k.length >= 5 && distancia(w, k) <= 1));
  const esEstaba = (w) => w.length >= 5 && w.length <= 7 && distancia(w, 'estaba') <= 1;
  // Vocabulario cerrado del «sí»: lo único que puede decir quien pide dejarlo como estaba.
  const VOCAB = ['como', 'antes', 'igual', 'asi', 'nomas', 'mas', 'no', 'si', 'lo', 'la', 'que', 'te', 'dije', 'ya', 'mejor', 'por', 'favor', 'mi', 'pedido', 'anterior', 'pues', 'quiero', 'tenia', 'el', 'esta', 'estaba'];
  const VOCAB_DUDA = VOCAB.concat(['se', 'cual', 'era', 'puedo', 'podria', 'volver', 'vuelve']);
  const enVocab = (w, v) => v.indexOf(w) >= 0 || esDejar(w) || esEstaba(w);
  const todas = (v) => palabras.every((w) => enVocab(w, v));
  const hayDejar = palabras.some(esDejar);
  const hayEstaba = palabras.some(esEstaba);
  // Un rechazo («no lo dejes como estaba», «no quiero dejarlo») NUNCA es «volver»: con pedido nuevo en curso no es nada; al elegir de nuevo, se pregunta.
  const rechazo = /\bno (quiero|queremos|lo|me|vayas a|deseo)( (lo|me))? (dejar|dejarlo|dejalo|dejes|deje|deses)\b/.test(norm) || /\bno (quiero|queremos) (que )?(lo )?(dejes|dejen|dejemos)\b/.test(norm)
    // «no dejes como estaba», «ya no dejes…», «mejor no dejes…», «no la dejes», «no lo dejen», «no dejarlo», «no dejar…»: un «no» seguido (con «lo/la/me/se/te» a lo sumo) del verbo.
    // El imperativo afirmativo («no, déjalo…», «dejala», «deja») no está en la lista: «No déjalo como estaba no más.» sigue siendo «volver».
    || /\bno (lo |la |me |se |te )*(dejes|dejen|deje|deses|dejar|dejarlo|dejarla)\b/.test(norm)
    // …y con un error de tipeo o de voz en el verbo («no dejez», «no deges»): el verbo, dicho con una letra de más o de menos, tras un «no».
    || rechazoConTipeo(palabras);
  if (rechazo) return tolerante && !/\d/.test(norm) && palabras.length <= 6 && todas(VOCAB_DUDA) ? 'duda' : '';
  // Formas que no llevan el verbo (cerradas).
  const SIN_VERBO = /^((ya|no|si|mejor|pues|es que|entonces) )*(como estaba( antes)?|como antes|lo que tenia|lo anterior|el anterior|mi pedido anterior|(volver|vuelve|volvamos|regresa|regresar) (al|a mi|a el) (pedido )?(anterior|de antes)|(volver|vuelve|volvamos|regresa|regresar) a mi pedido|(manten|mantener|mantenlo|mantengamoslo|mantenga)( mi| el)?( pedido)?|(no|ya no) (quiero )?(cambiar|cambio)( nada)?|no cambiar nada|cancelar( el)? cambio|cancela( el)? cambio|olvida el cambio)( no mas| nomas| igual)?( por favor)?$/;
  if (SIN_VERBO.test(norm)) return 'si';
  // «dejar» + «como estaba» / «como antes» en una frase corta de vocabulario cerrado: la forma cerrada que vale siempre.
  const comoEstaba = (hayEstaba && palabras.indexOf('como') >= 0) || /\bcomo (antes|tenia)\b/.test(norm);
  if (hayDejar && comoEstaba && palabras.length <= 6 && todas(VOCAB)) return 'si';
  if (!tolerante || /\d/.test(norm)) return '';
  // Solo al elegir de nuevo: tolerancia a otras formas de vocabulario cerrado.
  if (hayDejar && todas(VOCAB) && (hayEstaba || /\b(antes|igual|asi|anterior|nomas|mas|tenia)\b/.test(norm))) return 'si';
  if (hayDejar && palabras.length <= 4 && palabras.every((w) => esDejar(w) || ['no', 'si', 'mejor', 'lo', 'ya', 'pues', 'por', 'favor', 'nomas', 'mas'].indexOf(w) >= 0)) return 'si';
  // Modismos y frases de conformidad con lo que había («así nomás», «está bien así», «así está bien», «nomás», «sin cambios», «no cambies nada»): SOLO aquí (al
  // elegir de nuevo, mensaje ENTERO de vocabulario cerrado). Un «no» seguido de «está bien» / «así» («no está bien», «no así») es un rechazo: se pregunta.
  const CONFORME = ['asi', 'nomas', 'esta', 'bien', 'ya', 'pues', 'si', 'ok', 'okey', 'bueno', 'dale', 'entonces', 'mejor', 'dejalo', 'dejarlo', 'sin', 'cambios',
    'no', 'cambies', 'nada', 'quiero', 'cambiar', 'por', 'favor'];
  if (palabras.every((w) => CONFORME.indexOf(w) >= 0)) {
    if (palabras.indexOf('no') >= 0) {
      if (/^((ya|pues|si|ok|okey|bueno|dale|entonces|mejor) )*(no cambies nada|no quiero cambiar nada)( por favor)?$/.test(norm)) return 'si';
      if (palabras.some((w) => ['asi', 'bien', 'esta'].indexOf(w) >= 0)) return 'duda';
    } else if (palabras.some((w) => ['asi', 'nomas', 'bien', 'cambios'].indexOf(w) >= 0)) {
      return 'si';
    }
  }
  // Habla de dejarlo o de lo de antes con palabras de vocabulario cerrado, pero no se entiende del todo: se pregunta (una vez), no se deriva.
  if (palabras.length <= 6 && todas(VOCAB_DUDA) && (hayDejar || hayEstaba || /\b(anterior|tenia)\b/.test(norm) || /\bcomo antes\b/.test(norm))) return 'duda';
  return '';
}

// Una lista de la configuración (arreglo o CSV) como arreglo de textos.
function lista(v) {
  const base = Array.isArray(v) ? v : String(v === undefined || v === null ? '' : v).split(/[,;|]/);
  return base.map((x) => String(x).trim()).filter(Boolean);
}

// ¿Está cerrado el restaurante ahora? Sin horario (o ilegible) no se bloquea nada.
function cerrado() {
  if (!String(cfg.horario || '').trim()) return false;
  const h = vmHorario(cfg.horario);
  if (!h) { errores.push('horario_ilegible'); return false; }
  const a = vmAbierto(h, ahora);
  return !(a && a.abierto);
}

function cartaDelNegocio() {
  return pdCarta(Array.isArray(cfg.catalogo) ? cfg.catalogo : [], {
    areasExcluidas: lista(cfg.areasExcluidas), moneda: cfg.moneda,
  });
}

function extraerPedido() {
  if (cerrado()) return salir('fuera_de_horario');
  const carta = cartaDelNegocio();
  // Sin carta cargada no hay pedido que tomar: lo único que se ofrece es pasar con el local.
  if (!carta.length) return salir('transferir', { motivo: 'carta sin cargar' });
  return salir('extraer_pedido', { cuerpoExtraccion: pdCuerpoExtraccion(texto, carta, { ahoraMs: ahora }) });
}

function extraerReserva() {
  return salir('extraer_reserva', { cuerpoExtraccion: rsCuerpoExtraccion(texto, { ahoraMs: ahora, zonas: lista(cfg.zonasReserva) }) });
}

// ¿El texto PIDE la ubicación o la dirección del LOCAL? Función pura sobre el texto ya normalizado con `vmNorm` (sin tildes, en minúsculas, sin signos).
// `restringido` = el flujo está pidiendo la dirección de ENTREGA del cliente (`pedido_datos` con delivery): ahí «ubicación» y «dirección» sueltas son
// DARLA y solo vale lo que nombra al local («dónde están», «del local», «de ustedes», «su dirección», «mapa», «link»).
// 1) NUNCA si da algo: un dígito, una marca de entrega («mi», «estoy en», «calle», «zona», «barrio», «frente a», «nro»…), «te paso…», un enlace pegado.
// 2) Pedidos expresos que nombran al local: «dónde están/queda(n)/se ubican/se encuentran/los encuentro», «dónde está el local», «ubicados», «cómo llego/
//    llegar/se llega», «dirección/ubicación del local/de ustedes», «su dirección», «mapa», «google maps», «link de la ubicación».
// 3) Fuera de lo restringido, el mensaje ENTERO de vocabulario cerrado con una palabra de dirección («ubicación», «pásame la ubicación», «k direccion»,
//    «cuál es la dirección»): una palabra ajena («cambiar la dirección», «dirección de entrega») hace que no sea esto. Con faltas habituales
//    («ubicasion», «direcion»). Las constantes van DENTRO de la función (lo declarado con `const` después del `return` del nodo no se inicializa).
function pideElLocal(n, restringido) {
  if (!n || n.length > 200 || /\d/.test(n)) return false;
  const DA = /\b(?:mi|mis|mio|mia|nuestra|nuestro)\b|\b(?:estoy|estamos|vivo|vivimos|trabajo|trabajamos) (?:en|por|cerca|frente|a)\b|\b(?:te|les|le) (?:paso|mando|envio|comparto|dejo|doy)\b|\b(?:ahi|aqui|aca) (?:va|esta|es|queda)\b|\b(?:adjunto|adjunta|entregar|entregalo|entreguen|entregue|entrega|entregas)\b|\b(?:llevalo|llevamelo|llevenlo|llevenmelo|envialo|enviamelo|envienlo|envienmelo|mandalo|mandamelo|mandenlo|mandenmelo|traelo|traemelo|traiganlo|traiganmelo) a\b|\b(?:calle|calles|avenida|av|avda|zona|barrio|esquina|frente|cerca|nro|numero|casa|edificio|condominio|urbanizacion|urb|piso|departamento|depto|oficina|porteria|referencia|referencias)\b|\bubicad[oa]s? (?:en|por|cerca|frente|a|atras|detras|al)\b|\bhttps?\b|\bwww\b|\bgoo gl\b|\bmaps app\b/;
  if (DA.test(n)) return false;
  const DIR = '(?:dir[ei]c{1,2}ion(?:es)?|ubi[ck]a[cs]ion(?:es)?)';
  const ESDIR = new RegExp('^' + DIR + '$');
  const LOCAL = '(?:local|locales|restaurante|negocio|tienda|sucursal|lugar|establecimiento)';
  const DONDE = '(?:donde|dnde|dnd|onde)';
  // Qué sigue a «dónde están/queda…»: «los tacos» o «mi pedido» no es el local; «el local» o «ustedes» sí.
  const sigueUnLocal = (resto) => {
    const w = resto.trim().split(' ').filter(Boolean);
    if (!w.length) return true;
    if (['mi', 'mis', 'tu', 'tus', 'los', 'las', 'unos', 'unas', 'pedido', 'orden'].indexOf(w[0]) >= 0) return false;
    if (['el', 'la', 'un', 'una'].indexOf(w[0]) >= 0) return new RegExp('^' + LOCAL + '$').test(w[1] || '');
    return true;
  };
  const dondeEstan = new RegExp('\\b' + DONDE + ' (?:estan|queda|quedan|se ubican|se ubica|se encuentran|se encuentra|los encuentro|las encuentro|los puedo encontrar|funcionan)\\b(.*)$').exec(n);
  if (dondeEstan && sigueUnLocal(dondeEstan[1])) return true;
  if (new RegExp('\\b' + DONDE + ' (?:esta|se ubica|queda) (?:el |la )' + LOCAL + '\\b').test(n)) return true;
  // Con la entrega del cliente en curso, «ubicados» y «cómo llego» solo cuentan junto a «dónde» o a un nombre del local («dónde están ubicados» sí; «ubicados por el centro» ya cayó arriba).
  const nombraAlLocal = new RegExp('\\b' + DONDE + '\\b|\\b' + LOCAL + '\\b').test(n);
  if (/\bubicad[oa]s?\b/.test(n) && (!restringido || nombraAlLocal)) return true;
  if (/\bcomo (?:llego|llegar|llegamos|llegare|se llega|puedo llegar|hago para llegar|podemos llegar|llegariamos)\b/.test(n) && (!restringido || nombraAlLocal)) return true;
  if (new RegExp('\\b' + DIR + ' (?:del|de el) ' + LOCAL + '\\b').test(n) || new RegExp('\\b' + DIR + ' de (?:ustedes|uds)\\b').test(n)) return true;
  // «Su dirección» (fuera de la entrega); dentro de ella solo como pregunta o pedido, por el vocabulario cerrado de abajo.
  if (!restringido && new RegExp('\\b(?:su|vuestra|vuestro|tu) ' + DIR + '\\b').test(n)) return true;
