} catch (e) { crmCfg = null; }
if (!crmActivo(crmSanearConfig(crmCfg))) return [];

const out = [];
$input.all().forEach((it, i) => {
  const e = it.json;
  const p = e.prospectoPlanilla;
  if (e.guardarPlanilla !== true || !p || typeof p !== 'object' || !p.telefono) return;
  out.push({ json: Object.assign({}, p), pairedItem: { item: i } });
});
return out;

