// `crm.activo === false` no se escribe ni se consulta Google.
const CRM_MAPA = {"_nota":"Mapa de columnas de la planilla miniCRM de Q'Taco (hoja Leads_CRM, encabezados en la fila 3), opcion (b) del 06/11/2026: SIN ampliar el contrato de columnas del core; las columnas son las de la plantilla actual. A..I y N..T las escribe el bot; J..M y U son del equipo (el bot no las toca ni lee la U). Q'Taco no usa Dia ni Horario preferido (quedan vacios). Los titulos tienen que coincidir letra por letra con la copia viva de la planilla.","filaEncabezados":3,"prefijoId":"LEAD-","primerId":1001,"columnas":{"id":{"letra":"A","titulo":"ID Lead"},"fecha":{"letra":"B","titulo":"Fecha Registro"},"nombre":{"letra":"C","titulo":"Nombre y Apellido"},"empresa":{"letra":"D","titulo":"Empresa / Cliente"},"telefono":{"letra":"E","titulo":"Teléfono WhatsApp"},"etapaInicial":{"letra":"F","titulo":"Etapa Funnel"},"origen":{"letra":"G","titulo":"Origen / Canal"},"calificacion":{"letra":"H","titulo":"Calificación IA"},"resumen":{"letra":"I","titulo":"Resumen Chatbot IA"},"clasificacion":{"letra":"N","titulo":"Clasificación"},"quePidio":{"letra":"O","titulo":"Qué pidió"},"diaPreferido":{"letra":"P","titulo":"Día preferido"},"horarioPreferido":{"letra":"Q","titulo":"Horario preferido"},"derivacion":{"letra":"R","titulo":"Derivación a recepción"},"ultimaInteraccion":{"letra":"S","titulo":"Última interacción"},"ventana24h":{"letra":"T","titulo":"Se cierra la ventana de 24 h"}},"equipo":{"valor":{"letra":"J","titulo":"Valor Estimado ($)"},"responsable":{"letra":"K","titulo":"Responsable Comercial"},"estado":{"letra":"L","titulo":"Estado Comercial"},"proximaAccion":{"letra":"M","titulo":"Próxima Acción / Fecha"},"diagnostico":{"letra":"U","titulo":"Diagnóstico del equipo"}},"extrasDelEquipo":{},"alCrear":{"etapaInicial":"1. Nuevo Lead","origen":"Chatbot WhatsApp IA","origenAnuncio":"Campaña Meta Ads","estado":"Activo"}};

