  const senales = p && p.senales !== null && typeof p.senales === 'object' ? p.senales : {};
  return CRM_CALIFICACION_DE[crmClasificar(senales)];
}
function crmResumirSenales(p, conEstado, calificacionFinal) {
  const partes = [];
  if (calificacionFinal === 'Descalificado') partes.push('Marcado como no lead.');
  // Solo marcas fijas: el texto libre del cliente (que pidio, dia, horario) va a SUS columnas, si el tenant las mapea, y no se copia aca.
  if (p.derivacion === true || (typeof p.derivacion === 'string' && crmLimpio(p.derivacion))) partes.push('Derivado a recepción.');
  if (!partes.length) return conEstado ? 'Escribió por WhatsApp.' : '';
  return partes.join(' ').slice(0, 400);
}
const CRM_ADAPTADOR = { calificar: crmCalificarSenales, resumir: crmResumirSenales, prioridad: CRM_ESCALA };

// ADAPTADOR DEL RESTAURANTE para «Decidir fila de la planilla» (miniCRM). Se concatena DESPUÉS de `adaptador-senales.js` (que define `CRM_ADAPTADOR`) y solo cambia el RESUMEN (columna I):
// si el prospecto trae `resumenVenta` (lo arma `vmProspectoCrm` desde el pedido que calculó el código), ese es el resumen. Sin él, al CREAR la fila rige el de las señales
// («Escribió por WhatsApp.») y al ACTUALIZAR no se toca la celda (una derivación o un primer contacto no borran el último pedido). Calificación y prioridad: las del adaptador general.
// NUNCA dice que alguien pagó. MENSAJES: ninguno.
const CRM_RESUMEN_SENALES = CRM_ADAPTADOR.resumir;
CRM_ADAPTADOR.resumir = function (p, conEstado, calificacionFinal) {
  const venta = p && typeof p.resumenVenta === 'string' ? crmLimpio(p.resumenVenta).slice(0, 200) : '';
  if (venta) return venta;
  return conEstado ? CRM_RESUMEN_SENALES(p, conEstado, calificacionFinal) : '';
};

// DECIDIR FILA DE LA PLANILLA: con lo que se leyo de la hoja, decide si el prospecto es una fila NUEVA o una que YA EXISTE, y arma lo que se escribe.
// La logica y el mapa de columnas estan en `crm.js` (modulo `crm`); como se califica y se resume, en el adaptador de captacion (`crm-captacion.js`).
//
// SE LEE LO MINIMO. Dos lecturas chicas: `Buscar teléfono en planilla` (solo las filas de ESTE telefono, solo las columnas del bot: nunca las del equipo)
// y `Leer IDs de la planilla` (solo la columna del ID). No escribe: eso lo hacen `Agregar fila` y `Actualizar fila`, segun `accionPlanilla`. Sin modelo.
// MENSAJES: ninguno.
// El adaptador: `CRM_ADAPTADOR` si el paquete lo trae (adaptador-senales.js); si no, el de captacion (capCalificar, capResumir, CAP_PRIORIDAD).
// «Leer encabezados de la planilla» es de la rama `ramaCrm`: con el paquete de senales es OBLIGATORIO (sin la lectura no se agrega: cierra en falla);
// en captacion y chat, que no la tienen, rige la comprobacion de siempre (`encabezados` indefinido).
const exigeEncabezados = typeof CRM_ADAPTADOR !== 'undefined';
let encabezados = exigeEncabezados ? [] : undefined;
try {
  const leidos = $('Leer encabezados de la planilla');
  if (leidos.isExecuted !== false) encabezados = leidos.all();
} catch (e) { /* el nodo no existe en este flujo */ }
return crmDecidirFila({
  prospectos: $('Prospecto para la planilla').all(),
  busqueda: $('Buscar teléfono en planilla').all(),
  lecturaIds: $('Leer IDs de la planilla').all(), // por nombre: con «Leer encabezados» en medio, $input ya no es la lectura de IDs
  mapa: CRM_MAPA,
  encabezados,
  adaptador: typeof CRM_ADAPTADOR !== 'undefined' ? CRM_ADAPTADOR : { calificar: capCalificar, resumir: capResumir, prioridad: CAP_PRIORIDAD },
  ahoraMs: Date.now(),
});

// FUENTES DEL GUARDADO: las arma Flujos/experimental/comun-sin-agente/src/guardado.mjs para este flujo (nombres de nodo literales, para que n8n los precargue).
const GM_FUENTES = {
  carga: $('Carga de entrada').isExecuted ? $('Carga de entrada').first().json : {},
  config: $('Config del negocio').isExecuted ? $('Config del negocio').first().json : {},
};

// PREPARAR GUARDADO (módulo común de medios, contrato v2 «guardar y descargar TODO» del 30/10/2026 §1 y §4): decide si el medio de ESTE mensaje
// entrante se guarda y con qué cabeceras.
//
// Corre en su PROPIA rama, colgada de «Reportar mensaje (entrante)» (el servidor exige el entrante ya registrado por la ingesta) y DEBAJO de la rama que
// responde en el lienzo: con `executionOrder: v1` corre DESPUÉS de que el cliente recibió su respuesta, y nada de lo que pase acá corta el turno.
// Devuelve [] (la rama termina en silencio) si el mensaje no trae un medio, o si le falta un dato que el servidor exige.
// TODO medio se guarda (decisión de Andres, 30/10): imagen, audio (y nota de voz), video, documento de CUALQUIER tipo y sticker (va como `image`, webp).
// Ya no hay modo Anotar. Cada uno se baja con SU PROPIA descarga de Meta (no gasta el tope diario de ver u oír). El flujo NO se adelanta al tope por tipo
// del servidor (imagen 5 MB, audio, video y documento 16 MB): solo deja de bajar lo que Meta informa por encima de 16 MiB (`limite`), que cuenta como 413.
// `mime` es el que declara Meta SOLO si está en la lista cerrada de abajo; si no, `application/octet-stream` (el servidor decide por los bytes). Viaja en
// `X-NovuChat-Mime`. `contentType` (el transporte): imagen y audio, ese mismo mime; video y documento SIEMPRE `application/octet-stream`, para que el
// framework de la Function no intente parsear el cuerpo (un documento declarado application/json, form o multipart daría 400 antes del handler).
// También anota, en el estado estático del flujo (clave `guardadoDeMedios`), cuándo escribió por última vez la RECEPCIÓN: es la ventana de 24 h que
// decide si el aviso de falla puede salir como texto libre. Ningún dato del cliente se guarda ahí.
// Este nodo NO toca el binario: no lo hay todavía (se baja después) y nunca lo lee.
//
// `GM_FUENTES` la define la cabecera que arma `guardado.mjs` para cada flujo (`carga`: el nodo con `messages`; `config`: «Config del negocio»).
// JavaScript plano del nodo Code de n8n: sin require, URL, Buffer ni crypto.
const gmCarga = (GM_FUENTES && GM_FUENTES.carga && typeof GM_FUENTES.carga === 'object') ? GM_FUENTES.carga : {};
const gmCfg = (GM_FUENTES && GM_FUENTES.config && typeof GM_FUENTES.config === 'object') ? GM_FUENTES.config : {};
const gmMsg = Array.isArray(gmCarga.messages) && gmCarga.messages[0] && typeof gmCarga.messages[0] === 'object' ? gmCarga.messages[0] : null;
const gmAhora = Number(gmCarga.ahoraMs) > 0 ? Number(gmCarga.ahoraMs) : Date.now();
const gmSd = $getWorkflowStaticData('global');
if (!gmSd.guardadoDeMedios || typeof gmSd.guardadoDeMedios !== 'object' || Array.isArray(gmSd.guardadoDeMedios)) gmSd.guardadoDeMedios = {};
const gmEstado = gmSd.guardadoDeMedios;
if (!gmMsg) return [];

const gmTelefono = String(gmMsg.from || '');
const gmRecepcion = String(gmCfg.numeroRecepcionDigitos || gmCfg.numeroRecepcion || '').replace(/\D/g, '');
// La ventana de la recepción: su último mensaje a este número (de cualquier tipo).
if (gmRecepcion && gmTelefono === gmRecepcion) gmEstado.recepcionMs = gmAhora;

// El tipo del mensaje de WhatsApp → la categoría que se manda en `X-NovuChat-Tipo` (contrato v2 §1: image | audio | video | document).
const GM_TIPOS = { image: 'image', sticker: 'image', audio: 'audio', voice: 'audio', video: 'video', document: 'document' };
const gmTipoMeta = String(gmMsg.type || '');
const gmTipo = Object.prototype.hasOwnProperty.call(GM_TIPOS, gmTipoMeta) ? GM_TIPOS[gmTipoMeta] : '';
if (!gmTipo) return [];
const gmMedio = gmMsg[gmTipoMeta] || (gmTipo === 'audio' ? (gmMsg.audio || gmMsg.voice) : null);
if (!gmMedio || typeof gmMedio !== 'object') return [];
const gmMediaId = String(gmMedio.id || '');
const gmIdMeta = String(gmMsg.id || '');
// Lo que el servidor exige (§1): teléfono de 8 a 15 dígitos y el id del MENSAJE. Lo que viaja en una cabecera, sin espacios ni controles.
if (!/^\d{8,15}$/.test(gmTelefono) || !/^[\x21-\x7e]{1,200}$/.test(gmIdMeta) || !/^[A-Za-z0-9_-]{1,100}$/.test(gmMediaId)) return [];
const gmMimeCrudo = String(gmMedio.mime_type || '').toLowerCase().split(';')[0].trim();
// La lista CERRADA de mimes que viajan tal cual en `Content-Type`; cualquier otro (o uno de otra categoría) va como application/octet-stream.
const GM_MIMES = {
  image: ['image/jpeg', 'image/png', 'image/webp'],
  audio: ['audio/ogg', 'audio/opus', 'audio/mp4', 'audio/m4a', 'audio/x-m4a', 'audio/mpeg', 'audio/aac', 'audio/amr'],
  video: ['video/mp4', 'video/3gpp'],
  document: [
    'application/pdf', 'application/zip', 'text/plain', 'text/csv',
    'application/msword', 'application/vnd.ms-excel', 'application/vnd.ms-powerpoint',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  ],
};
const gmMime = GM_MIMES[gmTipo].indexOf(gmMimeCrudo) >= 0 ? gmMimeCrudo : 'application/octet-stream';
const gmContentType = gmTipo === 'image' || gmTipo === 'audio' ? gmMime : 'application/octet-stream';
// 16 MiB: lo más grande que el flujo baja (Meta permite documentos de 100 MB; manda el tope de Andres). El tope por tipo lo impone el servidor.
const GM_LIMITE = 16 * 1024 * 1024;
// Video y documento pueden pesar hasta 100 MB en WhatsApp: sin un tamaño informado por Meta NO se bajan (revisión de seguridad de #713). Imagen, audio y
// sticker se bajan igual: el servidor ya los acota por tipo.
const GM_EXIGE_TAMANO = gmTipoMeta === 'video' || gmTipoMeta === 'document';

return [{ json: {
  telefono: gmTelefono,
  idMeta: gmIdMeta,
  tipo: gmTipo,
  contentType: gmContentType,
  mime: gmMime,
  mediaId: gmMediaId,
  limite: GM_LIMITE,
  exigeTamano: GM_EXIGE_TAMANO,
  // A quién iría el aviso de falla (el número del NEGOCIO, no del cliente).
  recepcion: gmRecepcion,
  ahoraMs: gmAhora,
} }];

// PREPARAR REINTENTO (módulo común de medios, contrato v2 del 30/10/2026): `guardarMedio` respondió un 5xx (502 no_se_guardo, no_se_registro u otro):
// se reintenta UNA vez, con el mismo pedido. El servidor reconoce el repetido por el id del mensaje.
// Arma el ítem del reintento: los datos de «Preparar guardado» y la REFERENCIA al mismo binario `data` de «Descargar medio (guardado)» (no se vuelve a
// pedir a Meta). NO LEE el binario: copia el objeto que n8n le da (su id en el almacén de binarios) sin abrir su contenido. Un medio a la vez: un ítem.
// JavaScript plano del nodo Code de n8n: sin require, ni los globales de Node.
const rpPrep = $('Preparar guardado').first().json || {};
const rpItem = { json: Object.assign({}, rpPrep, { intento: 2 }) };
if ($('Descargar medio (guardado)').isExecuted) {
  const rpBajado = $('Descargar medio (guardado)').first();
  if (rpBajado && rpBajado.binary && rpBajado.binary.data) rpItem.binary = { data: rpBajado.binary.data };
}
return [rpItem];

// RESULTADO DEL GUARDADO (módulo común de medios, contrato v2 «guardar y descargar TODO» del 30/10/2026 y §2 del contrato del 29/10): lee la respuesta
// de `guardarMedio` y decide el AVISO DE FALLA.
//
// Toda respuesta termina acá y NINGUNA corta el turno (el cliente ya recibió su respuesta: esta rama corre después).
//   200 {ruta, repetido} · 400 · 401 · 405 · 409 (guardado_apagado, sin_mensaje, en_curso, {estado}) → silencio (devuelve []).
//   Registrados en el estado estático, sin aviso y sin datos del paciente (`guardadoDeMedios.<clave> = {dia, n}`): 401 (token rotado o número equivocado)
//   → `sinAcceso`; un 400 (telefono_invalido, falta_idmeta, tipo_invalido, vacio) → `pedidoInvalido`; una descarga de Meta que falló (sin respuesta del
//   servidor, tamaño dentro del límite) → `sinDescarga`.
//   413 demasiado_grande · 415 tipo_no_admitido · 429 cupo_diario_lleno | cupo_telefono_lleno · 502 no_se_guardo|no_se_registro (o cualquier 5xx), YA
//   REINTENTADO una vez → aviso a la recepción, si se puede.
//   Un medio que Meta informó más grande que 16 MiB NO se baja: cuenta como 413 sin llamar al servidor.
//   Un video o documento sin tamaño informado por Meta (ausente o 0) tampoco se baja: se registra en `sinTamano` y avisa como falla de tamaño.
//   Un corte de red, un error de Meta o una respuesta que no se entiende → silencio (no hay motivo cierto que decirle a la recepción).
// EL AVISO: texto libre a la recepción del negocio SOLO si su ventana de 24 h está abierta (escribió hace menos de 23 h 30 min: lo anota «Preparar guardado»),
// a lo más UNO por ejecución y día de La Paz (UTC-4 fijo) y por comercio (el estado estático es del flujo, que es de un solo comercio): con ejecuciones
// CONCURRENTES (un álbum de 3 fotos son 3 ejecuciones que leen el estado a la vez) pueden salir varios el mismo día. n8n no da un candado real; queda
// acotado porque el aviso no lleva datos del paciente y solo sale con la ventana de la recepción abierta. Y SIN datos del paciente:
// ni teléfono, ni nombre, ni el archivo, ni el id del mensaje. Solo el motivo. El día se marca ANTES de enviar: si Meta lo rechaza, ese día no se reintenta.
// Si Meta rechaza el aviso, la ejecución termina en ERROR (el envío no traga el fallo); la rama corre al final, cuando el cliente ya recibió su respuesta.
// Este nodo NO toca el binario.
// JavaScript plano del nodo Code de n8n: sin require, URL, Buffer ni crypto.
const grPrep = $('Preparar guardado').first().json || {};
const grUrl = $('Pedir el medio a Meta (guardado)').isExecuted ? ($('Pedir el medio a Meta (guardado)').first().json || {}) : {};
const grR = ($input.first() && $input.first().json) || {};
const grCodigo = Number(grR.statusCode) || 0;
const grCuerpo = grR.body && typeof grR.body === 'object' ? grR.body : {};
const grSd = $getWorkflowStaticData('global');
if (!grSd.guardadoDeMedios || typeof grSd.guardadoDeMedios !== 'object' || Array.isArray(grSd.guardadoDeMedios)) grSd.guardadoDeMedios = {};
const grEstado = grSd.guardadoDeMedios;
const grAhora = Number(grPrep.ahoraMs) > 0 ? Number(grPrep.ahoraMs) : Date.now();
const grHoy = new Date(grAhora - 4 * 3600 * 1000).toISOString().slice(0, 10);
const grRegistrar = (clave) => {
  const previo = grEstado[clave] && grEstado[clave].dia === grHoy ? Number(grEstado[clave].n) || 0 : 0;
  grEstado[clave] = { dia: grHoy, n: Math.min(previo + 1, 1000) };
};
if (grCodigo === 400) { grRegistrar('pedidoInvalido'); return []; }
if (grCodigo === 401) { grRegistrar('sinAcceso'); return []; }
const GR_MOTIVOS = {
  413: 'el archivo supera el tamaño permitido',
  415: 'el tipo de archivo no se admite',
  429: 'se llenó el cupo diario de archivos del comercio',
  '429t': 'se llenó el cupo diario de archivos de una conversación',
  '413s': 'no se pudo comprobar su tamaño',
  502: 'el servidor no pudo guardarlo',
};
// Un 5xx llega acá DESPUÉS del único reintento («Reintentar el guardado»): si sigue fallando, es «el servidor no pudo guardarlo».
let grMotivo = Object.prototype.hasOwnProperty.call(GR_MOTIVOS, grCodigo) ? GR_MOTIVOS[grCodigo] : (grCodigo >= 500 && grCodigo <= 599 ? GR_MOTIVOS[502] : '');
// El cupo por teléfono (100 medios o 500 MiB por día, contrato v2 §7.4) tiene su propio motivo; sigue sin decir CUÁL conversación.
if (grCodigo === 429 && grCuerpo.error === 'cupo_telefono_lleno') grMotivo = GR_MOTIVOS['429t'];
// El medio que no se bajó por tamaño (Meta lo informó por encima de 16 MiB): es un 413 aunque el servidor no lo haya visto.
const grTamano = Number(grUrl.file_size);
if (!grMotivo && grCodigo === 0 && Number(grPrep.limite) > 0 && grTamano > Number(grPrep.limite)) grMotivo = GR_MOTIVOS[413];
// Video o documento sin tamaño informado (Meta sí respondió con su URL): no se bajó a propósito; se registra y avisa como falla de tamaño.
if (!grMotivo && grCodigo === 0 && grPrep.exigeTamano === true && grUrl.url && !(grTamano > 0)) { grRegistrar('sinTamano'); grMotivo = GR_MOTIVOS['413s']; }
// Sin respuesta del servidor (Meta no dio la URL o no dejó bajar el archivo): no se sabe más, se registra sin aviso.
if (!grMotivo && grCodigo === 0) { grRegistrar('sinDescarga'); return []; }
if (!grMotivo) return [];

const GR_VENTANA_MS = 23 * 3600 * 1000 + 30 * 60 * 1000;
const grRecepcionMs = Number(grEstado.recepcionMs) || 0;
const grVentanaAbierta = grRecepcionMs > 0 && grAhora >= grRecepcionMs && grAhora - grRecepcionMs < GR_VENTANA_MS;
if (grEstado.avisoDia === grHoy || !grVentanaAbierta) return [];
const grRecepcion = String(grPrep.recepcion || '').replace(/\D/g, '');
if (!/^\d{6,20}$/.test(grRecepcion)) return [];
grEstado.avisoDia = grHoy;
return [{ json: {
  numeroRecepcion: grRecepcion,
  texto: 'No se pudo guardar un archivo de una conversación (' + grMotivo + '). Revísala en la Consola.',
} }];
